window.__D("text/torat-shmuel/c051",{"p":[[2000480460,"חפץ, וזהו שארז\"ל בג' לשונות של חיבה<sup data-n=\"4780\">50</sup> חיבב הקב\"ה את ישראל בדביקה בחשיקה ובחפיצה וכולן אין למדין אלא מפרשותו של אותו הרשע ותדבק נפשו<sup data-n=\"4781\">51</sup>, שכם בני חשקה<sup data-n=\"4782\">52</sup>, כי חפץ<sup data-n=\"4783\">53</sup>, דענין חפץ הוא חשיקה ודביקה עד שיתאחד ויהי' אחד ממש והוא בחי' תעלומות לב.\n<b>ושרש</b> ענין החפץ הנה חפץ הוא פנימיות הרצון<sup data-n=\"4784\">54</sup> וכמ\"ש ועמך לא חפצתי<sup data-n=\"4785\">55</sup> ולא כתי' לא רציתי דר\"ל דבכל מה שעמך שטפל ובטל לך וכמ\"ש כי עמך מקור חיים<sup data-n=\"4786\">56</sup> אפי' מקור החיים מקור התענוגי' ג\"כ טפל ובטל לך, וא\"כ אינו שייך שיחפץ בה דמאחר שהוא טפל ובטל, דעת להבין נקל<sup data-n=\"4787\">57</sup> שיחפוץ יותר באוא\"ס עצומ\"ה, וכל מה שצריכים על צד ההכרח שייך בזה רצון שהוא חיצוניות וכמארז\"ל כופין אותו עד שיאמר רוצה אני<sup data-n=\"4788\">58</sup>, ומאחר שכופין אותו ה\"ז שלא ברצונו, כ\"א ע\"צ ההכרח ומ\"מ נק' רצון שהוא חיצוניות הרצון, משא\"כ חפץ שהוא פנימיות הרצון אינו כ\"א לאוא\"ס עצומ\"ה לבד, וב' בחי' אלו הם מקור ב' בחי' נקודא בהיכלא, דאי' בכהאריז\"ל דגולגלתא (בפ\"א דמקיף את) דחפיא על מוחא הוא בינה והמוח שגנוז בתוכו הוא בחי' חכ'<sup data-n=\"4789\">59</sup> ושרש החכ' מבחי' ח\"ס יש שם ג\"כ ב' בחי' אלו גולגלתא שהוא בחי' רצון<sup data-n=\"4790\">60</sup> ומו\"ס בחי' חפץ פנימיות הרצון, וע\"י העבודה יכולים להמשיך ב' בחי' אלו רצון וחפץ, וזהו לפני ה' תטהרו בגימ' כתר<sup data-n=\"4791\">61</sup> שממשיכים ב' הב'<sup data-n=\"4792\">62</sup> שבכתר פנימיות וחיצוניות, וזהו מאד עמקו מחשבותיך<sup data-n=\"4793\">63</sup> סתם מח' הוא בחי' חכ' דמח' ויובלא לא אתפרש לעלמין<sup data-n=\"4794\">64</sup> יובל בחי' שער הנו\"ן דבינה<sup data-n=\"4795\">65</sup> ומח' חכ', מאד עמקו מח' שבבחי' עומק המח' יש ג\"כ ב' בחי' אלו, וזהו ממעמקים ב' עומקים ואי' בזהר ב' לשונות ע\"ז עומקא דכולא עומקא דבירא<sup data-n=\"4796\">66</sup> והם ב' יסודות דחו\"ב ונמשך מלמעלה ב'",[["4780","50","<b>בג' לשונות של חיבה</b>: ראה ב\"ר פ\"פ, ז. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים הערה 103."],["4781","51","<b>ותדבק נפשו</b>: וישלח לד, ג."],["4782","52","<b>שכם בני חשקה</b>: וישלח שם, ח."],["4783","53","<b>כי חפץ</b>: שם לד, יט."],["4784","54","<b>חפץ הוא פנימיות הרצון</b>: ראה שו\"ת הצ\"צ אבהע\"ז ח\"ב סרס\"ג (ח, ג). לקו\"ת שה\"ש כח, ד. וש\"נ. תו\"ח בא ח\"א קכה, ד ובהערה 597. סה\"מ ליקוט ח\"ב ע' רעו."],["4785","55","<b>ועמך לא חפצתי</b>: תהלים עג, כה."],["4786","56","<b>כי עמך מקור חיים</b>: תהלים לו, י. ראה לקו\"ת אמור לא, ד. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 50."],["4787","57","<b>דעת להבין נקל</b>: ע\"פ משלי יד, ו."],["4788","58","<b>כופין אותו עד שיאמר רוצה אני</b>: תו\"כ ופרש\"י ויקרא א, ג. ערכין כא, א במשנה. ראה סה\"מ מלוקט ו' ע' צט הערה 81."],["4789","59","<b>בכהאריז\"ל דגולגלתא. . בינה. . חכ'</b>: ראה קול ברמה לזהר אד\"ר נשא קכט, א (מהדורת קארעץ תקמ\"ה כב, א ד\"ה ספר דרושים)."],["4790","60","<b>גולגלתא שהוא בחי' רצון</b>: ראה לקו\"ת שלח מח, ב. (לקמן בחלק ההנחות) הנחה ד\"ה אני לדודי הא' ובהערה 59."],["4791","61","<b>תטהרו בגימ' כתר</b>: בלקו\"ת אחרי כו, רע\"ד מציין לרמ\"ז ס\"פ אחרי."],["4792","62","<b>הב'</b>: אולי צ\"ל: הבחי'."],["4793","63","<b>מאד עמקו מחשבותיך</b>: תהלים צב, ו."],["4794","64","<b>דמח' ויובלא לא אתפרש לעלמין</b>: ראה זהר ח\"ש קכג, א."],["4795","65","<b>יובל בחי' שער הנו\"ן דבינה</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"י מערכת יובל. אוה\"ת בהר כרך ב ע' תרט. נצבים ע' א'רעג."],["4796","66","<b>בזהר. . עומקא דכולא עומקא דבירא</b>: בשלח סג, ב."]]],[2000480461,"בחי' רצון וחפץ [בפ\"א וידוע [דשרש] היסוד למעלה ממוחין] וזהו בחי' איתן וע\"ז כתיב משכיל לאיתן האזרחי<sup data-n=\"4797\">67</sup> פי' שיזרח בנש\"י לע\"ל, דלע\"ל יומשך בחי' איתן למטה.\n<b>אך</b> מעין והארה מבחי' זו יכולים להמשיך עכשיו ג\"כ, דמאחר דבחי' פנימיות הלב ישנו בכל נפש מישראל הרי יכול להמשיך אותו מהעלם לידי גילוי, והוא בהתעורר ר\"ר על נפשו דכל נפש מישראל שרשה הגבה למעלה מאד וירדה למטה מטה בגוף ונה\"ב המעלים ומסתיר א\"כ גדלה הרחמנות על הנפש מאד, וכמו שמבואר במ\"א בענין האבות<sup data-n=\"4798\">68</sup> הן המרכבה<sup data-n=\"4799\">69</sup> שהמשיכו לבניהם אחריהם (בפ\"א דור אחר דור) נר\"ן לבי\"ע והוא בחי' פנימיות הלב לכן כאו\"א מאן דהוא אם בשם ישראל יכונה<sup data-n=\"4800\">70</sup> אפי' קל שבקלים ופושע ישראל יוכל להמשיך בזווגו נפש דמל' דמל' דעשי'<sup data-n=\"4801\">71</sup> אף שהוא ממדרי' הפחותות והתחתונות דעשי' מ\"מ מאחר שנכלל בכלל ע\"ס דקדושה יש בו התכללות וא\"כ יש בו בחי' חכ' ג\"כ ומלובש בו מל' דאצי', וגם דהנה אימא תתאה מקננא בעשי'<sup data-n=\"4802\">72</sup> ובמל' דאצי' מלובש חכ' עילאה שבו שורה אוא\"ס דחכ' הוא אחד האמת כח מה<sup data-n=\"4803\">73</sup> שבו שורה אוא\"ס, וא\"כ הרי יש בכאו\"א בחי' תעלומות לב, וכשאינו יכול להוציא אותו מכח אל הפועל בתוך תוך פנימיות נקודות לבו הרי הרחמנות על הנפש גדול מאד וכמו א' שחבוש בבית אסורים הרי גדלה הרחמנות עליו, וכמו\"כ כאן מה יוכל להיות בית אסורים יותר מזה שהוא חבוש ביד עצמו בל\"א אין זיך, שהכח שיש לו אינו יכול להוציא אותו לידי פועל.\n<b>וביאור</b> הענין הנה כתי' כה אמר ה' לבית יעקב<sup data-n=\"4804\">74</sup> אשר פדה את אברהם, יעקב הי' מרכבה לבחי' התפארת<sup data-n=\"4805\">75</sup> שהוא מדות הרחמים<sup data-n=\"4806\">76</sup>, ואברהם הוא בחי' האהבה המוסתרת שנת\"ל שהיא ירושה לנו מאבותינו<sup data-n=\"4807\">77</sup> והראשון הוא אברהם<sup data-n=\"4808\">78</sup>",[["4797","67","<b>משכיל לאיתן האזרחי</b>: תהלים פט, א. ראה גם לקו\"ת פ' ראה יח, סע\"א. מאמרי אדה\"ז הקצרים ע' עג. וש\"נ. ע' עד."],["4798","68","<b>בענין האבות</b>: ראה תניא פי\"ח."],["4799","69","<b>האבות הן המרכבה</b>: ראה ב\"ר פמ\"ז, ו. פפ\"ב, ו. מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. תו\"ח נח מט, ד ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."],["4800","70","<b>אם בשם ישראל יכונה</b>: ראה גם לקו\"ש י\"ב תמוז כרך ח ע' 329 ואילך."],["4801","71","<b>נפש דמל' דמל' דעשי'</b>: ראה גם לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 11."],["4802","72","<b>אימא תתאה מקננא בעשי'</b>: ראה ת\"ז ת\"ו (כג, א)."],["4803","73","<b>דחכ'. . כח מה</b>: זהר רע\"מ צו כח, א. לד, א. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 39. ד\"ה וירא העם וינועו על יד הערה 66."],["4804","74","<b>כה אמר ה' לבית יעקב</b>: ישעי' כט, כב [ושם: אל בית]. ראה תניא פמ\"ה. ראה גם לקמן הערה 116."],["4805","75","<b>יעקב שהי' מרכבה לבחי' התפארת</b>: ראה לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 16."],["4806","76","<b>התפארת שהוא מדות הרחמים</b>: ראה זח\"א בהשמטות רנא, ריש ע\"ב. פרדס שעה\"כ שכ\"ג, פ\"כ מערכת רחמים."],["4807","77","<b>האהבה המוסתרת. . מאבותינו</b>: ראה תניא פי\"ח."],["4808","78","<b>האהבה. . אברהם</b>: ראה גם סידור שער הסוכות רנט, ג. תו\"ח תצוה ח\"ב שסד, א. וש\"נ."]]],[2000480462,"והאהבה היא מוסתרת ונעלמת עד מאד, ויעקב הוא פודה את אברהם ע\"י התעוררות ר\"ר על נפשו, דשרש הנפש מבחי' ח\"ע דכל נפש ונפש מישראל שרשו מבחי' א\"ס חיי החיים<sup data-n=\"4809\">79</sup> וירדה למטה בגוף ונה\"ב שהגוף הוא ממישכא דחיוויא<sup data-n=\"4810\">80</sup> והוא מרוחק לגמרי מבחי' אור פני מלך חיים<sup data-n=\"4811\">81</sup> ומלך עולם, וכשיתבונן כל אדם היטב הרי ימצא מח' אשר לא לה' המה ומכ\"ש כשימצא דיבור ומכ\"ש מעשה אשר לא לה' המה וע\"ז כתי' מלך אסור ברהטים ברהיטא מוחא<sup data-n=\"4812\">82</sup> וגם המלך אסור כו' דכתי' יעקב חבל נחלתו<sup data-n=\"4813\">83</sup> כמו החבל כשמושכין קצה הא' נמשך גם קצה השני<sup data-n=\"4814\">84</sup> כמו\"כ ברהיטי מוחא גם המלך אסור והו\"ע גלות השכינה גלו לבבל שכינה עמהם<sup data-n=\"4815\">85</sup> וכמ\"ש השוכן אתם בתוך טומאותם<sup data-n=\"4816\">86</sup> דכמו בקדושה כתי' ושכנתי בתוכם בתוך כ\"א ואחד<sup data-n=\"4817\">87</sup> כמו\"כ כתי' השוכן אתם בתוך כו' שכינה עמהם. והעצה לזה יעזוב רשע דרכו<sup data-n=\"4818\">88</sup> ואיש און מחשבותיו וישוב אל ה' וירחמיהו, שיעורר ר\"ר על בחי' שם דהוי' (ר\"ל בחי' מל' שנק' שם ה') וזהו מדתו של יעקב.\n<b>דהנה</b> כתי' ויצא יעקב מבאר שבע<sup data-n=\"4819\">89</sup> וילך חרנה ומהו\"ע ההילוך ומה שלחו יצחק לחרן<sup data-n=\"4820\">90</sup>, אך הענין הוא לברר בירורים, ואח\"כ כתי' ויהי כאשר ראה יעקב את רחל<sup data-n=\"4821\">91</sup> כו' וישק יעקב לרחל וישא קולו ויבך<sup data-n=\"4822\">92</sup>, דהנה רחל הוא כנס\"י<sup data-n=\"4823\">93</sup> מקור כללות נש\"י והיא עקרת הבית<sup data-n=\"4824\">94</sup> עיקרא דביתא דיעקב וכמו שטען יעקב הלא ברחל עבדתיך<sup data-n=\"4825\">95</sup> כו' שעיקר עבודת הבירורים שלו הי' בשביל רחל<sup data-n=\"4826\">96</sup>,",[["4809","79","<b>חיי החיים</b>: יומא עא, א. ראה גם תניא פמ\"ד (סג, א)."],["4810","80","<b>ממישכא דחיוויא</b>: ראה תניא פל\"א (מ, ב) ובמ\"מ הגהות והע\"ק שם. ס' שיעורים בספר התניא פמ\"ה ע' 613 הערה 3. הנסמן באוה\"ת חוקת כרך ו ע' א'תתצג־ מאמרי אדה\"א נ\"ך ע' תלד."],["4811","81","<b>אור פני מלך חיים</b>: ע\"פ משלי טז, טו."],["4812","82","<b>מלך אסור ברהטים ברהיטא מוחא</b>: שה\"ש ז, ו. ת\"ז בהוספות תקונא שתיאה קמד, ב. ראה גם מאמרי אדה\"א דברים ח\"א ע' לב. וש\"נ. פיה\"מ נח, א. אוה\"ת נצבים ריש ע' א'קצו."],["4813","83","<b>יעקב חבל נחלתו</b>: האזינו לב, ט."],["4814","84","<b>כמו החבל. . קצה השני</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 58."],["4815","85","<b>גלו לבבל שכינה עמהם</b>: מכילתא בא יב, מב. ספרי בהעלותך י, לה. מסעי לה, לד. מגילה כט, א. ראה גם לקו\"ש ב' ניסן כרך ז ע' 210 הערה 29."],["4816","86","<b>השוכן אתם בתוך טומאותם</b>: אחרי טז, טז וברש\"י שם. יומא נו, ב. ספרי ורש\"י מסעי לה, לד."],["4817","87","<b>ושכנתי בתוכם בתוך כ\"א ואחד</b>: תרומה כה, ח. ראה אלשיך שם. לקו\"ש בא כרך כו ע' 83 הערה 49. שם תרומה ע' 173 הערה 45. טור ברקת הל' יו\"ט סתק\"כ (סג, א). טור יהלום יו\"ד סשס\"ג, ס\"ז (ב, ג). מאמרי אדמו\"ר הצ\"צ תרי\"ד ע' ו בשם הה\"מ."],["4818","88","<b>יעזוב רשע דרכו</b>: ישעי' נה, ז."],["4819","89","<b>ויצא יעקב מבאר שבע</b>: ויצא כח, י."],["4820","90","<b>יעקב. . שלחו יצחק לחרן</b>: תולדות כח, א-ב ואילך."],["4821","91","<b>ויהי כאשר ראה יעקב את רחל</b>: ויצא כט, י."],["4822","92","<b>וישק יעקב לרחל וישא קולו ויבך</b>: ויצא כט, יא [ושם: את קולו — וכ\"ה בסמוך בפנים]. ראה גם סה\"מ תרכ\"ז ע' שפא. וש\"נ."],["4823","93","<b>רחל הוא כנס\"י</b>: ראה זהר וארא כט, ב. ב\"ר פע\"א, ב. תניא פמ\"ה. תו\"א מג\"א צד, ד."],["4824","94","<b>רחל. . עקרת הבית</b>: ראה ב\"ר שם. פע\"ג, ב. זהר ויצא קנד, א. קנז, ב. רש\"י ויגש מו, יט. רות ד, יא."],["4825","95","<b>הלא ברחל עבדתיך</b>: ויצא כט, כה [ושם: עבדתי עמך — ראה גם תו\"ח ויצא קעב, ד]."],["4826","96","<b>רחל. . שהיא מל'</b>: ראה זהר פינחס רמד, א. פרדס שער ערכי הכנויים שכ\"ג, פ\"כ מערכת רחל. מאו\"א מערכת רחל אות טז וראה ביאיר נתיב שם בסופו."]]],[2000480463,"ונק' כנס\"י (בפ\"א שהיא מל'<sup data-n=\"4827\">97</sup> ) ויעקב נק' ישראל<sup data-n=\"4828\">100</sup> שהוא<sup data-n=\"4829\">101</sup> ז\"א<sup data-n=\"4830\">99</sup> ) וכונס אורות דישראל דלעילא בתוכה<sup data-n=\"4831\">98</sup>, אך הנה רחל יש בו עוד פי' וכמ\"ש כרחל לפני גוזזי' נאלמה<sup data-n=\"4832\">102</sup> וכמ\"ש נאלמתי דומי' החשיתי<sup data-n=\"4833\">103</sup> והו\"ע ירידת הנשמה בגוף שאינו מאיר בבחי' דיבור, וכשראה יעקב את זאת התחיל לעורר ר\"ר עם מדתו שהוא מדת הרחמים, ועוד זאת וישא את קולו ויבך דכתי' הקל קול יעקב קלא קדמאה חסר ו' קלא בתראה<sup data-n=\"4834\">104</sup> מלא ו' ובחי' הקול הוא ממשיך שיהי' יעקב יוד עקב<sup data-n=\"4835\">105</sup> שהיו\"ד יומשך בבחי' עקביים ג\"כ (ע' בתו\"א פ' ויצא בביאור לד\"ה ושבתי בשלום<sup data-n=\"4836\">106</sup> ) וישא את קולו שהגביהו בבחי' רחמים פשוטים ר\"ר רב חסד<sup data-n=\"4837\">107</sup> שלמעלה מסדר השתל', וזהו אב הרחמן, אב הרחמים<sup data-n=\"4838\">108</sup>, אב הרחמן הוא רחמים דסדר השתל' מדתו של יעקב, אב הרחמים הם רחמים פשוטים שלמעלה מסדר השתל', וזהו וישא את קולו לבחי' רחמים גדולים רחמים פשוטים, ויבך הו\"ע מים תחתונים בוכים<sup data-n=\"4839\">109</sup> אנן בעינן למהוי קדם מלכא בחי' מקדם ומאז<sup data-n=\"4840\">110</sup>, וענין וישק יעקב לרחל הו\"ע התדבקות רוחא ברוחא<sup data-n=\"4841\">111</sup> וכמ\"ש ישקני מנשיקות פיהו<sup data-n=\"4842\">112</sup> ופרש\"י שהם טעמים תומ\"צ<sup data-n=\"4843\">113</sup> שיתגלו לע\"ל וכמ\"ש ושם נעשה לפניך כמצות רצונך<sup data-n=\"4844\">114</sup> שעיקר מצות רצונך יהי' לע\"ל דוקא, והארה מבחי' זו נמשך עתה ג\"כ והוא בחי' טל תחי'<sup data-n=\"4845\">115</sup> שמחי' הנשמה המלובשת בגוף, וזהו\"ע התדבקות רוחא ברוחא התקשרות מחדו\"מ במחדו\"מ",[["4827","97","<b>ונק' כנס\"י. . מל'</b>: ראה זהר בלק קצז, א."],["4828","100","<b>ויעקב נק' ישראל</b>: וישלח לב, כט. לה, י."],["4829","101","<b>שהוא ז\"א</b>: ראה ע\"ח שער פרצופי זו\"ן של\"א, פ\"א. שער הקליפות שמ\"ח, פ\"ג. שער הפסוקים וישלח לב, כט. שער היחוד ע' קלג, ואילך."],["4830","99","<b>מל'). . ז\"א)</b>: כ\"ה בגוכתי\"ק."],["4831","98","<b>כנס\"י. . וכונס אורות. . בתוכה</b>: ראה גם תו\"א תצוה פד, ב. סה\"מ תרל\"ח ע' תיט. וש\"נ."],["4832","102","<b>כרחל לפני גוזזי' נאלמה</b>: ישעי' נג, ז [ושם: וכרחל. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 244]."],["4833","103","<b>נאלמתי דומי' החשיתי</b>: תהלים לט, ג. ראה גם לקו\"ת צו ט, ב. מסעי פח, ג."],["4834","104","<b>הקל קול יעקב קלא קדמאה. . בתראה</b>: תולדות כז, כב. ראה הנסמן באוה\"ת וישב כרך ב ע' 526. כרך ה ע' 1788."],["4835","105","<b>יעקב יוד עקב</b>: ע\"ח שער סדר אצי' ש\"ג, פ\"ב. ראה תו\"א ר\"פ ויצא. מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח שמות ח\"א יח, ב. וש\"נ."],["4836","106","<b>בתו\"א. . ושבתי בשלום</b>: כב, א ואילך."],["4837","107","<b>רב חסד</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה עשה צדקה ומשפט ובהערות 115-114."],["4838","108","<b>אב הרחמן אב הרחמים</b>: ראה לקו\"ת ר\"ה סב, ד. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 14."],["4839","109","<b>מים תחתונים בוכים</b>: ראה ת\"ז ת\"ה (יט, ב). לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ט הערה 487."],["4840","110","<b>קדם. . מקדם ומאז</b>: ראה גם אוה\"ת חנוכה כרך ה' ע' 1864 שמציין ללקו\"ת פ' ראה יח א: מאז מקדם [ובלקו\"ת שם: מאז מעולם]. תו\"א ויקהל פז, ד."],["4841","111","<b>התדבקות רוחא ברוחא</b>: ראה זהר משפטים קכד, ב."],["4842","112","<b>ישקני מנשיקות פיהו</b>: שה\"ש א, ב."],["4843","113","<b>ופרש\"י שהם טעמים תומ\"צ</b>: ראה רש\"י שם. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 499."],["4844","114","<b>ושם נעשה לפניך כמצות רצונך</b>: מוסף ליו\"ט [בדילוג]. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת הב' ובהערה 9."],["4845","115","<b>טל תחי'</b>: ראה שבת פח, ב."]]],[2000480464,"דתורה, וזהו יעקב אשר פדה את אברהם<sup data-n=\"4846\">116</sup> במדתו של יעקב מדות הרחמים, והנה מעשה אבות סימן לבנים<sup data-n=\"4847\">117</sup> כמו\"כ יש בכוח כאו\"א מישראל לבוא לבחי' זו.\n<b>וזהו</b> בכל מאדך<sup data-n=\"4848\">118</sup> ויש בזה ב' פי' בזהר פי' בכל מאדך שהוא אהבה רבה שבלי גבול<sup data-n=\"4849\">119</sup> (בפ\"א וכמו שמבואר בחסידות בכ\"מ שבכל מאדך הוא רעותא<sup data-n=\"4850\">120</sup> דליבא<sup data-n=\"4851\">121</sup> בלי גבול) והוא בחי' תעלומות לב, ובמשנה פי' בכל מאדך בכל ממונך<sup data-n=\"4852\">122</sup> עשיות הצדקה בלי הגבלה, דכל המצות הם בהגבלה סוכה לא פחות מז\"ט ומשהו ולא יותר מך' אמה, שופר שיעורו טפח<sup data-n=\"4853\">123</sup>, לולב ד\"ט<sup data-n=\"4854\">124</sup> וכדומה ועצם החיוב דמצות הוא<sup data-n=\"4855\">125</sup> ג\"כ בהגבלה חומש ומעשר<sup data-n=\"4856\">126</sup>, ואף ע\"י עשיות המצוה בהגבלה הרי נת\"ל שעי\"ז נעשה וכל גבולך לאבני חפץ, אך ע\"י עשיות הצדקה למעלה מההגבלה הוא בחי' ריח העלאות מ\"ן לכח העליון שבנפש בחי' תעלומות לב, דאפי' כשבא לבחי' בכל מאדך שבלי גבול א\"ז בערך בחי' מאד העליון שהרי בכל מאדך כתי' מאד שלך<sup data-n=\"4857\">127</sup> אך בחסד ה' עלינו מאד האדם מעורר מאד העליון שבלי גבול, כמו\"כ ע\"י בחי' בכל מאדך בכל ממונך יבוא לבחי' מאדך בחי' תעלומות לב, ולכן אף שפנימיות הלב מתאחד עם המוחין מ\"מ כדי להוציא מכח אל הפועל הוא ע\"י צדקה, וזהו עטרת תפארת שיבה בדרך צדקה תמצא, תפארת שיבה הוא בחי' הדרת פנים יאר ה' פניו אליך בחי' יגת\"ד שיהי' נושא עון ועובר על פשע<sup data-n=\"4858\">128</sup> שהם המשכות המקיפים שיומשכו בפנימיות וכמשנת\"ל שע\"י צדקה ממשיכים המקיף בפנימי, וזהו עטרת תפארת שיבה בדרך צדקה תמצא כדי שיומשך המקיף בפנימי' הוא ע\"י צדקה דוקא בדרך צדקה תמצא כו'.",[["4846","116","<b>יעקב אשר פדה את אברהם</b>: ראה גם לעיל הערה 74. הערות לתיקונים לתניא ספל\"ב. תניא מ\"מ הגהות והע\"ק ספל\"ב. מאמרי אדה\"א הנחות תקע\"ז ע' ח. וש\"נ."],["4847","117","<b>מעשה אבות סימן לבנים</b>: ראה תו\"א וישלח כו, רע\"א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' צא. רמב\"ן לך יב, ו. לקו\"ש תולדות כרך כה ע' 123. וש\"נ."],["4848","118","<b>בכל מאדך</b>: ראה ואתחנן ו, ה."],["4849","119","<b>בכל מאדך. . בזהר. . שבלי גבול</b>: ראה זהר וארא כז, א."],["4850","120","<b>שבכל מאדך. . רעותא דליבא</b>: ראה לקו\"ת מטות פא, סע\"ג ואילך. ואתחנן י, ד. עקב טו, ג. שה\"ש מט, א ואילך. נא, א."],["4851","121","<b>רעותא דליבא</b>: זהר וירא ק, א."],["4852","122","<b>בכל מאדך. . בכל ממונך</b>: ראה ברכות נד, א. (לעיל בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 102."],["4853","123","<b>שופר שיעורו טפח</b>: שו\"ע אדה\"ז הל' שופר סתקפ\"ו, ס\"ו־ סי\"ג. ראה גם לעיל הנחה ד\"ה עשה צדקה ומשפט ובהערה 101."],["4854","124","<b>לולב ד\"ט</b>: ראה שו\"ע אדה\"ז הל' לולב רסתר\"נ. לעיל שם ובהערה 103."],["4855","125","<b>דמצות הוא</b>: אולי צ\"ל: דמצות הצדקה הוא."],["4856","126","<b>חומש ומעשר</b>: ראה שו\"ע יו\"ד רסרמ\"ט. אגה\"ק ס\"י. מאמרי אדה\"א הנחות תקע\"ז ע' ס. סה\"מ תש\"י ע' 177 ובהערה לשם."],["4857","127","<b>בכל מאדך. . מאד שלך</b>: ראה גם לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך ובהערה 30."],["4858","128","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח."]]],[2000480465,"<h3>רני ושמחי</h3>\n<b></b><b>ש\"פ מקץ שבת חנוכה תאמ\"ר לפ\"ק</b>\nמקץ חנוכה\n<b>רני</b> ושמחי<sup data-n=\"4859\">1</sup> בת ציון<sup data-n=\"4860\">2</sup> כי הנני בא ושכנתי בתוכך נאום ה'. וצ\"ל מהו אומרו בת דוקא והלא בחי' אם למעלה מבחי' בת וכמ\"ש במדרש לא זז מחבבה עד שקראה אמי<sup data-n=\"4861\">3</sup> וכתי' בעטרה שעטרה לו אמו<sup data-n=\"4862\">4</sup>, הרי אמי עוטר ל\"ו עטרה, ולמה א' כאן בת, וגם צ\"ל ענין בתוכך. והנה צ\"ל תחילה ענין קריאת שם חנוכה דלכאו' הוא שלא מעין המאורע כלל ומ\"ש במ\"א דחנוכה הוא חנו כ\"ה<sup data-n=\"4863\">5</sup> הוא רק תירוץ, והנה צ\"ל תחילה מ\"ש חנוך לנער ע\"פ דרכו גם כי יזקין לא יסור ממנו<sup data-n=\"4864\">6</sup> וידוע הקושיא בתניא מדאמר דרכו<sup data-n=\"4865\">7</sup> הרי א\"ז דרך האמת ואמיתי וא\"כ מהו המעלה דגם כי יזקין לא יסור ממנו, ומבואר שם התירוץ דכתי' שבע יפול צדיק וקם<sup data-n=\"4866\">8</sup> דהנה כל הנשמה היא מהלך<sup data-n=\"4867\">9</sup> וזהו ההפרש בין נשמות למלאכים וכשצריך להיות הילוך מדרגא לדרגא צ\"ל תחילה נפילה ממדריגתו הראשונה, וא\"ז נפילה גמורה דכי יפול לא יוטל<sup data-n=\"4868\">10</sup> כתי' ולגבי אחר ה\"ז עילוי אך בערך מדריגתו הראשונה ה\"ז נפילה אבל אינו נפילה גמורה, דדבר שבקדושה אינו נעקר ממקומו לגמרי<sup data-n=\"4869\">11</sup> ונשאר רשימה ממדריגתו הראשונה, ואח\"כ הוא מתעלה למדריגה עליונה ממנה וזהו גם כי יזקין לא יסור דבחי' האהבה שמורגל בה מנעוריו לא יסור ממנו גם כי יזקין.\n<b>וביאור</b> הענין הנה שרו ש\"ע נק' נער וכמ\"ש נער הייתי גם זקנתי ואמרז\"ל שרו ש\"ע אמרו<sup data-n=\"4870\">12</sup>, והוא בדרך משל ומליצה<sup data-n=\"4871\">14</sup> וקאי על מלאך מט\"ט<sup data-n=\"4872\">13</sup> שהוא ביצי'<sup data-n=\"4873\">15</sup>, וגם מצינו בחי' נער במדרי' שלמעלה מבחי' זו וכמ\"ש נער ישראל",[["4859","1","<b>רני ושמחי</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ. נמצא לפנינו לע\"ע רק חלק מהמאמר."],["4860","2","<b>רני ושמחי בת ציון</b>: זכרי' ב, יד."],["4861","3","<b>לא זז מחבבה. . אמי</b>: ראה שהש\"ר פ\"ג, יא [ב]. הנסמן במ\"מ ללקו\"ת שה\"ש כא, ב."],["4862","4","<b>בעטרה שעטרה לו אמו</b>: שה\"ש ג, יא."],["4863","5","<b>דחנוכה הוא חנו כ\"ה</b>: ראה ת\"ז תי\"ג (כט, רע\"א). לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה זאת חנוכת המזבח ובהערה 12."],["4864","6","<b>חנוך לנער ע\"פ דרכו. . ממנו</b>: משלי כב, ו [ושם: ממנה]."],["4865","7","<b>הקושיא בתניא מדאמר דרכו</b>: ח\"ב בהקדמה — חינוך קטן. ראה גם אוה\"ת על ענינים ע' קכה."],["4866","8","<b>שבע יפול צדיק וקם</b>: משלי כד, טז."],["4867","9","<b>כל הנשמה היא מהלך</b>: ראה תו\"א וישב ל, סע\"א. ש\"א ח, ב ובהערה 42."],["4868","10","<b>דכי יפול לא יוטל</b>: תהלים לז, כד."],["4869","11","<b>דדבר שבקדושה אינו נעקר ממקומו לגמרי</b>: ראה אלשיך ר\"פ לך (הובא באוה\"ת לך כרך ד ע' תרעה וע' תרפא. ושם מציין לפרדס שער המציאות פ\"א). לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אז ישיר ובהערה 45."],["4870","12","<b>נער הייתי. . שרו ש\"ע אמרו</b>: תהלים לז, כה. ראה יבמות טז, ב ובתוס' שם."],["4871","14","<b>משל ומליצה</b>: משלי א, ו. חבקוק ב, ו."],["4872","13","<b>שרו ש\"ע. . מט\"ט</b>: ראה יבמות טז, ב ובתוס' שם. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה לה\"ע ר\"ח ובהערה 39."],["4873","15","<b>מט\"ט שהוא ביצי'</b>: ראה ע\"ח שער סדר אבי\"ע שמ\"ז, פ\"ו. תו\"ח בא ח\"א צח, ריש ע\"ב ובהערה 85."]]],[2000480466,"ואוהבהו<sup data-n=\"4874\">16</sup> והוא בחי' ישראל זוטא<sup data-n=\"4875\">18</sup> (בפ\"א<sup data-n=\"4876\">19</sup> שהוא בחי' ז\"א<sup data-n=\"4877\">17</sup> ) גם זקנתי דבשבת עולה באצי'<sup data-n=\"4878\">20</sup> ומקבל מחכ'<sup data-n=\"4879\">21</sup> שבו שורה אוא\"ס<sup data-n=\"4880\">22</sup> בחי' קדמון ונצחי ועל ל' הפסוק הוא בחי' עתיק יומין כמ\"ש בדניאל עתיק יומין יתיב<sup data-n=\"4881\">23</sup>, ופי' שהוא מיושן בימים<sup data-n=\"4882\">24</sup> הגם שאמרז\"ל מי איכא זקנה קמי' קוב\"ה<sup data-n=\"4883\">25</sup>, אך באמת אינו שייך שם זמן כלל ומ\"ש מיושן בימים הכוונה לשלול החידוש שאינו מחודש, אבל לא שהוא בגדר זמן דהמתנשא מימות עולם כתי'<sup data-n=\"4884\">26</sup>, ומה שנק' עתיק יומין להורות על היותו קדמון, וכמו שמבואר במ\"א בפי' האזרחי שהו\"ע מאז ומקדם<sup data-n=\"4885\">27</sup>, מקדם אשר לא נעשה<sup data-n=\"4886\">28</sup>, ועי' שמות<sup data-n=\"4887\">29</sup> ל' [האזרחי] הוא שם<sup data-n=\"4888\">31</sup> ע\"ב שאינו מחודש<sup data-n=\"4889\">30</sup> כמו ס\"ג<sup data-n=\"4890\">32</sup> ומ\"ה<sup data-n=\"4891\">33</sup> ששניהם<sup data-n=\"4892\">35</sup> מחודשים<sup data-n=\"4893\">34</sup> דסתירת התהו הי' שלא במקרה<sup data-n=\"4894\">36</sup> דזה שייך לעמלק אשר קרך<sup data-n=\"4895\">37</sup> כו' אלא בנין התהו הי' ע\"מ לסתור וסתירת התהו הי' ע\"מ לבנות<sup data-n=\"4896\">38</sup> עולם התיקון וא\"כ שניהם",[["4874","16","<b>נער ישראל ואוהבהו</b>: הושע יא, א."],["4875","18","<b>ישראל זוטא</b>: ראה זהר רע\"מ בא מג, א. ויקהל רטז, א."],["4876","19","<b>בפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך הא' ובהערה 74."],["4877","17","<b>ישראל. . ז\"א</b>: ראה ע\"ח שער פרטי עי\"מ שכ\"ז, ספ\"ד. מאמרי אדה\"א דברים ח\"ב ע' שצב. וש\"נ."],["4878","20","<b>גם זקנתי. . באצי'</b>: ראה זהר פינחס ריז, סע\"א ואילך. (לעיל בחלק המאמרים) בהמאמר כאן הערה 17."],["4879","21","<b>באצי'. . מחכ'</b>: ראה לקו\"ת תזריע כג, ב שמציין לע\"ח שמ\"ז, פ\"ג [ובדפו\"א פ\"ב]. ראה גם הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקי. לעיל ח\"א (בחלק המאמרים) המשך מצה זו פל\"א ובהערה 1002."],["4880","22","<b>מחכ' שבו שורה אוא\"ס</b>: ראה תניא פי\"חא. פל\"ה בהג\"ה[ednref_323_א]. לקו\"ת במדבר יד, ב[ednref_324_ב]. תו\"ח שמות ח\"א ז, ד הערה 333. סה\"מ תרנ\"ח ע' יב."],["4881","23","<b>בדניאל עתיק יומין יתיב</b>: ז, ט [ושם: ועתיק]."],["4882","24","<b>מיושן בימים</b>: לשון אוה\"ת חנוכה כרך ה ע' 1864."],["4883","25","<b>מי איכא זקנה קמי' קוב\"ה</b>: ראה יבמות טז, ב. (לעיל בחלק המאמרים) מאמר ד\"ה וזהו שרש ענין יונתי ובהערה 99."],["4884","26","<b>דהמתנשא מימות עולם כתי'</b>: ע\"פ ברכת יוצר אור."],["4885","27","<b>בפי' האזרחי שהו\"ע מאז ומקדם</b>: לקו\"ת פ' ראה יח, א[ednref_325_ג]."],["4886","28","<b>מקדם אשר לא נעשה</b>: ע\"פ ישעי' מו, י."],["4887","29","<b>ועי' שמות</b>: כנראה הכוונה שבענין השמות."],["4888","31","<b>שם ע\"ב</b>: ראה זהר תרומה קלב, ב. פרדס שער פרטי השמות שכ\"א, פ\"ה. מכתב להרב בראנדט נדפס ברשימות חוברת מא (לפ' אחו\"ק)."],["4889","30","[האזרחי]<b> הוא שם ע\"ב שאינו מחודש</b>: ראה לעיל הנחה ד\"ה לכל תכלה ראיתי קץ ובהערה 93."],["4890","32","<b>שם. . ס\"ג</b>: ראה זהר רע\"מ פינחס רמו, ב."],["4891","33","<b>שם. . ומ\"ה</b>: ראה זהר בהקדמה ד, א ובדרך אמת שם. הנסמן במאמרי אדה\"א נ\"ך ע' עא."],["4892","35","<b>ומ\"ה ששניהם מחודשים</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1627."],["4893","34","<b>ס\"ג. . ששניהם מחודשים</b>: ראה גם לעיל הנחה ד\"ה לכל תכלה ראיתי קץ הנ\"ל ובהערה 87."],["4894","36","<b>דסתירת התהו הי' שלא במקרה</b>: ראה גם לעיל שם ובהערה 1808."],["4895","37","<b>לעמלק אשר קרך</b>: תצא כה, יח. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 560. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם סביבות הערה 99 ואילך."],["4896","38","<b>בנין התהו. . לסתור וסתירת התהו. . לבנות</b>: ראה גם לעיל ח\"א (המשך מצה זו) שם הערה 1699.\n\n[edn_323_א] ובמ\"מ הגהות והע\"ק שם.\n\n[edn_324_ב] ושם מציין: ”בע\"ח שער מ\"ז פ\"ג\" ולפנינו הוא פ\"ב ”ושער ב' במה\"ב פ\"א פ\"ג\" ולפנינו הוא בשער סדר אצי' ש\"ג.\n\n[edn_325_ג] בלקו\"ת שם: מאז מעולם. ראה גם אוה\"ת חנוכה כרך ה ע' 1864."]]],[2000480467,"מחודשים אבל שם ע\"ב אינו מחודש ונק' אזרח, [ולפ\"ז] אפ\"ל דאזרח הוא בחי' חכ'<sup data-n=\"4897\">39</sup> דלעילא מגולגלתא דא\"ק<sup data-n=\"4898\">40</sup>.\n<b>וזהו</b> גם זקנתי דבשבת כשעולה באצי' ומקבל מחכ' שבו שורה אוא\"ס בחי' זקנה, ואחר השבת נעשה בבחי' נער וכמאמר סליק לסיבא ואתהדר כמדלקדמין<sup data-n=\"4899\">41</sup>, והוא כדי שיתעלה אח\"כ בשבת בבחי' זקנה במדרי' גבוה יותר במדרי' זו גופא, וכמו בר\"ה דכתי' מרשית השנה חסר א'<sup data-n=\"4900\">43</sup> דאז החיות מסתלק<sup data-n=\"4901\">42</sup> וע\"י תקיעות וברכות נמשך אור חדש הגם שהוא לחדש הישנות מ\"מ נק' אור חדש רק שתלוי בהעלאת מ\"ן דשנה העברה, ונמשך רק עד אחרית השנה אבל מ\"מ הוא אור חדש והכל במדרי' אחת רק שהוא מדרי' יותר גבוה במדרי' זו גופא, ואפ\"ל זהו\"ע ג' ימים דבתר שבתא<sup data-n=\"4902\">44</sup> וג' ימים דמקמי' שבתא, דג' ימים דבתר שבתא הם כח הברורים מבחי' זקנה דשבת העברה, ואח\"כ ג' ימים דקמי' שבתא<sup data-n=\"4903\">45</sup> הם הבירורים לעשות את השבת<sup data-n=\"4904\">46</sup>, הגם דיש עולת התמיד<sup data-n=\"4905\">47</sup> והיינו תפלה דחול שהוא הארת השבת<sup data-n=\"4906\">48</sup> שבששת יומין דחול, אך הנה יש עולת שבת בשבתו<sup data-n=\"4907\">49</sup> לבד עולת התמיד, ולכן צ\"ל בחי' לעשות השבת, ובחי' זו למטה נק' שבע יפול צדיק וקם שבע יסוד<sup data-n=\"4908\">50</sup>, וזהו והוא נער את בני בלהה ובני זלפה<sup data-n=\"4909\">51</sup> נשי אביו, דיוסף נק' נער, ועז\"נ חנוך לנער ע\"פ דרכו שצריכים לחנכו והמחנך הוא זקן [והוא בחי' עטרת תפארת שיבה<sup data-n=\"4910\">52</sup> ].\n<b>וביאור</b> הענין הנה אי' בזהר ע\"פ והוא נער שקאי על יוסף שהוא בחי' יסוד<sup data-n=\"4911\">54</sup> והוא נק' נער<sup data-n=\"4912\">53</sup> דבמל' יש ב' בחי' נער ונערה<sup data-n=\"4913\">55</sup> וכשהמל' בבחי' נערה אז",[["4897","39","<b>חכ'</b>: ראה לעיל (בחלק המאמרים) בהמאמר כאן: חכ' עילאה."],["4898","40","<b>דלעילא מגולגלתא דא\"ק</b>: לעיל בהמאמר כאן: שלמעלה גם מהכתר שלעילא מגולגלתא דא\"ק — ראה ע\"ח שער שביה\"כ ש\"ט, רפ\"ו. לקו\"ת מסעי צה, ב. המשך תער\"ב ח\"ג ע' א'שצז."],["4899","41","<b>סליק לסיבא ואתהדר כמדלקדמין</b>: ראה זהר פינחס ריז, ריש ע\"ב [ושם: כמלקדמין]."],["4900","43","<b>מרשית השנה חסר א'</b>: עקב יא, יב. אגה\"ק שם."],["4901","42","<b>בר\"ה. . החיות מסתלק</b>: ראה אגה\"ק סי\"ד. (לעיל בחלק המאמרים) המשך יונתי פכ\"ג ובהערה 567."],["4902","44","<b>ג' ימים דבתר שבתא</b>: פסחים קו, סע\"א. וראה גם סהמ\"צ להצ\"צ ח, א בשם הפע\"ח."],["4903","45","<b>וג' ימים דקמי' שבתא</b>: נסמן בהערה שלפנ\"ז."],["4904","46","<b>לעשות את השבת</b>: תשא לא, טז. ראה גם תו\"א יתרו ע, א. לקו\"ת בהר מד, ג. ש\"ש סח, ב. שה\"ש כד, ב. מאמרי אדה\"ז תקס\"ג ח\"א ע' שיב."],["4905","47","<b>עולת התמיד</b>: פינחס כח, ו. ראה לקו\"ת שבהערה 49."],["4906","48","<b>תפלה דחול שהוא הארת השבת</b>: ראה תו\"א ויקהל פח, א. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני באשישות ובהערה 23."],["4907","49","<b>עולת שבת בשבתו</b>: פינחס כח, י. ראה לקו\"ת בהר מא, א."],["4908","50","<b>שבע יסוד</b>: ראה גם אוה\"ת נח ע' 120 ואילך. ויקרא ע' רסח."],["4909","51","<b>והוא נער את בני בלהה ובני זלפה</b>: וישב לז, ב [ושם: ואת בני זלפה — ראה גם לקמן בפיסקא והענין]."],["4910","52","<b>עטרת תפארת שיבה</b>: משלי טז, לא."],["4911","54","<b>יוסף שהוא בחי' יסוד</b>: ראה זהר רע\"מ פינחס רלו, א. פרדס שעה\"כ שכ\"ג, פ\"י מערכת יוסף. (לעיל בחלק המאמרים) מאמר ד\"ה עטרת תפארת שיבה ובהערה 42."],["4912","53","<b>בזהר ע\"פ והוא נער. . יסוד והוא נק' נער</b>: לעיל (בחלק המאמרים) בהמאמר כאן: בזהר ובמק\"מ פ' וישב דקפ\"ב ע\"ב."],["4913","55","<b>דבמל'. . נער ונערה</b>: ראה זהר בא לח, א. פרדס שער סדר האצילות ש\"ה, פ\"ב. מאו\"א מערכת נער סכ\"ג (הב') וביאיר נתיב שם. לקו\"ת צו ט, ד."]]],[2000480468,"יסוד בבחי' נער, ועז\"נ תתחדש כנשר נעוריכי<sup data-n=\"4914\">56</sup>, אך העיקר שזה קאי על מ\"ש בפדר\"א דנשים לא נתנו נזמיהם<sup data-n=\"4915\">57</sup> על העגל ואח\"כ בנדבת המשכן נתנו אותם בחפץ גדול ונטלו שכרן בעוה\"ז ובעוה\"ב, בעוה\"ז שמשמרים ר\"ח יותר מאנשים, ובעוה\"ב שיתעלו בבחי' ר\"ח [ועז\"נ תתחדש כנשר נעוריכי (בפ\"א וכמ\"ש המשביע בטוב עדיך תתחדש<sup data-n=\"4916\">58</sup> )], דהנה כתי' והי' אור הלבנה כאור החמה ואור החמה יהי' שבעתים כאור שבעת הימים<sup data-n=\"4917\">59</sup>, ויש בזה ב' פי' הא' שאור הלבנה יהי' כאור החמה דעכשיו<sup data-n=\"4918\">60</sup>, ב' כאור החמה שיהי' שבעתים כאור זה\"י כמו\"כ יהי' אור הלבנה בשוה<sup data-n=\"4919\">61</sup> והם ז\"ת דעתיקא, ועוי\"ל מ\"ש תתחדש כנשר נעוריכי דהנה אי' במדר'<sup data-n=\"4920\">62</sup> ע\"פ כחול ארבה ימים<sup data-n=\"4921\">63</sup>, דחוה נתנה מעה\"ד לכל הבהמות ולכל החיות ולכל העופות לבד עוף א' ושמו חול לא אכל מעה\"ד והוא חי אלף שנה ומשתיר בכביצה וחוזר ומגדל אברים, והוא משל להבין שלאחר הגדלות יש גדלות שני ותחילה צ\"ל קטנות והוא ג\"כ קטנות שני.\n<b>והענין</b> דהנה כתי' ונערים במשתה נגינתם<sup data-n=\"4922\">64</sup> מהו נערים ל' רבים, והוא בדקדוק שיש ב' נערים א' מ\"ש והוא נער את בני בלהה ובני זלפה נשי אביו, בני בלהה כו' הם חיילות דבריאה<sup data-n=\"4923\">65</sup> (חסר עוד פי' א') מ\"מ הם נשי אביו דיעקב הוא ל' יבקע<sup data-n=\"4924\">66</sup> וכמ\"ש<sup data-n=\"4925\">67</sup>",[["4914","56","<b>תתחדש כנשר נעוריכי</b>: נסמן בסמוך הערה 58."],["4915","57","<b>בפדר\"א דנשים לא נתנו נזמיהם</b>: פמ\"ה. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה להבין ענין ר\"ח בתחילתו. וש\"נ."],["4916","58","<b>המשביע בטוב עדיך תתחדש</b>: תהלים קג, ה."],["4917","59","<b>והי' אור הלבנה. . כאור שבעת הימים</b>: ישעי' ל, כו."],["4918","60","<b>פי' הא'. . כאור החמה דעכשיו</b>: ראה לקו\"ת צו י, א. תו\"ח ויצא קסח, א. אוה\"ת משפטים ע' א'קסט. סה\"מ תרכ\"ז ע' קמג. תר\"ל ע' רסא. תרל\"ח ע' נה. המשך תרס\"ו ע' תט."],["4919","61","<b>ב' כאור החמה. . אור הלבנה בשוה</b>: ראה בחיי פינחס כח, טו. כלי פז ישעי' שם. מערכת הובא בשל\"ה בית דוד בהג\"ה כג, ב. לקו\"ת שם. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקצג. אוה\"ת ישעי' ע' רטז ואילך. המשך תרס\"ו שם."],["4920","62","<b>במדר'</b>: ב\"ר פי\"ט, ה. ראה גם לקו\"ש יו\"ד שבט כרך ו' ע' 84 הערה 32."],["4921","63","<b>כחול ארבה ימים</b>: איוב כט, יח [ושם וכחול]."],["4922","64","<b>ונערים במשתה נגינתם</b>: ע\"פ נוסח ברכת נשואין."],["4923","65","<b>בני בלהה. . דבריאה</b>: ראה מק\"מ שבהערה 53."],["4924","66","<b>דיעקב הוא ל' יבקע</b>: ראה ע\"ח שער הארת המוחין של\"ב, פ\"א. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' הערה 21."],["4925","67","<b>וכמ\"ש</b>: ע\"כ נמצא לע\"ע. ראה ההמשך (לעיל בחלק המאמרים) בהמאמר כאן."]]],[2000480469,"<h3>מפני שיבה תקום</h3>\n<b></b><b>ש\"פ ויגש תאמ\"ר לפ\"ק\n(בפ\"א)</b>\nויגש\n<b>מפני</b> שיבה תקום<sup data-n=\"4926\">1</sup> והדרת פני זקן<sup data-n=\"4927\">2</sup>, ואי' בלקו\"ת מהאריז\"ל<sup data-n=\"4928\">3</sup> שזהו כנגד ב' בחי' יגת\"ד<sup data-n=\"4929\">4</sup> דא\"א ויגת\"ד דז\"א, כנגד יגת\"ד דא\"א א' מפני שיבה תקום וכנגד יגת\"ד דז\"א א' והדרת פני זקן, זה קנה חכמה<sup data-n=\"4930\">5</sup> דאבא מעטרא לי' עטרה ועייל בי' מוחא דבז\"א בעצם לא יש בחי' מוחין, ולהבין זה צלה\"ק תחילה מ\"ש שמע ישראל ה' אלקינו ה' אחד<sup data-n=\"4931\">6</sup>, וכתי' כי נער ישראל ואוהבהו<sup data-n=\"4932\">7</sup>, ואי' בזהר שהו\"ע ישראל סבא וישראל זוטא<sup data-n=\"4933\">8</sup>, והענין דהנה בפ' ויגש כתי' ואלה שמות בנ\"י הבאים מצרימה יעקב ובניו<sup data-n=\"4934\">9</sup>, הרי יעקב בכלל ישראל, ובפ' שמות כתי' ואלה שמות בני ישראל הבאים מצרימה את יעקב<sup data-n=\"4935\">10</sup> הרי יעקב בפ\"ע ולא בכלל ישראל.\n<b>והענין</b> הוא דישראל הוא לי ראש<sup data-n=\"4936\">11</sup> שהוא בחי' חכ' ראשית האצי'<sup data-n=\"4937\">12</sup>, אך עצם החכ' אנת הוא חכים<sup data-n=\"4938\">13</sup> ולא בחכ' ידיעה שאינו שייך בו השגה כלל והוא בחי' הוא לבדו הוא שאפי' אם לא הי' בריאות העולמות<sup data-n=\"4939\">14</sup> הי' שייך ג\"כ בחי' זו, רק כשמאיר בחי' נה\"י דאימא אז יכול להיות מקור לעולמות והו\"ע כליות יועצות<sup data-n=\"4940\">16</sup> איך להשפיע ובחי' זו נק' ישראל סבא<sup data-n=\"4941\">15</sup>, ובני ישראל היינו מה שיוצא מבחי' זו הם",[["4926","1","<b>מפני שיבה תקום</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה וביאור הענין למעלה הנה ארז\"ל בסוף מס' אבות בן ששים לזקנה שנדפס לעיל בחלק המאמרים. וש\"נ.\nבריש המאמר בין וממעל לתיבות לקו\"ת להאריז\"ל נרשם: (בפ\"א) ולא ניכר בהצילום שצויין מקומו איפה שייך — ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך הא' ובהערה 74."],["4927","2","<b>מפני שיבה תקום והדרת פני זקן</b>: קדושים יט, לב."],["4928","3","<b>בלק\"ת מהאריז\"ל</b>: ראה פ' קדושים בטעמי המצות בסופו."],["4929","4","<b>יגת\"ד</b>: בטעמי המצות־ ספר הליקוטים־ שער המצות (ריש פ' קדושים)־ לקו\"ת שה\"ש יא, סע\"א־ אוה\"ת חנוכה ח\"ב (כאן) ע' 576־ (לעיל בחלק המאמרים) בהמאמר כאן: דיקנא (וכן בסמוך)."],["4930","5","<b>זקן זה קנה חכ'</b>: תו\"כ קדושים יט, לב. קדושין לב, ב. ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' תשמ. תו\"ח משפטים ח\"ב ש, ב ואילך."],["4931","6","<b>שמע ישראל. . אחד</b>: ואתחנן ו, ד."],["4932","7","<b>כי נער ישראל ואוהבהו</b>: הושע יא, א."],["4933","8","<b>ואי' בזהר שזהו\"ע ישראל סבא וישראל זוטא</b>: בא, מג, א. ויקהל רטז, סע\"א."],["4934","9","<b>בפ' ויגש כתי' ואלה שמות. . יעקב ובניו</b>: מו, ח."],["4935","10","<b>ובפ' שמות כתי' ואלה שמות. . את יעקב</b>: א, א."],["4936","11","<b>דישראל הוא לי ראש</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צה. שע\"ת צד, ד הערה 26. סה\"מ תרל\"ח ע' קז. וש\"נ."],["4937","12","<b>חכ' ראשית האצי'</b>: ראה רמ\"ז לזהר ואתחנן רסה, ב (קצד, א (ד\"ה לארקא). שם סע\"ב). לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1248."],["4938","13","<b>אנת הוא חכים</b>: ראה ת\"ז בהקדמה יז, ב. (לעיל בחלק המאמרים) המשך יונתי הערה 23."],["4939","14","<b>בריאות העולמות</b>: ראה גם תניא פכ\"א כז, א ובליקוטי לוי יצחק שם."],["4940","16","<b>נה\"י. . כליות יועצות</b>: ברכות סא, א. ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 21."],["4941","15","<b>נה\"י דאימא. . ישראל סבא</b>: ראה תו\"א שמות נ, ד. (לעיל בחלק המאמרים) בהמאמר כאן: נה\"י דאבא. וראה גם להלן על יד הערה 26."]]],[2000480470,"אותיות המח', וזהו מ\"ש בפ' ויגש ואלה שמות בני ישרא\"ל, הכוונה על בחי' ישראל סבא לכן א' יעקב ובניו דיעקב הוא אחוריים דאבא וה\"ה בכלל בני ישראל, וגם אותיות המח' נק' מצרים שהם ג\"כ מגבילים וזהו ירידה הראשונה במצרים, אבל מ\"ש בפ' שמות ואלה שמות בני ישראל הבאים מצרימה הוא ירידה הב' מישראל זוטא בדיבור, וענין ישראל זוטא הוא בחי' ז\"א ונק' קטן כמ\"ש מי יקום יעקב כי קטן הוא<sup data-n=\"4942\">17</sup> והפי' כפשוטו שהוא קטן, דהנה נת\"ל ב' פי'<sup data-n=\"4943\">18</sup> הא' שנק' קטן בערך הא\"ס דבאמת הוא בריח התיכון המבריח מן הקצה אל הקצה<sup data-n=\"4944\">19</sup> אלא שהוא קטן בערך הא\"ס והוא כלי לבחי' א\"ס וכמ\"ש קטנתי מכל החסדים<sup data-n=\"4945\">20</sup> ומכל האמת פי' מפני שקטונתי לכן האיר בו בחי' חסד של אמת, אבל כאן הכוונה כפשוטו שהוא קטן שהוא רק ו\"ק ולא יש בו מוחין, או דתלת כלילן גו תלת<sup data-n=\"4946\">21</sup>, הגם שנק' ישראל לי ראש הרי יש בו מוחין, אך הוא מוחין שבמדות ואינו בערך לגבי מוחין בעצם, וכמו התינוק כשעושין נגד רצונו הוא כועס והיינו מפני שלא יש לו מוחין אבל מי שמתנהג בהשכל אינו כועס כלל, וזהו אב הרחמן<sup data-n=\"4947\">22</sup> שהוא רחמים דסדר השתל' ונמשך מבחי' אב הוא בחי' חכ' דוקא משם נמשך רחמים, ולכן כתי' כאן את יעקב שאינו בן לבחי' זו כ\"א אחים ורעים.\n<b>והנה</b> במ\"א מבואר<sup data-n=\"4948\">23</sup> דחכ' הוא ראשית השתל'<sup data-n=\"4949\">24</sup> דממכ\"ע והוא ראשית האצי' שרש האצי', דעיקר האצי' הוא עולם התיקון, וענין התיקון הוא המברר ובחכ' אתברירו<sup data-n=\"4950\">25</sup>, דענין השבירה הוא שנעשה מציאות היש, וחכ' הוא אין, והנה בחכ' גופא יש ע\"ס ומכתר שבחכ' עד ת\"ת שבחכ' הוא אבא, ונה\"י דאבא הוא ישראל סבא<sup data-n=\"4951\">26</sup> והוא מקור השפעות הנשמה ונו\"ה דאבא הם כלי השפע, והשפעה זו הוא באצי' גופא וגילוי הנשמה הוא באדם שלמטה, וע\"ז כתי' וישמחו בך ישראל מקדשי שמך<sup data-n=\"4952\">27</sup>, ובחי' זו הוא מזל מקור הנשמה. אך צ\"ל דהנה בלקו\"ת בד\"ה יונתי<sup data-n=\"4953\">28</sup>",[["4942","17","<b>מי יקום יעקב כי קטן הוא</b>: באוה\"ת חנוכה ח\"ב ע' 596 מציין: עמוס ז, ה. מכות כד, סע\"א."],["4943","18","<b>נת\"ל ב' פי'</b>: בחלק המאמרים מאמר ד\"ה רני ושמחי על יד הערה 122 ואילך."],["4944","19","<b>בריח התיכון. . אל הקצה</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["4945","20","<b>קטנתי מכל החסדים</b>: וישלח לב, יא. אגה\"ק ס\"ב."],["4946","21","<b>קטן. . ו\"ק. . דתלת כלילן גו תלת</b>: ראה מאו\"א מערכת קטן סי\"ב. מאמר ד\"ה רני ושמחי (שבהערה 18) הערה 127."],["4947","22","<b>אב הרחמן</b>: ברכת (אהבת עולם) ק\"ש שחרית. ראה גם תו\"א והמאמר שבהערה 15. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו הערה 14."],["4948","23","<b>והנה במ\"א מבואר</b>: ראה לקו\"ת שה\"ש כו, ד"],["4949","24","<b>דחכ' הוא ראשית השתל'</b>: ראה גם לעיל הערה 12."],["4950","25","<b>ובחכ' אתברירו</b>: ראה אגה\"ק סכ\"ח. זהר היכלות פקודי רנד, סע\"ב. ע\"ח שער דרושי נקודות ש\"ח, פ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא. תו\"ח תשא ח\"ב שפד, ד ואילך."],["4951","26","<b>ונה\"י דאבא הוא ישראל סבא</b>: ראה לעיל על יד הערה 15."],["4952","27","<b>וישמחו בך ישראל מקדשי שמך</b>: נוסח תפלת העמידה ליו\"ט בסידור ר\"י עמדין (בסידור אדה\"ז כל ישראל). וכ\"ה בכ\"מ — ראה לקו\"ת שה\"ש כו, א. מאמרי אדה\"א הנחות תקע\"ז ע' שסז. וש\"נ. סה\"מ תרל\"ח ע' קכג. וש\"נ."],["4953","28","<b>מזל. . בלקו\"ת בד\"ה יונתי</b>: שה\"ש טז, ד."]]],[2000480471,"מבואר שהוא בחי' ישראל עלו במח'<sup data-n=\"4954\">29</sup>, וענין מח' הוא מדרי' היותר עליונה שבחכ' והוא בחי' אתדבקותא אל הכתר<sup data-n=\"4955\">30</sup>, ועוד מבואר שם שהוא בחי' מח' הקדומה א\"ק<sup data-n=\"4956\">31</sup> וכ\"ה בכ\"ד, אך הנה אי' בזהר [ד\"ו ע\"א] על רב המנונא סבא אבל אבא דילי כו' רב סגי יקירא ועתיק יומין, ופי' בס' אשל אברהם<sup data-n=\"4957\">32</sup> שהוא בחי' ישראל סבא, דסבא ועתיק הם פי' א', הרי נשמת רב המנונא סבא מבחי' ישראל סבא אך מ\"ש דישראל סבא הוא בחי' עתיק צ\"ל שהו\"ע שמתבונה נעשה כתר לז\"א, ולפי\"ז א\"ש שבחי' זו הוא מקיף לנשמה שהוא בחי' גבוה יותר שאין ערוך כלל, וכ\"כ בכהאריז\"ל<sup data-n=\"4958\">33</sup> נח נח<sup data-n=\"4959\">34</sup> תרי זימנא הוא מקיף הנשמה ופנימיות הנשמה, ועוי\"ל דכמו שכתר האמיתי דז\"א שהוא<sup data-n=\"4960\">*36</sup> [מפנימיות] א\"א<sup data-n=\"4961\">35</sup> כמו\"כ שרש [הנשמה] מא\"א, ועוי\"ל דהנה אי' בזהר זכה יתיר יהבין לי' נשמתא<sup data-n=\"4962\">36</sup> מסטרי' דאבא ואימא והוא בחי' ישראל סבא אך אינו נק' נשמה עד שיעבור בחי' זיווג זו\"נ ונק' אחים ורעים דשרשה מאו\"א, וע\"ז שייך לומר וישמחו בך ישראל מקדשי שמך, דשמך הוא מל' דאצי' שבבי\"ע וישראל שאומרים ג\"פ קדוש ממשיכים מבחי' קדש חכ' לכן נק' מקדשי שמך, אך בלקו\"ת הנ\"ל אי' שמ\"ש והדרת פני זקן קאי על ז\"א, וכ\"ה בכהאריז\"ל<sup data-n=\"4963\">37</sup> בהדיא דבמ\"ת נדמה להם כזקן<sup data-n=\"4964\">38</sup> שנמשך בחי' יגת\"ד דא\"א בז\"א ונעשה ג\"כ בחי' יגת\"ד ונק' זקן.\n<b>אך</b> הענין הוא הנה אוא\"ס שורה בחכ' וכמ\"ש בסש\"ב<sup data-n=\"4965\">39</sup> דחכ' הוא אחד האמת שבו שורה אוא\"ס, הגם שגם ז\"א נק' ישרא\"ל זוטא לי ראש שיש בו ג\"כ מוחין, הנה מוחין שבמדות אינו בערך לגבי מוחין בעצם, וע\"ז כתי' מאד עמקו מחשבותיך<sup data-n=\"4966\">40</sup>, הנסתרות לה' אלקינו<sup data-n=\"4967\">41</sup>, לכן כדי להמשיך עצם החכ' הוא ע\"י תורה דהוא וחכ' ורצונו א'<sup data-n=\"4968\">42</sup>, ואפ\"ל ההפרש כמו מוחין דיניקה ומוחין דגדלות<sup data-n=\"4969\">43</sup>, מוחין דיניקה הוא שהמוחין מגדלי' המדה [הגם שהוא רק מוחין שבמדות מ\"מ הוא מוחין דמדות לגבי מוחין אינו בערך כלל] שהמדה בקטנות וממילא גם המוחין בקטנות אבל מוחין דגדלות הוא שמאיר עצם המוחין, וזהו ההפרש בין מה שקיים אברהם כל התורה",[["4954","29","<b>ישראל עלו במח'</b>: ראה ב\"ר פ\"א, ד. לעיל (בחלק המאמרים) מאמר ד\"ה ולהבין כו' מזבח הפנימי הערה 140."],["4955","30","<b>אתדבקותא אל הכתר</b>: לקו\"ת שם יט, ב."],["4956","31","<b>מח' הקדומה א\"ק</b>: שם יז, ד. יח, ב."],["4957","32","<b>ופי' בס' אשל אברהם</b>: ראה גם לעיל בחלק המאמרים בהמאמר כאן הערה 40."],["4958","33","<b>בכהאריז\"ל</b>: זהר הרקיע ר\"פ נח קארעץ תקמ\"ה לג, ב."],["4959","34","<b>נח נח</b>: נח ו, ט."],["4960","*36","<b>שהוא</b>: אולי כ\"ה בגוכתי\"ק."],["4961","35","<b>שכתר. . א\"א</b>: ראה ע\"ח שער מוחין דצלם שכ\"ג, רפ\"ז."],["4962","36","<b>זכה יתיר יהבין לי' נשמתא</b>: ראה זהר משפטים צד, סע\"ב. ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש ד."],["4963","37","<b>בכהאריז\"ל</b>: ראה פע\"ח שכ\"ג שער חג השבועות."],["4964","38","<b>דבמ\"ת נדמה להם כזקן</b>: ראה מכילתא בשלח טו, ג. יתרו כ, ב."],["4965","39","<b>וכמ\"ש בסש\"ב</b>: פל\"ה בהגהה."],["4966","40","<b>מאד עמקו מחשבותיך</b>: תהלים צב, ו."],["4967","41","<b>הנסתרות להוי' אלקינו</b>: נצבים כט, כח."],["4968","42","<b>דהוא וחכ' ורצונו א'</b>: ראה אגה\"ק סכ\"ו (קמד, א). לקו\"ת שה\"ש יג, ב."],["4969","43","<b>ההפרש כמו מוחין דיניקה ומוחין דגדלות</b>: ראה סידור שחרית לשבת קעח, ג."]]],[2000480472,"כולה<sup data-n=\"4970\">45</sup> עד שלא ניתנה בין מ\"ת<sup data-n=\"4971\">44</sup> שנדמה להם כזקן, דמה שקיים אברהם כו' הו\"ע מוחין דיניקה שהמוחין לפ\"ע המדות וזהו חנוך לנער ע\"פ דרכו<sup data-n=\"4972\">46</sup> ע\"פ דרך שלו וכמשנת\"ל בד\"ה רני ושמחי בת<sup data-n=\"4973\">47</sup>, אבל מ\"ת נדמה להם כזקן שהוא בחי' מוחין דגדלות עצם המוחין וכמו הזקן שנתלבנו שערותיו מפני שמאיר בו מבחי' חכ' עילאה, וזהו\"ע הלבון<sup data-n=\"4974\">48</sup> שבציצית שהם ל\"ב נת\"ח<sup data-n=\"4975\">49</sup>, אין כבוד אלא תורה<sup data-n=\"4976\">50</sup> כבוד בגימ' ל\"ב<sup data-n=\"4977\">51</sup> לכן צ\"ל לבון<sup data-n=\"4978\">52</sup>, ואפ\"ל שכנגד ב' בחי' אלו זהו מה שמצינו שב\"פ א' ליעקב לא יעקב יקרא עוד שמך כ\"א ישראל<sup data-n=\"4979\">53</sup>, תחילה א\"ל המלאך ואח\"כ א\"ל הקב\"ה, ומבואר בלקו\"ת<sup data-n=\"4980\">54</sup> שמה שא\"ל המלאך הוא בחי' שם הוי' שבסיני, ומה שא\"ל הקב\"ה הוא מ\"ש ויקרא ה' ה' פסיק טעמא בינייהו<sup data-n=\"4981\">55</sup> שיש ב' שמות הוי' ושיש ש' הוי' שלמעלה מסדר השתל', ולפמ\"ש אפ\"ל שמה שא\"ל המלאך כ\"א ישראל יהי' שמך הוא בחי' ישראל זוטא והו\"ע מוחין שבמדות, או י\"ל שהו\"ע שם הוי' שבת\"ת<sup data-n=\"4982\">56</sup> שמפני זה נק' ג\"כ ישראל, ומה שא\"ל הקב\"ה כ\"א ישראל יהי' שמך הוא בחי' מוחין דגדלות שמאיר בו מעצם החכ', והנה כ\"ז ב' בחי' נער וזקן אבל בחי' שיבה הוא למעלה מבחי' זקן והוא יגת\"ד דא\"א ומשם נמשך שיהי' זה קנה חכ', והוא סבא וסבא דסבין<sup data-n=\"4983\">57</sup>, ולפ\"ז מתורץ מ\"ש בכהאריז\"ל הנ\"ל כו'.",[["4970","45","<b>שקיים אברהם כל התורה כולה</b>: ראה יומא כח, ב. לקו\"ש תולדות כרך לה ע' 107 ואילך."],["4971","44","<b>ההפרש. . שקיים אברהם. . בין מ\"ת</b>: ראה תו\"א יתרו סח, ג."],["4972","46","<b>חנוך לנער ע\"פ דרכו</b>: משלי כב, ו."],["4973","47","<b>וכמשנת\"ל בד\"ה רני ושמחי בת</b>: נדפס לעיל."],["4974","48","<b>הלבון</b>: אולי צ\"ל הלבן. ראה גם בסמוך הערה 52."],["4975","49","<b>שבציצית שהם ל\"ב נת\"ח</b>: לעיל בחלק המאמרים בהמאמר כאן על יד הערה 67: ל\"ב חוטין הם בחי' ל\"ב נתה\"ח — ראה זח\"ג תוספת שא, א. מאמרי אדה\"א בראשית ע' שצד. וש\"נ."],["4976","50","<b>אין כבוד אלא תורה</b>: אבות פ\"ו, ג. ראה מאמרי אדה\"א בראשית ע' טז."],["4977","51","<b>כבוד בגימ' ל\"ב</b>: זהר רע\"מ צו לג, א."],["4978","52","<b>לבון</b>: אולי צ\"ל לבן. ראה גם לעיל הערה 48."],["4979","53","<b>שב\"פ. . לא יעקב יקרא עוד שמך כ\"א ישראל</b>: וישלח לב, כט. לה, י [ושם: לא יקרא שמך עוד יעקב כ\"א ישראל]."],["4980","54","<b>ומבואר בלקו\"ת</b>: שלח מט, ב."],["4981","55","<b>ויקרא ה' ה' פסיק טעמא בינייהו</b>: תשא לד, ו. זהר אד\"ר נשא קלח, רע\"א. ראה אוה\"ת וארא כרך ז ע' ב'תקסד. סה\"מ תרל\"ח ע' נה. וש\"נ."],["4982","56","<b>ש' הוי' שבת\"ת</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1505."],["4983","57","<b>סבא וסבא דסבין</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן בסופו."]]],[2000480473,"<h3>יפה שעה א' הא'</h3>\n<b></b><b>הנחה בס\"ד פ' ראה תר\"מ ליובאוויץ</b>\nפ' ראה\n<b>יפה</b> שעה א' בתשומע\"ט בעוה\"ז מכל חיי עוה\"ב<sup data-n=\"4984\">2</sup>. וצ\"ל הלא עוה\"ב הוא תשלום שכר על עשיות המצות ואיך שייך לומר שעשיות המצוה היא יפה מהתשלום שכר, ובפרט כיון שאמרו מכל חיי עוה\"ב הרי כולל גם עולם התחי' כי מהגמ' משמע שעוה\"ב הוא ג\"ע כמארז\"ל כל ישראל יש להם חלק לעוה\"ב<sup data-n=\"4985\">3</sup> ומביא ראי' מהפסוק ועמך כולם צדיקים לעולם ירשו ארץ<sup data-n=\"4986\">4</sup> וארץ הוא געה\"ת, וידוע המחלוקת בין הרמב\"ם והרמב\"ן<sup data-n=\"4987\">5</sup> בפי' עוה\"ב אם הוא נשמות בלא גופים או התלבשות נשמות בגופים שהוא עוה\"ת, אך המחלוקת זהו בעוה\"ב סתם אבל כאן שאמר מכל חיי עוה\"ב משמע מכל מיני חיות עוה\"ב הן נשמות בלא גופים והן נשמות שמתלבשות בגופים שגם גוף הגשמי'<sup data-n=\"4988\">6</sup> יהי' ניזון מזיו השכינה כי על עוה\"ב ארז\"ל עולם שאין בו לא אכילה<sup data-n=\"4989\">7</sup> ולא שתי' אלא צדיקים יושבין ונהנין מזיו השכינה, ולכאורה איך אפשר להיות שהגוף הגשמי' יהי' ניזון מזיו השכינה, אך משום ששם מאיר אוא\"ס הסוכ\"ע שהוא כל יכול לכן אפשר להיות שגם גוף הגשמי' יהי' ניזון ממנו<sup data-n=\"4990\">8</sup> והוא ע\"ד מה שאנו רואים גם עכשיו שהגשמי' הוא מקבל חיות מהרוחניות שלכאורה איך מקבל מהרוחניות דבר הגשמי', אך משום שחיותו הוא מאוא\"ס הכל יכול מחי' דבר הגשמי' ג\"כ. כמו\"כ הגוף הגם שהוא גשמי' מ\"מ ניזון מזיו השכינה, וצ\"ל איך יפה שעה כו' מכל חיי עוה\"ב שיפה עשיות המצוה מהתשלום שכר, הלא ארז\"ל אין הקב\"ה מקפח שכר<sup data-n=\"4991\">9</sup> כל ברי' ואיך הוא יפה.\n<b>אך</b> להבין זה צ\"ל תחילה מה שאי' במד\"ר ע\"פ ראה<sup data-n=\"4992\">11</sup> אנכי נותן לפניכם היום ברכה אי' שם שקאי על מה שסיים בפ' עקב אם שמור תשמרון<sup data-n=\"4993\">12</sup> ואי' שם במד\"ר ד\"א נרי בידך ונרך בידי<sup data-n=\"4994\">10</sup> אם אתה משמר את נרי הרי אני משמר את נרכם, נרי בידך קאי על מצות שמצות נק' בש' נר כמ\"ש נר מצוה ותורה אור<sup data-n=\"4995\">13</sup> ונרך בידי",[["4984","2","<b>יפה שעה א'. . עוה\"ב</b>: אבות פ\"ד, מי\"ז [ושם: העוה\"ב]. ראה גם המשך וככה תרל\"ז רפ\"ט."],["4985","3","<b>כל ישראל. . לעוה\"ב</b>: סנהדרין ר\"פ חלק (צ, א)."],["4986","4","<b>ועמך כולם. . ארץ</b>: ישעי' ס, כא [ושם: יירשו]. ראה לקו\"ת ואתחנן ט, א."],["4987","5","<b>המחלוקת בין הרמב\"ם והרמב\"ן</b>: ראה רמב\"ם הל' תשובה פ\"ח, ה\"ב. פיה\"מ ר\"פ חלק. (אגרת) מאמר תחיית המתים. רמב\"ן בסוף שער הגמול. תשובות וביאורים (קה\"ת תשל\"ד) סי\"א ע' 57 הערה 23."],["4988","6","<b>הגשמי'</b>: כנצ\"ל: הגשמי. וכן בסמוך."],["4989","7","<b>עולם. . לא אכילה</b>: ראה ברכות יז, א."],["4990","8","<b>שגם גוף הגשמי יהי' ניזון ממנו</b>: ראה גם תו\"ח שמות ח\"א מ, ב. המשך אלה תולדות נח תרל\"ז פי\"ח (לא נדפס לע\"ע). המשך וככה תרל\"ז פ\"ה (ע' ז). סה\"מ תרכ\"ט ע' כב. וש\"נ. תרל\"ב ח\"א ע' קכא. וש\"נ. תשובות וביאורים שם ס\"ג ע' 12."],["4991","9","<b>אין הקב\"ה מקפח שכר</b>: ב\"ק לח, ב."],["4992","11","<b>ראה אנכי. . ברכה</b>: פ' ראה יא, כו."],["4993","12","<b>אם שמור תשמרון</b>: עקב יא, כב."],["4994","10","<b>במד\"ר ע\"פ ראה. . נרי בידך ונרך בידי</b>: ראה דב\"ר פ\"ד, ד."],["4995","13","<b>נר מצוה ותורה אור</b>: משלי ו, כג."]]],[2000480474,"קאי על נשמות שהנשמה נק' ג\"כ בש' נר כמ\"ש נר הוי' נשמת אדם<sup data-n=\"4996\">14</sup> והכי פי' אם אתה משמר את נרי תומ\"צ הרי אני משמר את נרכם היינו הנשמה, וצ\"ל למה תלו השמירה דנשמה בתומ\"צ הלא בל\"ה אי' ואתה משמרה בקרבי<sup data-n=\"4997\">15</sup>. ולהבין כ\"ז צ\"ל תחילה ענין ירידת הנשמה בגוף שלכאורה היא ירידה גדולה ועצומה כי קודם שירדה הנשמה בגוף כתי' חי הוי' אשר עמדתי לפניו<sup data-n=\"4998\">16</sup>, וענין עמידה למעלה הו\"ע ביטול באהוי\"ר ע\"ד מלאכים שכתי' אצלם ויעמידם לעד לעולם<sup data-n=\"4999\">17</sup> שרפים עומדים ממעל לו<sup data-n=\"5000\">18</sup> שעמידתם הוא באהוי\"ר, והנה מה מלאכים שהם מחיצוני' הכלים עמידתם הוא באהוי\"ר וכש\"כ נשמות שהם מפנימי' הכלים<sup data-n=\"5001\">19</sup> בודאי עמידתה הוא באהוי\"ר, ואיך הי' עמידתה לפניו שהוא מדריגה גדולה, ועכשיו שירדה להתלבש בגוף ונה\"ב ה\"ה מעלים ומסתיר על אהוי\"ר שהי' לה ואין ביכולתה לעורר אהוי\"ר ואפי' שתתעורר אהוי\"ר אין ערוך לאהוי\"ר שהיתה לה מקודם והלואי שתהי' שבה למעליותה כמקדם ויכול להיות שלא תתעורר כלל אהוי\"ר, וכל דרכיה בחזקת סכנה. וצ\"ל למה ירדה כ\"כ ירידה גדולה ומוכרחים לומר שכדאי הירידה בשביל העלי' שיהי' אח\"כ שהו\"ע ירידה צורך עלי'<sup data-n=\"5002\">20</sup> והוא ע\"ד כמו שאי' בספרים שיש מיני אבנים יקרים שאינם נמצאים ביבשה כ\"א בים<sup data-n=\"5003\">21</sup> דוקא ואנו רואים שיורדים בים במקום סכנה כדי להוציא האבן והוא יקר מאד כך מוכרח להיות שמה שירדה הנשמה במקום סכנה שהוא ירידה גדולה והוא בשביל העלי' שאח\"כ, צ\"ל מהו\"ע העלי'.\n<b>והענין</b> הוא כי הנה ידוע שעיקר קיום העולם הוא בשביל תומ\"צ כמ\"ש בראשית ברא אלקים ולכאו' מהו בראשית דוקא, ותירצו בשביל ישראל שנק' בראשית ובשביל התורה<sup data-n=\"5004\">22</sup> שנק' ראשית נמצא שעיקר קיום העולם הוא בשביל התומ\"צ, וכמו שאי' עשרה עשרה הכף בשקל הקדש<sup data-n=\"5005\">23</sup> שעשה\"ד מכוון כנגד עש\"מ<sup data-n=\"5006\">24</sup>,",[["4996","14","<b>נר הוי' נשמת אדם</b>: משלי כ, כז."],["4997","15","<b>בל\"ה </b>[ בלאו הכי]<b> אי' ואתה משמרה בקרבי</b>: ברכת אלקי נשמה."],["4998","16","<b>חי הוי' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["4999","17","<b>ויעמידם לעד לעולם</b>: תהלים קמח, ו. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 15."],["5000","18","<b>שרפים עומדים ממעל לו</b>: ישעי' ו, ב. ראה סוטה לט, א (צויין אליו ב) לקו\"ת נשא כ, ג. כב, ג."],["5001","19","<b>מלאכים שהם מחיצוני' הכלים. . מפנימי' הכלים</b>: ראה ע\"ח שער העיבורים שכ\"ח, פ\"א. שער פו\"ח ש\"מ, דרוש י. מאמרי אדה\"א ויקרא ח\"א ע' צט. וש\"נ. דברים ח\"ג ע' תשסח. וש\"נ. תו\"ח בשלח ח\"א רמ, ד ואילך."],["5002","20","<b>ירידה צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["5003","21","<b>שאי' בספרים. . אבנים. . בים</b>: ראה גם המשך מים רבים תרל\"ו בתחלתו סע\"ב ואילך."],["5004","22","<b>בראשית ברא. . ישראל. . התורה</b>: בראשית א, א. ראה רש\"י בראשית א, א. תו\"ח בראשית מד, א הערה 6. ראה גם תו\"ח שם ז, א ואילך."],["5005","23","<b>עשרה עשרה הכף בשקל הקדש</b>: נשא ז, פו."],["5006","24","<b>שעשה\"ד מכוון כנגד עש\"מ</b>: ראה זהר יתרו צג, ב. ויקרא יא, ב. לקו\"ת חוקת נז, סע\"ג ואילך בשם המגיד. מאמרי אדה\"א דברים ח\"א ע' רפ. וש\"נ. תו\"ח וארא ח\"א פא, ג ובהערה 636. סה\"מ תרל\"ח ע' ע. וש\"נ. סה\"מ מלוקט ד' ע' פ ואילך."]]],[2000480475,"שקיום עש\"מ הוא ע\"י עשה\"ד, וכמ\"ש אם לא בריתי<sup data-n=\"5007\">25</sup> יומם ולילה חוקת ארץ ושמים לא שמתי ואי' במד\"ר תנאי התנה הקב\"ה<sup data-n=\"5008\">26</sup> עם מעשה בראשית אם יקיימו ישראל תורתי מוטב ואם לאו יחזיר את העולם לתוהו, וכן אי' במד\"ר ע\"פ אלה תולדות השמים והארץ בהבראם<sup data-n=\"5009\">27</sup> ואלה בזכות מי הם עומדים ובזכות מי הם קיימים בזכות ואלה שמות בנ\"י<sup data-n=\"5010\">28</sup> ואלה בזכות מי הם עומדים וקיימים בזכות ואלה העדות והחוקים<sup data-n=\"5011\">29</sup>, נמצא שעיקר קיום העולם הוא בשביל התורה דוקא, וכן מצינו בפירוש מקרא מלא הכתוב מדבר שנא' אנכי עשיתי ארץ<sup data-n=\"5012\">30</sup> ואדם עלי' בראתי ולכאורה מהו הסיפור, אך הענין הוא כי כדי שיוכל להיות מאנכי מי שאנכי<sup data-n=\"5013\">31</sup> ארץ הגשמי' הוא בשביל אדם עלי' משום שאדם הוא מובחר הנבראים<sup data-n=\"5014\">32</sup> כמארז\"ל כל העולם לא נברא אלא לצוות לזה<sup data-n=\"5015\">33</sup> פי' לצוות שיהי' הצוותא וחיבור<sup data-n=\"5016\">34</sup> לזה, והנה ענין זה הוא כמ\"ש סוף דבר הכל נשמע את אלקי' ירא ואת מצותיו שמור כי זה כל האדם<sup data-n=\"5017\">35</sup>, שעיקר המכוון הוא זה, ומהו זהו בראתי שבראתי גימט' תרי\"ג<sup data-n=\"5018\">36</sup> שעליהם קיום העולם.\n<b>וצ\"ל</b> ענין המצות לכאורה מה יהי' באם שיעשה המצות, אך הנה בכלל מצות הם למעלה מטו\"ד ואפי' המצות שהם עפ\"י טו\"ד הם ג\"כ למעלה מטו\"ד, לא מיבעי חוקים הם למעלה מטו\"ד לגמרי אלא אפי' המצות שהם עפ\"י טו\"ד הטעם הוא רק עשיות המצוה אבל עצם המצוה למעלה מטו\"ד, דהיינו מצות סוכה שנא' בסוכת תשבו ז' ימים<sup data-n=\"5019\">37</sup> הטעם הוא כי בסוכות הושבתי<sup data-n=\"5020\">38</sup> את בנ\"י, או עד\"מ מצות מצה שמצה זו על שום מה על שום שלא הספיק<sup data-n=\"5021\">39</sup>, כי בחיפזון יצאת<sup data-n=\"5022\">40</sup> מארץ מצרים, נמצא שהטעם הוא על עשיות המצות ועל עצם המצוה אין לה טעם ודעת, ואין לומר שהמצות הו\"ע זכירה זה אין שייך לומר, ואפי' כשתאמר שהם ענין זכירה צ\"ל למה עלה ברצונו שתהי' באופן כזה לכתחילה, וזה א\"א לומר שהמצות הם צורך גבוה<sup data-n=\"5023\">41</sup>,",[["5007","25","<b>אם לא בריתי</b>: ירמי' לג, כה [ושם: שמים וארץ]. ראה שבת לג, א."],["5008","26","<b>ואי' במד\"ר תנאי התנה הקב\"ה</b>: ראה שבת פח, א. מאמרי אדה\"א בראשית ע' קמ. וש\"נ. תו\"ח בראשית ב, ד הערה 37. סה\"מ מלוקט ד' ע' שכו."],["5009","27","<b>אלה תולדות השמים והארץ בהבראם</b>: בראשית ב, ד. ראה שמו\"ר פמ\"ח, [ב]."],["5010","28","<b>ואלה שמות בנ\"י</b>: שמות א, א."],["5011","29","<b>ואלה העדות והחוקים</b>: ואתחנן ד, מה [ושם: אלה]."],["5012","30","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב."],["5013","31","<b>מאנכי מי שאנכי</b>: ראה תניא מהדו\"ק ספמ\"ט. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["5014","32","<b>שאדם הוא מובחר הנבראים</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פט\"ו. וש\"נ."],["5015","33","<b>כל העולם. . לצוות לזה</b>: ראה ברכות ו, ב."],["5016","34","<b>לצוות. . הצוותא וחיבור</b>: ראה גם לעיל המשך זאת חנוכת המזבח שם ובהערה 357."],["5017","35","<b>סוף דבר. . האדם</b>: קהלת יב, יג."],["5018","36","<b>שבראתי גימט' תרי\"ג</b>: ראה רמ\"ז לזהר ויגש רה, ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1688."],["5019","37","<b>בסוכת תשבו ז' ימים</b>: אמור כג, מב."],["5020","38","<b>כי בסוכות הושבתי</b>: אמור כג, מג."],["5021","39","<b>שמצה זו. . שלא הספיק</b>: נוסח ההגדה."],["5022","40","<b>כי בחיפזון יצאת</b>: פ' ראה טז, ג."],["5023","41","<b>שהמצות הם צורך גבוה</b>: ראה גם לעיל הנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה (נדפסה בחלק הנחותיו) ובהערה 44."]]],[2000480476,"הלא אצלו ית' אי' אנת הוא שלימותא דכולהו<sup data-n=\"5024\">42</sup>. ובאמת אי' במד\"ר מאי איכפת להקב\"ה אם שוחט מן העורף או מן הצואר, ופי' מאי איכפת שאינו נוגע ואינו תופס מקום כלל, כי כללות כל המצות הם ענין צדקה כמ\"ש כל מצותיך צדק<sup data-n=\"5025\">44</sup> שהו\"ע צדקה, אלא לא ניתנו המצות לישראל אלא לצרף את הבריות<sup data-n=\"5026\">43</sup>, ועל מה שייך לומר בריות על נה\"א א\"א לומר בריות כי הוא חלק אלקה ממעל<sup data-n=\"5027\">45</sup> כמ\"ש חלק הוי' עמו<sup data-n=\"5028\">46</sup>, ואפי' על נפש דמל' דמל' דעשי' אי' בתני'<sup data-n=\"5029\">47</sup> שמלובש בו חכ' דעשי' חכ'<sup data-n=\"5030\">48</sup> דיצי' חכ' דברי' חכ' דאצי' שבה שורה אוא\"ס ובאצי' אין שייך לומר בריאה אלא בריות קאי על גוף ונה\"ב<sup data-n=\"5031\">49</sup>, שע\"י תומ\"צ נתברר נה\"ב ויתעלה למעלה, כי נה\"ב שרשו מעולם התוהו<sup data-n=\"5032\">50</sup> שקדמה לתיקון<sup data-n=\"5033\">51</sup> רק שנפלה בשבה\"כ וע\"י שיקיים תומ\"צ מעלה אותו למקורו ושרשו ויורש אורות דתוהו, ובזה יהי' ניחא מה שירדה הנשמה בגוף ונה\"ב שהיא ירידה גדולה ועצומה וכל הדרכים בחזקת סכנה<sup data-n=\"5034\">52</sup> מ\"מ כדאי הירידה כי ע\"י בירור דנה\"ב גדלה ורב כוחה שיתעלה נה\"א ג\"כ, והגם שכתי' ורוח האדם היא העולה למעלה<sup data-n=\"5035\">53</sup> משמע שבל\"ה עולה, אך פי' עולה אינו פי' שעולה אלא שיש בכחו לעלות, כי ההפרש הוא בין דבר שיש בכחו לעלות ולדבר שאין בכחו לעלות, כי דבר שאין בכחו לעלות עד\"מ אבן שטבעו לנפול למטה וע\"י שזורק האדם את האבן עולה למעלה, ואינו עולה רק כמה שיש בכוח מקיף היד לעלות ולא יותר, אבל דבר שיש בכוחו לעלות יכול לעלות עד רום המעלות, כך נה\"א יש בכוחו לעלות וע\"י בירור דנה\"ב עולה עד רום המעלות, וצ\"ל אנה עליתה.\n<b>צ\"ל</b> תחילה מה שאנו אומרים נשמה שנתת בי טהורה היא אתה בראת יצרת נפחת ולכאו' איך שייך טהורה קודם בראת<sup data-n=\"5036\">54</sup> הלא טהורה הוא ש' ומציאות ובראת הוא בריאה יש מאין שהוא דבר מלא דבר<sup data-n=\"5037\">55</sup> ומאחר שלא דבר הוא איך שייך שם דבר",[["5024","42","<b>אנת הוא שלימותא דכולהו</b>: ראה ת\"ז בהקדמה יז, ב."],["5025","44","<b>כל מצותיך צדק</b>: תהלים קיט, קעב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם ובהערה 39."],["5026","43","<b>מאי איכפת. . לצרף את הבריות</b>: ראה תנחומא שמיני ז-ח. ב\"ר רפמ\"ד. אוה\"ת שמיני ע' נב ואילך. המשך מים רבים תרל\"ו ע' קטו. סה\"מ תרל\"ח ע' מח ואילך. לקו\"ש אבות כרך יז ע' 415 הערה 53. שופטים כרך יט ע' 182 הערה 42."],["5027","45","<b>חלק אלקה ממעל</b>: איוב לא, ב. ראה תניא רפ\"ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 395."],["5028","46","<b>חלק הוי' עמו</b>: האזינו לב, ט. ראה גם לעיל ח\"א הנחה ד\"ה כמים הפנים סוף פיסקא א."],["5029","47","<b>נפש דמל' דמל' דעשי' אי' בתני'</b>: ראה שם פי\"ח. ראה גם לעיל שם ובהערה 11."],["5030","48","<b>חכ'</b>: תיבה זו הוכפלה בכתה\"י."],["5031","49","<b>בריות. . ונה\"ב</b>: ראה המשך מים רבים תרל\"ו פק\"י ע' קטו. ראה גם (לעיל בחלק המאמרים) המשך יונתי כאן ובהערה 204."],["5032","50","<b>נה\"ב שרשו מעולם התהו</b>: ראה תו\"ח נח ס, ג ובהנסמן במ\"מ לשם. סה\"מ תרע\"ח ע' רפ."],["5033","51","<b>התהו שקדמה לתיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ד. וש\"נ. לעיל הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 68."],["5034","52","<b>וכל הדרכים בחזקת סכנה</b>: ירושלמי ברכות פ\"ד, ה\"ד. קה\"ר ג, ב (ב)."],["5035","53","<b>ורוח האדם היא העולה למעלה</b>: קהלת ג, כא [ושם: מי יודע רוח בני האדם העולה היא למעלה — ראה גם לקמן הנחה ד\"ה אני לדודי הא' על יד הערה 15. ש\"א י, ב הערה 36]."],["5036","54","<b>נשמה. . טהורה קודם בראת</b>: ברכת אלקי נשמה (מברכות ס, ב). ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 92."],["5037","55","<b>דבר מלא דבר</b>: אולי צ\"ל: דבר לא מדבר — ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 479."]]],[2000480477,"אך הנה כל הנוסחות הם מאנשי כנה\"ג<sup data-n=\"5038\">56</sup> ולא הם בעצמם התקינו מחדש אלא הם קבלו איש מפי איש וגם משה רבינו<sup data-n=\"5039\">57</sup> אמר זה הנוסח, ואפי' בני עלי'<sup data-n=\"5040\">58</sup> שהיו ושעתידין להיות ג\"כ אומרים זה הנוסח, וצ\"ל איך אומרים טהורה קודם בראת. אך הענין הוא כי הנה ידוע שיש ב' מיני נשמות כמו שאי' וזרעתיה בישראל<sup data-n=\"5041\">60</sup> זרע אדם וזרע בהמה, זרע אדם קאי על נשמות דאצי' וזרע בהמה<sup data-n=\"5042\">59</sup> קאי על נשמות דבי\"ע. והנה כאשר נשמות דאצי' צריכין להתלבש בגוף ונה\"ב צריכין לימשך דוקא דרך בי\"ע ולכן אומרים זה הנוסח שהם יורדים דרך בראת כו', וגם נשמות דבי\"ע אומרים ג\"כ זה הנוסח כי שרשם הוא בטה\"ע<sup data-n=\"5043\">61</sup> כמו שאי' בתניא שאפי' נשמה דמל' דמל' דעשי' מלובש בה חכ' דאצי'. והגם שאי' לבושין תקינת לון<sup data-n=\"5044\">62</sup> דמינייהו פרחין נשמתין לבני נשא משמע שהם אינן אלא לבושין, אך זהו רק פרחין אבל עצם הנשמה שרשה הוא בטהו\"ע<sup data-n=\"5045\">63</sup>. ולפי זה קשה מאחר ששרש הנשמות הוא בטהורה עילאה שהיא מד' גבוה וצ\"ל איך היא עליתה. אך הענין הוא כי הנה פי' טהורה שנקי מכל דבר לכלוך ומדבר חציצה<sup data-n=\"5046\">64</sup> ואינו מעלים ומסתיר, ובאמת יש כמה פירושים בתי' טהורה שעל שמות לשון<sup data-n=\"5047\">66</sup> הוא טהורה עילאה<sup data-n=\"5048\">65</sup> ועוד י\"ל שקאי על אותיו' הרשימה<sup data-n=\"5049\">67</sup> שבאותיו' הרשימה לא נגע בה הצמצום כי הצמצום לא הי' רק באורות שהוא פעולת האותיו' ולא בהאותיו' כי אותיו' הם ממד' גבוה כמו שאנו רואים שדבר שכל נמשך דוקא ע\"י אותיו' שהם פועלים השכל וזהו ידוע שפועל הוא מד' גבוה מהפעולה<sup data-n=\"5050\">68</sup> ולפי זה הוא יותר קשה למה ירדה הנשמה בגוף בשביל העלי' ובכ\"מ נת' שעלי' הוא מאיהו וגרמוהי לאיהו וחיוהי<sup data-n=\"5051\">69</sup> וכאן ביארנו שבגרמוהי לא נגע בה הצמצום אלא בהאורות שהו\"ע חיוהי נמצא לא די שאינו עלי' אלא ה\"ה פחיתות.",[["5038","56","<b>כל הנוסחות הם מאנשי כנה\"ג</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר רסמ\"ו. מאמרי אדה\"ז תקס\"ג ח\"א ע' קכד. תו\"ח וארא ח\"א עד, א."],["5039","57","<b>קבלו איש מפי איש וגם משה רבינו אמר</b>: ראה גם (לעיל בחלק המאמרים) בההמשך כאן ובהערה 208."],["5040","58","<b>בני עלי'</b>: סוכה מה, ב."],["5041","60","<b>וזרעתיה בישראל</b>: ירמי' לא, כו [ושם: וזרעתי את ב\"י. בדילוג]."],["5042","59","<b>ב' מיני נשמות. . זרע אדם. . וזרע בהמה</b>: ראה תו\"א ותו\"ח ר\"פ משפטים. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 29."],["5043","61","<b>שרשם הוא בטה\"ע</b>: נסמן לקמן הערה 65."],["5044","62","<b>לבושין תקינת לון</b>: ת\"ז בהקדמה יז, א."],["5045","63","<b>בטהו\"ע</b>: בכמה מקומות בהנחה כאן כותב: ”טהורה\" במקום תיבת ”טהירו\"."],["5046","64","<b>טהורה. . חציצה</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 193."],["5047","66","<b>שעל שמות לשון</b>: כ\"ה בהכת\"י."],["5048","65","<b>טהורה. . טהורה עילאה</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי כאן ובהערה 211."],["5049","67","<b>אותיו' הרשימה</b>: ראה לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה אז ישיר בהמשך מצה זו פ\"ו. פ\"ז. ובהנחת כ\"ק אדמו\"ר מהורש\"ב שם על יד הערה 38 ואילך."],["5050","68","<b>שפועל הוא מד' גבוה מהפעולה</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 55. המשך וככה תרל\"ז ע' יז ואילך. סה\"מ תרל\"ח ע' תצד וע' תקז."],["5051","69","<b>שעלי' הוא מאיהו וגרמוהי לאיהו וחיוהי</b>: ראה תו\"א יתרו עא, א. עב, ב. לקו\"ת בלק ע, ב. פ' ראה כז, א ואילך. יוה\"כ ע, ג."]]],[2000480478,"<b>אך</b> הענין הוא שאי' בזהר איהו וחיוהי חד ואיהו וגרמוהי חד<sup data-n=\"5052\">70</sup> ומוכרח לומר שחיוהי וגרמוהי הם שני דברים שאל\"כ הי' לו לומר איהו וחיוהי ואיהו וגרמוהי חד, לל\"ל תרי זימנא חד אלא הם שני דברים. והענין הוא פי' דגרמוהי יש בו שני פירושים, באגרת הקודש ובע\"ח אי' שגרמוהי הו\"ע כלים ובזהר ומפרשי הזהר אי' שגרמוהי הו\"ע מדות<sup data-n=\"5053\">71</sup>, והנה איך שנפרש ענין גרמוהי הן שהו\"ע כלים והן שגרמוהי הו\"ע מדות הרי האיהו מתייחד עם גרמוהי כדי לברוא בו וע\"י בריאה יש מאין כי בריאה הוא מחיק הבורא ולא מחיק הנבראים, מאחר שהוא נברא אינו יכול לברוא אלא הוא מחיק הבורא, ואפי' מגרמוהי ג\"כ אין יכול להיות בריאה מאחר שצריך להיחוד דאיהו אלא העיקר בריאה הוא מאיהו<sup data-n=\"5054\">72</sup> רק בכדי שיהי' התחלקות ליש ודבר בפ\"ע צריך להיות שנמשך דרך גרמוהי אבל עיקר הבריאה הוא מאיהו, והוא עד\"מ צבת שצבת בצבת עשוי'<sup data-n=\"5055\">73</sup> או המכה בקורנס על גבי הסדין ומי המכה הלא האדם רק שהוא ע\"י הקורנס כמ\"כ כאן עיקר הבריאה הוא מאיהו רק בכדי שיוכל להיות התחלקות ויש דבר בפ\"ע הוא ע\"י מה שאיהו מתייחד עם גרמוהי. וענין חיוהי יש בו ג\"כ ב' פי' האהה\"ק<sup data-n=\"5056\">74</sup> ובע\"ח אי' שחיוהי הוא אורות ובזהר ומפרשי הזהר אי' שחיוהי הוא מוחין. וכשם שנת' שחיוהי וגרמוהי הם שני דברים כמו\"כ מוכרחים לומר מה שאיהו מתייחד עם חיוהי הוא ג\"כ מחולק מהאיהו שמתייחד עם גרמוהי שאל\"כ הי' לו למימר איהו וחיוהי וגרמוהי חד לל\"ל איהו אצל גרמוהי ג\"כ, וזה אין לומר שכתב כן כדי להורות שלא יטעו לומר שגרמוהי הוא מחולק מאיהו, אך זהו אין לומר כי הרי הם שני חילוקי שמות גרמוהי וחיוהי בודאי הם שני דברים, אלא תלוי במי שאיהו מתייחד אם איהו מתייחד עם גרמוהי הוא באופן כזו ואם האיהו מתייחד עם חיוהי ה\"ה באופן אחר, אלא מוכרח לומר שהם מחולקים, והגם דא\"ס הוא פשוט בתכלית הפשיטות ואיך שייך לומר שיש בו התחלקות שאיהו דחיוהי הוא מחולק מאיהו וגרמוהי, אך היא הנותנת כיון שהוא פשוט בתכלית הפשיטות והוא כל יכול לכן י\"ל שאינן שוי'.\n<b>ולהבין</b> זה צ\"ל תחילה ענין גרמוהי. הנה איהו מתייחד עם גרמוהי לברוא בו וע\"י בריאה יש מאין שיהי' יש ודבר בפני עצמו, והגם שכתי' אין דבר חוץ ממנו, אין עוד מלבדו<sup data-n=\"5057\">75</sup>, וכשם שקודם הצמצום הי' ממלא את כל<sup data-n=\"5058\">76</sup> החלל<sup data-n=\"5059\">77</sup> כך אחר",[["5052","70","<b>איהו וחיוהי. . וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב. לעיל (בחלק המאמרים) המשך יונתי כאן הערה 216."],["5053","71","<b>דגרמוהי. . באגרת הקודש ובע\"ח. . כלים ובזהר ומפרשי הזהר. . מדות</b>: ראה גם סה\"מ תרל\"ג ח\"ב ע' תלה ובהערה שם. (לעיל בחלק המאמרים) המשך יונתי ובהערה 100. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 52."],["5054","72","<b>מגרמוהי אין יכול להיות בריאה. . מאיהו</b>: ראה סה\"מ תרל\"ח ע' ד."],["5055","73","<b>שצבת בצבת עשוי'</b>: אבות פ\"ה, מ\"ו."],["5056","74","<b>האהה\"ק </b>[כנצ\"ל: באגה\"ק]<b> ובע\"ח אי' שחיוהי הוא אורות ובזהר ומפרשי הזהר. . מוחין</b>: ראה הערה 71."],["5057","75","<b>אין עוד מלבדו</b>: ואתחנן ד, לה."],["5058","76","<b>שקודם הצמצום הי' ממלא את כל החלל</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב."],["5059","77","<b>ממלא את כל החלל</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 215."]]],[2000480479,"הצמצום ה\"ה ממלא את כל החלל כמקדם וכמ\"ש את השמים והארץ אני מלא<sup data-n=\"5060\">78</sup> פי' אני א\"ס עצומ\"ה כאדם האומר על עצמו אני הוא על מי ששאלת עליו, כונתו אני עצמותו, כמו\"כ מ\"ש אני מלא א\"ס עצומ\"ה. אך מה שנראה העולם ליש ודבר בפ\"ע זהו דוקא לגבינו אבל גבי' ית' אין לך דבר חוץ ממנו. ומה שאי' מה שנראה העולם הוא שקר גמור<sup data-n=\"5061\">79</sup>, זה אין שייך לומר שא\"כ מהו\"ע בריאת העולמות ובאמת כתי' בראשית ברא אלקים<sup data-n=\"5062\">80</sup> כי אל דיעות הוי'<sup data-n=\"5063\">81</sup> שהב' דיעות הם אמת, אך מה שנראה העולם ליש ודבר בפ\"ע זהו שקר גמור אבל לגבי' ית' אינו דבר בפ\"ע רק ההפרש הוא בין העלם וגילוי אבל באמת שניהם אלקות, כי העלם וגילוי הוא אלקות, כשם שגילוי הוא אלקות כך העלם הוא ג\"כ אלקות<sup data-n=\"5064\">82</sup>, וזהו פי' איהו וגרמוהי שע\"י שאיהו מתייחד עם גרמוהי ע\"י זה נעשה יש ודבר בפ\"ע והאיהו הוא בהעלם בגרמוהי. ונוכל להבין זאת מנפש האדם הנה זהו ברי לכל אדם שיש בו נשמה המחי' אותו מ\"מ א\"א לראות מהות הנשמה כי גילוי הנשמה היא גבוה<sup data-n=\"5065\">83</sup> מגילוי אליהו ורוח הקודש, ודוקא האריז\"ל זכה לזה ע\"י שמחה של מצוה<sup data-n=\"5066\">84</sup>. והגם שלא ראינו מהות הנשמה מ\"מ אין חל ע\"ז אפי' ספק יש<sup data-n=\"5067\">85</sup> נשמה המחי' את הגוף או לא, אלא ברי לנו שבודאי יש נשמה המחי' את הגוף כי בהפרד הנפש מהגוף נשאר הגוף כאבן דומם, ובעת שהנשמה ישנה בגוף יכול להתעלות עד רום המעלות, ומוכרח לומר שיש הרכבה שמחבר הנשמה והגוף כי הגוף אין לו ערך לגבי הנשמה כערך הדומם לגבי חי ומאין הוא ההרכבה שמחבר הנשמה עם הגוף שזהו מא\"ס שהוא כל יכול שאפי' חכ' כעשי' גשמי' נחשבת<sup data-n=\"5068\">86</sup> כמ\"ש כולם בחכ' עשית<sup data-n=\"5069\">*87</sup>, והוא האיהו שמתייחד עם גרמוהי.\n<b>ועוד</b> י\"ל זאת ממה שאנו רואים שמוכרח לומר שבעצם הגוף לבד הנשמה יש בו ג\"כ חיות<sup data-n=\"5070\">87</sup> מלבד הקיסטא דחיותא<sup data-n=\"5071\">88</sup> שהוא כח ההרגש כמ\"ש ונפשו עליו",[["5060","78","<b>את השמים והארץ אני מלא</b>: ירמי' כג, כד [ושם: ואת הארץ]."],["5061","79","<b>שנראה העולם הוא שקר גמור</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1454."],["5062","80","<b>בראשית ברא אלקים</b>: בראשית א, א."],["5063","81","<b>כי אל דיעות הוי'</b>: שמואל-א ב, ג. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. תו\"ח בראשית יח, ג ובהערה 11. (לעיל בחלק המאמרים) מאמר ד\"ה והוא כחתן על יד הערה 15."],["5064","82","<b>העלם הוא ג\"כ אלקות</b>: ראה גם סה\"מ תרכ\"ט ע' קסג. וש\"נ."],["5065","83","<b>גילוי הנשמה היא גבוה</b>: ראה שע\"ק להרח\"ו ח\"ג, ש\"ה וש\"ז. מאמרי אדה\"א דברים ח\"ב ע' תצא. וש\"נ. ח\"ד ריש ע' א'תפט. וש\"נ. דרושי חתונה ח\"א ע' קפב. הנחות תקע\"ז ע' שה. וש\"נ. סה\"מ תרל\"ח ע' שצו. וש\"נ."],["5066","84","<b>האריז\"ל. . שמחה של מצוה</b>: ראה גם המשך מים רבים תרל\"ו ע' רג[ednref_326_א]. ח\"ב ריש ע' תקיב. סה\"מ תרל\"ח ע' שצו וע' תלד. וראה גם מאמרי אדה\"א נ\"ך ע' כז. וש\"נ."],["5067","85","<b>יש</b>: כנראה צ\"ל: אם יש."],["5068","86","<b>חכ' כעשי' גשמי' נחשבת</b>: ראה תניא פ\"ב בהגהה. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך ובהערה 46."],["5069","*87","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["5070","87","<b>שבעצם הגוף. . יש בו ג\"כ חיות</b>: ראה גם לעיל (בחלק המאמרים) המשך יונתי כאן ובהערה 223."],["5071","88","<b>הקיסטא דחיותא</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן ובהערות 224-225.\n\n[edn_326_א] ושם: ”וכמ\"ש במ\"א בד\"ה כל העוסק בתורה בלילה שהאר\"י ז\"ל זכה לזה ע\"י בחי' שמחה של מצוה\"."]]],[2000480480,"תאבל<sup data-n=\"5072\">89</sup>, קשה רימה למת<sup data-n=\"5073\">90</sup>, או כמארז\"ל מתים יודעים או לא יודעים<sup data-n=\"5074\">91</sup>, שמלבד זה מוכרח לומר שבעצם הגוף יש לו חיות המחיהו כמו שמצינו באדה\"ר שקודם ויפח באפיו נשמת חיים הי' לו ג\"כ ציור ודמות הגוף כמ\"ש ויצר הוי' את האדם<sup data-n=\"5075\">92</sup> עפר מן האדמה, שהי' לו ציור ודמות הגוף, ומאחר שכן הוא מוכרח לומר שיש לו חיות והוא האיהו שמתייחד עם גרמוהי. ועוד י\"ל זאת ממה שאנו רואים אילן בעת גידולו יש לו פירות ועלין וענפים דקים וכשתולשין אותו אז זורק מעליו העלין והפירות וענפים דקים והוא מפני שנחסר אצלו חיות וההוא נביעו איהו כנשמתא לגופא<sup data-n=\"5076\">93</sup>, אבל הנה האילן עצמו ה\"ה נשאר כציורו וכדמותו מוכרח לומר שיש לו חיות המחייהו. או אילן סתם שנתייבש שנפסק לו החיות כוח הצומח שבארץ ומ\"מ ה\"ה בציורו וכדמותו כמו קודם מוכרח לומר שיש לו חיות המחייהו, אך אח\"כ כשנרקב אז נפרד ההרכבה מד\"י ארמ\"ע<sup data-n=\"5077\">94</sup> אזי אין לו חיות אבל קודם לכן מוכרח לומר שיש לו חיות המחייהו וחיותו הוא האיהו. ועוד נוכל להבין זאת ממה שאנו רואים עצים כששורפין אותם נתעלו הג' יסודות אר\"מ ע\"י העשן ויסוד העפר<sup data-n=\"5078\">95</sup> נשאר למטה שהוא אפר, כי עפר ואפר דבר א' הוא<sup data-n=\"5079\">96</sup> כי אפר כשר לענין שחיטה כמו עפר<sup data-n=\"5080\">97</sup> וגם אנו רואים שהוא מצמיח כמו עפר מפני שעפר ואפר דבר א' הוא, מ\"מ מוכרח לומר שהם שני דברים כי מצינו באברהם שאמר ואנכי עפר ואפר<sup data-n=\"5081\">98</sup>, משמע שהם שני דברים שאל\"כ לל\"ל כפל לשון מובן מזה שהם שני דברים, וההפרש הוא ביניהם שבעפר יש בו ההרכבה מד' יסודות אבל באפר אין בו אלא יסוד העפר, מ\"מ מוכרח לומר שיש בו הד' יסודות רק שהם בהעלם כי יסוד א' אינו יכול להיות מציאות דבר ומאחר שהוא מציאות מוכרח לומר שיש לו חיות המחייהו והוא ע\"י שאיהו מתייחד עם גרמוהי.\n<b>וענין</b> איהו וחיוהי איך שנפרש הן שחיוהי הו\"ע מוחין אמרו רז\"ל איהו וחכ' ובינתו ודעתו א'<sup data-n=\"5082\">99</sup>, ה\"ה א' ממש, והגם שאנו קורין בש' חכמה ובינה ודעת מ\"מ א' הוא, והוא ע\"ד שאנו רואים בנפש האדם הלא כל הכחות יש בהנפש מ\"מ אינם יכולים להתחלק בהנפש ולומר שזהו כח זה וזה כח זה מ\"מ מוכרח לומר שיש",[["5072","89","<b>ונפשו עליו תאבל</b>: איוב יד, כב."],["5073","90","<b>קשה רימה למת</b>: ברכות יח, ב. שבת יג, ב."],["5074","91","<b>כמארז\"ל מתים יודעים או לא יודעים</b>: ועד\"ז הובא לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב (בחלק הנחותיו) בהנחה כאן על יד הערה 83 (ושם: ”הפלוגתא שבגמ' אם\"). ראה גם ברכות יח, א — יט, רע\"א. תוד\"ה אבותי סוטה לד, ב."],["5075","92","<b>ויצר הוי' את האדם</b>: בראשית ב, ז [ושם: וייצר ה\"א]."],["5076","93","<b>וההוא נביעו. . לגופא</b>: ת\"ז בהקדמה יז, א."],["5077","94","<b>מד\"י ארמ\"ע</b>: ראה שה\"א סו, א ובהערה 17. סה\"מ תרכ\"ט ע' קעט. וש\"נ. תרל\"ח ע' תצא."],["5078","95","<b>עצים כששורפין. . הג' יסודות. . העפר</b>: ראה גם אגה\"ק סט\"ו. סה\"מ תרל\"ח ע' רצו. וש\"נ."],["5079","96","<b>עפר ואפר דבר א' הוא</b>: ראה גם ש\"א מז, ב."],["5080","97","<b>אפר כשר. . כמו עפר</b>: ראה חולין פח, ב. תוד\"ה מצינו שם. שו\"ע יו\"ד הל' שחיטה סכ\"ח, סכ\"ג. תו\"א וישלח כו, רע\"ד."],["5081","98","<b>ואנכי עפר ואפר</b>: וירא יח, כז."],["5082","99","<b>אמרו רז\"ל איהו וחכ' ובינתו ודעתו א'</b>: ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"י. שער היחוד והאמונה פ\"ח. תניא פ\"ב. לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב (בחלק ההנחותיו) בהנחה כאן על יד הערה 89. (בחלק המאמרים) בההמשך כאן על יד הערה 232."]]],[2000480481,"בהנפש כל הכוחות והו\"ע ע\"ד שנת' שיש עקודים שע\"ס עקוד בכלי אחד<sup data-n=\"5083\">100</sup> ה\"ה ע\"ס ומ\"מ הם בכלי א' כך ענין מה שאיהו וחכמתו ובו\"ד אחד ה\"ה א' ממש. והן שנפרש שחיוהי הו\"ע אורות ג\"כ אין בו שום שינוי כי לכן נק' בש' אור ע\"ש שאין בו שום שינוי וע\"ד שזיו השמש אינו פועל שום שינוי בהשמש<sup data-n=\"5084\">101</sup> איך שמאיר כך ענין אור, ועש\"ז נק' בש' אוא\"ס כי בא\"ס עצמותו ומהותו א\"א לדבר כלל רק באוא\"ס<sup data-n=\"5085\">102</sup>, וגם במקום שנזכר א\"ס הכוונה הוא על אוא\"ס כי אין בו שום שינוי בין קודם הבריאה לאחר הבריאה כי אפי' לאחר שסילק את אורו הגדול אל הצד<sup data-n=\"5086\">103</sup> ג\"כ אין שינוי כי אני הוי' לא שניתי<sup data-n=\"5087\">104</sup> אתה הוא קודם שנברא<sup data-n=\"5088\">105</sup> העולם ואתה הוא לאחר שנברא העולם שאין בו שום שינוי בין קודם הבריאה לאחר הבריאה, כי חיוהי אינו אפי' מקור לעולמות. ופי' איהו קאי א\"ס<sup data-n=\"5089\">106</sup> עצמו\"ה וזהו איהו וחיוהי חד שאיהו מתייחד חיוהי<sup data-n=\"5090\">107</sup>.\n<b>ועוד</b> נוכל להבין ענין איהו וחיוהי ואיהו וגרמוהי ממה שמצינו בנפש האדם שיש בו ב' לבושין מח' ודיבור והנה דיבור הוא דבר לזולתו דהיינו אדם שיש לו דבר שכל ובכדי שימסור השכל לאחר הוא דוקא ע\"י דיבור כי כשיחשוב אפי' כל היום הן בעמידה ובישיבה או בהליכה לא ידע הזולת מה שחושב רק שידע שחשב אבל מה שחשב לא ידע כ\"א דוקא ע\"י דיבור מפני שדוקא דיבור הוא לזולתו, כי עשי' שלא יעשה הדבר יהי' נחסר אפי' לעצמו אבל דיבור לא יהי' נחסר לו כלל שהוא לזולתו. או יש בענין דיבור דהיינו שיאמר לאחר שישמש לו, הוא ג\"כ לזולתו, רק ההפרש הוא שהתם הוא גילוי לזולתו לפעולת זולתו וכאן הוא לפעולת עצמו נמצא שדיבור הוא דוקא לזולתו אבל ענין מחשבה הוא גילוי העלם עצמי'<sup data-n=\"5091\">108</sup> לגבי עצמו כי הנה אנו רואים בעת שאדם עוסק בדבר הלכה והבריק לו ברק המבריק<sup data-n=\"5092\">109</sup> אפשר שעל זה האופן יהי' ניחא, ואם יעבור איזה זמן רב ולא יהרהר בזה, או אם יבוא איש ויבלבל אותו, ממילא ישכח הברק שהבריק לו ולכאורה איך שייך שם שכחה הלא שכחה הוא מאחוריים<sup data-n=\"5093\">110</sup>, אך מאחר שיש שם שכחה מוכרח לומר שגם במוחין יש אחוריים, וכשם שיש לו ברק המבריק רק שלא מלביש אותו באותיו' המח'",[["5083","100","<b>שע\"ס עקוד בכלי אחד</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. תו\"א נח י, ג ואילך. תו\"ח וארא ח\"א נב, ד. וש\"נ. סה\"מ תרנ\"ב ע' ק ואילך. תרל\"ח ס\"ע עה ואילך ובהערה 274."],["5084","101","<b>שזיו השמש אינו פועל שום שינוי בהשמש</b>: ראה לקו\"ת שה\"ש יד, ג. אוה\"ת ואתחנן כרך ו ע' ב'רמו."],["5085","102","<b>בא\"ס. . באוא\"ס</b>: ראה גם תו\"א וירא יד, ב. לקו\"ת נצבים מט, סע\"א."],["5086","103","<b>שסילק את אורו הגדול אל הצד</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 216."],["5087","104","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["5088","105","<b>אתה הוא קודם שנברא</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["5089","106","<b>קאי א\"ס</b>: אוצ\"ל: קאי על א\"ס."],["5090","107","<b>מתייחד חיוהי</b>: אוצ\"ל: מתייחד עם חיוהי."],["5091","108","<b>עצמי'</b>: אוצ\"ל: עצמי."],["5092","109","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק לעיל (בחלק המאמרים) המשך יונתי רפ\"ד. וש\"נ."],["5093","110","<b>שכחה הוא מאחוריים</b>: ראה קו\"א דוד זמירות (תניא קסא, א). מאו\"א מערכת שכחה סל\"ז וביאיר נתיב שם. רמ\"ז לזהר בחוקותי קיב, א (ד\"ה אר\"י א\"ל — ע' צז בדפי הספר)."]]],[2000480482,"אינה פעולה כמו\"כ באם שיש לו אותיו' המח' ואין לו ברק המבריק אין פעולה מזה כי זה וזה גורם. כן יובן בנמשל שענין איהו וגרמוהי הוא כמו משל דדיבור שדיבור הוא דבר לזולתו כמו\"כ ענין גרמוהי כדי שלהיות דבר יש בפ\"ע לפעולת הזולת שהאיהו שמתייחד עם גרמוהי הוא כח הגבול שבא\"ס כי כשם שכחו בבל\"ג כך כחו בגבול<sup data-n=\"5094\">111</sup> שאל\"כ הרי אנת הוא<sup data-n=\"5095\">112</sup> מחסר שלימותו ואי' אנת הוא שלימותא דכולהו, אבל חיוהי הו\"ע שהוא לעצמו, והוא וחכ' ורצונו א'<sup data-n=\"5096\">113</sup> ה\"ז עצמי', והגם שאין המשל דומה לנמשל, אך הנה לגבי' אז אין המשל דומה להנמשל אבל לגבי הזולת ה\"ה עצמי', והגם שאי' בתני' שגם חכ' אינה עצמי' הנפש<sup data-n=\"5097\">114</sup> אלא הו\"ע לבוש אך י\"ל שבאמת הוא לבוש אך יש הפרש בלבוש שיש ב' מיני לבושין כמו שאי' וכמה לבושין תקינת להון<sup data-n=\"5098\">115</sup> וכמה גופין תקינת להון<sup data-n=\"5099\">116</sup>, וההפרש הוא שלבוש יכול לפשוט וללבוש שפושט זה הלבוש ולובש לבוש זה אבל גוף<sup data-n=\"5100\">117</sup> הגם שהוא ג\"כ לבוש מ\"מ אין ביכולתו מגוף<sup data-n=\"5101\">118</sup> הזה וללבוש בגוף אחר, וגם מהגוף שהוא שם אינו יכול לפשוט, רק זאת יש ביכולתו להזדכך<sup data-n=\"5102\">119</sup> אותו אבל לא לפשוט כי בע\"כ אתה חי<sup data-n=\"5103\">120</sup>. ועוד י\"ל שהוא לבוש ע\"ד מארז\"ל כהדין קמצא<sup data-n=\"5104\">121</sup> דלבושי' מיני' ובי' ה\"ה מיני' ובי' שהוא עצמי' כמו\"כ ענין חיוהי הו\"ע עצמי'. וענין חיוהי למעלה הו\"ע ידיעת<sup data-n=\"5105\">122</sup> עצמותו יודע את התורה, כי הוא וחכ' ובינתו ודעתו אחד, וזהו כמ\"ש לא ידע אנוש ערכה<sup data-n=\"5106\">123</sup> אלקי' הבין דרכה<sup data-n=\"5107\">124</sup> שאצל אלקי' כתי' הבין ע\"פ טו\"ד שזהו\"ע גרמוהי אבל התם כתי' ידע שהוא למעלה מטו\"ד והוא ע\"ד ידיעת השלילה<sup data-n=\"5108\">125</sup> וי\"ל שהוא ע\"ד ואדם ידע את חוה<sup data-n=\"5109\">126</sup> שיכול להיות להוליד בדומה לו שהוא עצמי'. וזהו\"ע איהו וחיוהי.\n<b>ומעתה</b> יובן ענין ירידת הנשמה בגוף אעפ\"י שהיא ירידה גדולה ועצומה וכל הדרכים בחזקת סכנה מ\"מ כדאי הוא מפני שהיא ירידה צורך עלי'",[["5094","111","<b>כשם שכחו בבל\"ג כך כחו בגבול</b>: ראה עבודת הקודש ח\"א רפ\"ח. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 224."],["5095","112","<b>אנת הוא</b>: אוצ\"ל: אתה."],["5096","113","<b>והוא וחכ' ורצונו א'</b>: ראה אגה\"ק סכ\"ו (קמד, א). לקו\"ת שה\"ש יג, ב. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים על יד הערה 56."],["5097","114","<b>שאי' בתני' שגם חכ' אינה עצמי' הנפש</b>: ראה גם (לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב בחלק הנחותיו) בהנחה כאן ובהערה 104."],["5098","115","<b>וכמה לבושין. . להון</b>: ראה ת\"ז בהקדמה יז, א. הדרת מלך ע' קיא."],["5099","116","<b>וכמה גופין. . להון</b>: ראה ת\"ז שם."],["5100","117","<b>וההפרש הוא שלבוש. . אבל גוף</b>: ראה אוה\"ת על ענינים ע' קיג ואילך (ובהנסמן בריש המאמר שם). ע' קמג ואילך."],["5101","118","<b>ביכולתו מגוף</b>: אוצ\"ל: ביכולתו לפשוט א\"ע מגוף."],["5102","119","<b>להזדכך</b>: אוצ\"ל: לזכך."],["5103","120","<b>בע\"כ אתה חי</b>: ראה אבות ספ\"ד."],["5104","121","<b>כהדין קמצא</b>: ראה ב\"ר פכ\"א, ה. (לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב בחלק הנחותיו) בהנחה כאן הערה 107."],["5105","122","<b>ידיעת</b>: אוצ\"ל: בידיעת."],["5106","123","<b>לא ידע אנוש ערכה</b>: איוב כח, יג."],["5107","124","<b>אלקי' הבין דרכה</b>: איוב שם, כג."],["5108","125","<b>ידיעת השלילה</b>: ראה גם (לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב בחלק הנחותיו) בהנחה כאן הערה 90."],["5109","126","<b>ואדם ידע את חוה</b>: בראשית ד, א [ושם: והאדם]."]]],[2000480483,"והעלי' הוא מאיהו וגרמוהי לאיהו וחיוהי, והגם שנת' למעלה שגרמוהי הוא מד' גבוה אשר לא נגע בה הצמצום ושם הוא שורש הנשמה אשר נתת בי טהורה היא שהיא טהורה עילאה ועוד אפי'<sup data-n=\"5110\">127</sup> שקאי על אותיו' הרשימה ואפשר לומר עוד מד' גבוה אותיו' החקיקה ועוד גבוה על גליף גליפי' בטהירו עילאה<sup data-n=\"5111\">128</sup> שהו\"ע שהקלף נושא וסובל האותיות אך מ\"מ ה\"ז ענין גרמוהי שהו\"ע כלים שהיא בריאה יש מאין, ולכאו' איך שייך שם בריאה יש מאין אך הנה נת' שאפי' בא\"ק יש ג\"כ ענין בריאה<sup data-n=\"5112\">129</sup> יש מאין ובע\"ח איתא שהו\"ע קיפל מלבושי'<sup data-n=\"5113\">130</sup>, והעלי' הוא באיהו וחיוהי שהוא וחכ' ובינתו ודעתו אחד שהו\"ע עצמי' שהוא למעלה מטו\"ד. ולכן ניחא ירידת הנשמה בגוף אעפ\"י שהיא ירידה גדולה ועצומה ואפי' כשתתעורר אהוי\"ר אין ערוך להאהוי\"ר שהיתה לה מקודם אך מ\"מ זהו רק לפי ראות עינים אבל כשהעלי' הוא באיהו וחיוהי ששם הוא למעלה מטו\"ד אזי יכולה לבוא לאשתאבה בגופא דמלכא<sup data-n=\"5114\">131</sup>. ומעתה יובן מה שאי' במד\"ר נרי בידך ונרך בידי אם אתם משמר<sup data-n=\"5115\">132</sup> את נרי הרי אני משמר אתכם<sup data-n=\"5116\">133</sup> ולכאו' הלא בל\"ה אי' אתה משמרה בקרבי אך התם כתי' אתה שהו\"ע גילוים ששייך לעולמות אבל ע\"י קיום תומ\"צ הרי אני משמר אתכם פי' אני הוא א\"ס עצומ\"ה כי נפ\"א הוא חלק אלקה ממעל כמ\"ש כי חלק הוי' עמו שי\"ה הענין<sup data-n=\"5117\">134</sup> חיוהי ו\"ה הו\"ע גרמוהי והעלי' הוא מאיהו וגרמוהי לאיהו וחיוהי.\n<b>ובזה</b> יובן מ\"ש יפה שעה א' בתשומע\"ט כו' דהנה ארז\"ל עתיד הקב\"ה להנחיל לכל צו\"צ ש\"י עולמות<sup data-n=\"5118\">135</sup>, הנה ש\"י הוא מחצה מתר\"ך<sup data-n=\"5119\">136</sup> שתר\"ך הו\"ע כתר<sup data-n=\"5120\">137</sup> שבכתר יש ב' חצאין<sup data-n=\"5121\">138</sup> חצי' העליון הוא מד' התחתונה שבמאציל וחצי' התחתון הוא ראש ומקור לנאצלים וש\"י הוא מחצה התחתון ולכן נק' עולמות שהו\"ע העלם<sup data-n=\"5122\">139</sup> אבל יפה שעה א' בעוה\"ז בתשומע\"ט כי ע\"י תרי\"ג מצות דאורייתא וז' מצות דרבנן שהם תר\"ך<sup data-n=\"5123\">140</sup> עמודי אור<sup data-n=\"5124\">141</sup> באים לבחי' כתר לב' החצאין שיש בכל חציו ע\"ס, והגם",[["5110","127","<b>אפי'</b>: אוצ\"ל: אפשר."],["5111","128","<b>גליף גליפי' בטהירו עילאה</b>: ראה זהר בראשית טו, א."],["5112","129","<b>בא\"ק. . בריאה</b>: ראה ע\"ח שער סדר אצי' ש\"ג, רפ\"א."],["5113","130","<b>ובע\"ח אי' שהו\"ע קיפל מלבושי'</b>: ראה גם (לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב בחלק הנחותיו) בהנחה כאן הערה 115."],["5114","131","<b>לאשתאבה בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 51."],["5115","132","<b>אתם משמר</b>: לעיל בפיסקא אך להבין זה הובא: אתה משמר."],["5116","133","<b>אתכם</b>: לעיל שם הובא: את נרכם."],["5117","134","<b>הענין</b>: אוצ\"ל: הוא ענין."],["5118","135","<b>עתיד. . לכל צו\"צ ש\"י עולמות</b>: עוקצי' בסופה. ראה גם אוה\"ת בהעלותך ע' תטז."],["5119","136","<b>ש\"י הוא מחצה מתר\"ך</b>: ראה הקדמת הראב\"ד לס\"י ירושלים תשכ\"ב ד, א."],["5120","137","<b>שתר\"ך הו\"ע כתר</b>: ראה ע\"ח שער ז\"א שי\"ז, ספ\"א. לעיל ח\"א (בהנחת כ\"ק אדמו\"ר מהורש\"ב בחלק הנחותיו) הנחה ד\"ה וירא העם וינועו הערה 54."],["5121","138","<b>שבכתר יש ב' חצאין</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א."],["5122","139","<b>עולמות שהו\"ע העלם</b>: ראה ספר הבהיר ס\"י. תו\"ח שמות ח\"א יח, ד הערה 783."],["5123","140","<b>תרי\"ג מצות דאורייתא וז' מצות דרבנן שהם תר\"ך</b>: ראה לעיל ח\"א (בהנחת כ\"ק אדמו\"ר מהורש\"ב בחלק הנחותיו) הנחה ד\"ה סמכוני באשישות הערות 80-83."],["5124","141","<b>תר\"ך עמודי אור</b>: ראה לקו\"ת להאריז\"ל חבקוק. מאמרי אדה\"א ויקרא ח\"ב ע' תסא. וש\"נ. תו\"ח בראשית מה, ג הערה 32."]]],[2000480484,"שיפה עשיות המצוה מהתשלום שכר מ\"מ אינו מקפח שכר כל ברי' כי ארז\"ל עתיד הקב\"ה לעשות ראש מחול לצדיקים לע\"ל<sup data-n=\"5125\">142</sup> פי' מחול הוא בחי' עיגול שז\"ע כלליות הכתר והיינו שכר מצוה מצוה<sup data-n=\"5126\">143</sup> פי' המצוה בעצמה יהי' השכר ונמצא כי הגם שיפה שעה א' כו' עכ\"ז לא יקפח השכר שהרי לע\"ל יתגלה עצם המצוה כמו שהיא ברוחני' שהוא רצה\"ע.",[["5125","142","<b>עתיד. . ראש מחול לצדיקים לע\"ל</b>: ראה ירושלמי מוע\"ק פ\"ג, ה\"ז. מגילה פ\"ב, ה\"ד. ויק\"ר פי\"א, ט. תענית לא, א. לקו\"ת ואתחנן ז, סע\"ב. לקו\"ש ט\"ו באב כרך כד ע' 66 ובהערה 76."],["5126","143","<b>שכר מצוה מצוה</b>: אבות פ\"ד, מ\"ב. ראה לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 230."]]],[2000480485,"<h3>לכל תכלה ראיתי קץ</h3>\n<b>בס\"ד</b>\n<b>לכל</b> תכלה ראיתי קץ<sup data-n=\"5127\">1</sup> רחבה מצותיך מאד<sup data-n=\"5128\">2</sup>, ופי' המפרשים לכל תכלה לכל דבר שיש לה כליון ראיתי שיש סיום וקץ להדבר אבל רחבה מצותך מאד שלמצות אין להם סיום וקץ שהוא בלי גבול. וצ\"ל איך פסק שאין להם סיום וקץ שהוא מפני שלא השיג הסיום והקץ אפשר שגם הוא דוקא לא השיג אבל יכול להיות שאחר יכול להשיג שיש להם סיום וקץ, ואיך פסק שאין להם סיום וקץ. ועוד צ\"ל מה שאמר רחבה מצותך מאד שמצות הם מד' מאד שהם בלי גבול<sup data-n=\"5129\">3</sup> הלא מצות הם ענין הגבלה כמו מצות סוכה הם ז' טפחים ומשהו<sup data-n=\"5130\">4</sup> או ד' מינים שבלולב וכמו\"כ כל המצות הם ענין הגבלה ואיך יכול להיות שהם בלי גבול ובאמת גבול ובלי גבול הם מרוחקים זה מזה שלא בערך<sup data-n=\"5131\">5</sup> כי אנו רואים עד\"מ שני קצוות מזרח ומערב שמזרח הוא גבול ומערב הוא גבול ושטח הגבול שמפסיק ביניהם מצד זה אינם יכולים להיות ביחד, והנה מה שזה גבול וזה גבול אינם יכולים להתייחד מכש\"כ מצות שהם גבול בודאי אינם יכולים להיות במד' בלי גבול, אך להבין זה צ\"ל תחילה ענין ירידת הנשמה בגוף שלכאורה היא ירידה גדולה ועצומה ובשביל מה הי' הירידה בשביל העלי'",[["5127","1","<b>לכל תכלה ראיתי קץ</b>: הנחה ממאמר הד' מהמשך יונתי (פי\"א-פי\"ב) שנדפס לעיל בחלק המאמרים [ושם הפתיחה: אך עדיין צ\"ל מאחר שבחי' חיוהי].\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לעיל (בחלק הנחותיו)."],["5128","2","<b>לכל תכלה ראיתי קץ רחבה מצותיך מאד</b>: תהלים קיט, צו. ראה גם לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב (בחלק הנחותיו) כאן בתחילתה. אוה\"ת בראשית כרך ג ע' 1010 ואילך. סה\"מ תרס\"ו ע' כ."],["5129","3","<b>מאד שהם בלי גבול</b>: ראה אגה\"ק סי\"ז. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 99."],["5130","4","<b>מצות סוכה הם ז' טפחים ומשהו</b>: באגה\"ק ס\"י ז\"ט. ראה גם לעיל (בחלק המאמרים) בההמשך כאן ובהערה 270. סה\"מ תרל\"ב ח\"א ע' פד ובהערה שם."],["5131","5","<b>גבול ובלי גבול. . שלא בערך</b>: ראה גם (לעיל הנחת כ\"ק אדמו\"ר מהורש\"ב — בחלק הנחותיו) הנחה ד\"ה יפה שעה אחת הערה 111."]]],[2000480486,"שיהי' אח\"כ שהו\"ע ירידה צורך עלי'<sup data-n=\"5132\">6</sup> שכדאי הירידה בשביל העלי', והעלי' הוא מאיהו וגרמוהי לאיהו<sup data-n=\"5133\">7</sup> וחיוהי<sup data-n=\"5134\">8</sup>, ואף ששרש הנשמה הוא ממדריגה גבוה אלקי נשמה<sup data-n=\"5135\">9</sup> שנתת בי טהורה<sup data-n=\"5136\">11</sup> היא שהו\"ע טהורה עילאה<sup data-n=\"5137\">10</sup> מ\"מ ה\"ז גרמוהי אבל העלי' הוא בחיוהי, ולא בחיוהי לחוד אלא באיהו שמתייחד עם חיוהי. והנה נת' שענין איהו וחיוהי למעלה הו\"ע ידיעת עצמותו יודע את התורה<sup data-n=\"5138\">12</sup>. וצ\"ל פי' של בידיעת עצמותו יודע את התורה<sup data-n=\"5139\">13</sup> כי מאחר שהוא בידיעת עצמותו שאינו שייך לגבי זולתו שהוא דוקא לגבי עצמותו לכאורה למה נאצל הבחי' זו כי לגבי' ית' ה\"ז ידוע תחילה קודם שנאצל כי אנת הוא שלימותא דכולהו<sup data-n=\"5140\">14</sup>, וכלום חסר, ולגבי הזולת אינו שייך אפי' לאחר שנאצל וצ\"ל מהו ההתחדשות במה שנאצל בחי' הזו.\n<b>אך</b> הענין הוא בכדי שיוכל להיות מא\"ס שהוא פשוט בתכלית הפשיטות יהי' אפי' בחי' לאו בחכמה ידיעה<sup data-n=\"5141\">15</sup> וכש\"כ חכ' ידיעה שהוא חכמת התורה צ\"ל להיות<sup data-n=\"5142\">16</sup> תחילה ענין ידיעת עצמותו, כי מא\"ס עצמותו ומהותו אינו יכול להיות חכ' ידיעה שהיא חכמת התורה וכן אפי' לאו בחכ' ידיעה, לכן ע\"י שנאצל בחי' ידיעת עצמותו אז יכול להיות חכמת התורה, כי אפי' בחי' אלפים שנה קדמה תורה לעולם<sup data-n=\"5143\">17</sup> ואיך שנפרש פירושו הן שקאי על בחי' אאלפך חכ' אאלפך בינה<sup data-n=\"5144\">18</sup> שהו\"ע חו\"ב דע\"ס דאצי'<sup data-n=\"5145\">19</sup> והן שהו\"ע כללות סדר השתל'<sup data-n=\"5146\">20</sup> העולמות אינה יכולה להיות אא\"כ שנאצל תחילה ידיעת עצמותו אז יכול להיות יודע את התורה. ועוד י\"ל זאת ממה שיש בחכ' שני בחי' יש חכים לא בחכ' ידיעה<sup data-n=\"5147\">21</sup> ויש חכ' ידוע שיכול להיות מורגש גם לזולתו, ואף שמוחין איז דאך אויף גיטראגין ממדות, כי מדות הם דוקא לזולתו כמו רחמן",[["5132","6","<b>ירידה צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["5133","7","<b>והעלי'. . לאיהו וחיוהי</b>: ראה בהנחה ד\"ה יפה שעה שלפנ\"ז."],["5134","8","<b>מאיהו וגרמוהי לאיהו וחיוהי</b>: ראה ת\"ז בהקדמה ג, ב. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 99."],["5135","9","<b>אלקי נשמה</b>: ברכת אלקי נשמה (מברכות ס, ב)."],["5136","11","<b>טהורה</b>: בכמה מקומות בכת\"י זה כותב: ”טהורה\" במקום תיבת ”טהירו\"."],["5137","10","<b>טהורה. . טהורה עילאה</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 211."],["5138","12","<b>איהו וחיוהי. . יודע את התורה</b>: ראה לעיל בהנחה ד\"ה יפה שעה על יד הערה 122."],["5139","13","<b>בידיעת עצמותו יודע את התורה</b>: ראה קו\"א דוד זמירות (תניא קסא, א). וראה גם (לעיל בחלק המאמרים) המשך יונתי פ\"י על יד הערה 239 ואילך."],["5140","14","<b>אנת הוא שלימותא דכולהו</b>: ראה ת\"ז בהקדמה יז, ב."],["5141","15","<b>לאו בחכ' ידיעה</b>: נסמן בסמוך הערה 21."],["5142","16","<b>להיות</b>: כנראה שתיבה זו מיותרת."],["5143","17","<b>אלפים שנה קדמה תורה לעולם</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ. מאמר ד\"ה זה תשי\"א יום ב' דחה\"ש."],["5144","18","<b>אאלפך חכ' אאלפך בינה</b>: ע\"פ איוב לג, ג. שבת קד, א."],["5145","19","<b>אלפים. . חו\"ב דע\"ס דאצי'</b>: ראה לקו\"ת שה\"ש א, סע\"ד ואילך."],["5146","20","<b>אלפים. . כללות סדר השתל'</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' שכא וע' שכד (נו\"ש). ראה גם סה\"מ תרל\"ח ע' תקב. ע' תקיב (וש\"נ)."],["5147","21","<b>חכים לא בחכ' ידיעה</b>: ז\"ח יתרו לד, ד. ת\"ז בהקדמה יז, ב."]]],[2000480487,"או חסדן או שמדתו להטיב שהוא דוקא לזולתו שיש על מי להתרחם או למי שיתחסד ולמי להיטיב אבל כשאין זולת לא שייך המדה, ואף שאדה\"ר הי' לו מדות ומסתמא הי' משפיעה<sup data-n=\"5148\">23</sup> טוב, אך מחמת שהי' נבראים ג\"כ שהו\"ע זולת אבל אדם שהוא בפני עצמו אינו שייך אצלו מדות אלא כ\"א שיש אצלו אפי' דשאים ועשבים שיכול להטיב עמהם שיצמיחו ומשקה אותן אבל כשאין עמו זולת כלל אינו שייך אצלו מדות, והגם שיש לו המדה והרצון של המדה ומרגיש אותה, אך מ\"מ ה\"ה כאלו אינה, כי מאי נפקא מיני' אם יש לו המדה אם אינה, כי מאחר שאין פעולה מהמדה ה\"ה כלא הי', נמצא שמדות הם דוקא לזולתו אבל חכ' הוא לעצמו<sup data-n=\"5149\">22</sup> כמו שאנו רואים באדם שיכול להשכיל כמה השכלות בעומק גדול ולא ישפיע לזולתו כלל וכמו שאי' אלפים שנה קדמה תורה לעולם שאעפ\"י שלא הי' העולם שהו\"ע זולת מ\"מ הי' שייך בחי' חו\"ב. ומה שאי' ומתלמידי יותר מכולם<sup data-n=\"5150\">24</sup>, אין הפי' שניתוסף אצלו דבר חדש, אלא שהי' תחילה ג\"כ רק שהי' בהעלם במשכיל ואח\"כ נמשך אל השכל אבל התחדשות בא דוקא לעצמו בלא זולתו כמו שמצינו ברשב\"י אעפ\"י שהי' יחיד במערה<sup data-n=\"5151\">26</sup> מ\"מ ניתוסף אצלו חכ' עד אין שיעור, כי קודם שהי' במערה הי' הוא השואל ור' פינחס ב\"י הי' המשיב וכמה הי' משיב לו י\"ב פירוקי', ואח\"כ ע\"י שהי' רשב\"י במערה ניתוסף כ\"כ חכ' אצלו עד שהי' הוא המשיב וכמה כ\"ד פירוקי'<sup data-n=\"5152\">25</sup> בכפל, נמצא שמוחין שייכים דוקא לעצמו.\n<b>וכן</b> יובן למעלה הנה מדות אינם שייכים אלא לזולת דוקא כמ\"ש זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"5153\">27</sup>, אימתי שייך רחמים וחסדים שיש עולם דוקא שהו\"ע זולת כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"5154\">28</sup>, כשיש בחי' עולם אז שייך מדות החסד, אף שהי' מדות החסד קודם אך לא הי' רק בהעלם אבל כשנעשה העולם נבנה מדות החסד כדבעי, נמצא שמדות שייכים דוקא לזולתו אבל מוחין הם לעצמן. ומ\"מ י\"ל שמוחין ג\"כ שייך לזולתו רק שאינו הכרחי להיות לזולתו כמו מדות<sup data-n=\"5155\">29</sup> שאם לא הזולת אינם המדות מדות, ומוחין יכול להיות לעצמו, מ\"מ יכול להיות גם לזולתו כמו שאנו רואים עד\"מ אדם שעוסק בדבר הלכה ומבין בעומק השכלה מדבר הלכה יכול להשפיעה<sup data-n=\"5156\">30</sup> גם לזולתו והזולת הוא מרגיש השכל, ומאחר שהמקבל הוא מרגיש מוכרח שגם המשפיע השכל, השכל מורגש אצלו, כי אין המשפיע יכול להשפיע דבר שכל אלא א\"כ שיבין תחילה. וזהו\"ע חכמה ידיעה.",[["5148","23","<b>משפיעה</b>: כנצ\"ל: משפיע."],["5149","22","<b>מדות. . לזולתו. . חכ' הוא לעצמו</b>: ראה (לעיל בחלק המאמרים) המשך יונתי כאן ובהערה 261."],["5150","24","<b>ומתלמידי יותר מכולם</b>: תענית ז, א. ראה גם לעיל ח\"א (חלק המאמרים) המשך מצה זו ובהערה 538."],["5151","26","<b>ברשב\"י. . יחיד במערה</b>: בשבת שם עם ר\"א בנו. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וירא העם וינועו ובהערה 92."],["5152","25","<b>ברשב\"י. . כ\"ד פירוקי'</b>: שבת לג, ב."],["5153","27","<b>זכור רחמיך. . המה</b>: תהלים כה, ו [בדילוג השם]."],["5154","28","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם סה\"מ תרל\"ח ע' מח ובהערה 220 (בע' מז)."],["5155","29","<b>כמו מדות</b>: תיבות אלו נכפלו בהכת\"י."],["5156","30","<b>להשפיעה</b>: כנצ\"ל: להשפיע."]]],[2000480488,"<b>אך</b> הנה יש בחי' שהוא לא בחכ' ידיעה שהו\"ע ידיעת עצמותו שאינו מורגש אפי' לעצמו, והוא הממוצע בין א\"ס שפשוט בתכלית הפשיטות לבין בחי' חכמה ידועה<sup data-n=\"5157\">31</sup> שהוא חכמת התורה. ולכאורה צ\"ל פירושו של חכים לא בחכ' ידיעה, ממ\"נ אם הוא חכים איך הוא לא ידוע, ואם לא ידוע איך שייך חכים. וע\"ז הוא ענין ידיעת עצמותו שהוא שולל חכמה ידיעה שחכ' ידוע הוא לזולתו אבל ידיעת עצמותו הוא הידיעה שכלול בעצמי' שהוא חכים אבל לא בחכ' ידיעה והוא עד\"מ אור שכלול במאור שבעת שהוא כלול במאור אז לא עולה בשם אור כלל<sup data-n=\"5158\">32</sup> אלא הוא בטל במאור כמו\"כ ענין ידיעת עצמותו הידיעה שהיא כלולה בעצמי'. ובאמת אין המשל דומה לנמשל כי באור יש שינוי כמ\"ש המאיר לארץ ולדרים עליה<sup data-n=\"5159\">33</sup>, שבעת שמאיר האור אז האדם הוא בשמחה אויפגיטראגין אבל ביום המעונן גם האדם הוא בשפלות און איז ן גיריקט, נמצא שיש שינוי בהאור, שזהו מפני שהאור הוא מוגבל והמאור הוא מוגבל שהאור הוא מעין המאור לכן יש שינוי למטה והרגשה, אבל למעלה כשם שהוא א\"ס כך הידיעה הוא ג\"כ א\"ס וזהו פי' של ידיעת עצמותו שהידיעה שהוא כלול בעצמי'. ולכאורה צ\"ל כיון שהיא ידיעת עצמותו יודע את התורה שהו\"ע פועל ונפעל איך שייך בעצמותו ענין פועל ונפעל.\n<b>אך</b> הנה משל ע\"ז א\"א לדמות כי איזה משל אנו יכולים להביא ממה שאתנו ה\"ה הגבלה ולמעלה הוא בלי גבול ואיך יכול לדמות בלי גבול מגבול אך בכדי לקרב אל השכל הענין הוא כי כמו שאנו רואים באדם שמשכיל איזה השכלה ומבין אותה היטיב בכל הסברות רק שאינו רוצה שידע גם הזולת לכן אינה אומרה מחמת שיש לו טעם כמוס לזה. או אדם שמוצא אוצר ואינו רוצה שידע הזולת הרי אצלו היא ידועה רק להזולת ה\"ה לא ידוע אבל לעצמו ה\"ה יודע כי במשל דהאוצר הרי יכול לספור ולמדוד האוצר וכמו\"כ השכל יכול ג\"כ להתבונן היטיב איך עומק השכל והשכלתה ה\"ה ידוע ורק להזולת ה\"ה לא ידועה, וזהו הטעם שמצינו מחברים שעשו בעצמם השאלה והתשובה<sup data-n=\"5160\">34</sup> כדי שלא ידעו מי הוא העושה שו\"ת אבל לעצמם ה\"ה ידוע. אבל מצינו עוד בחי' אחרת דהיינו כשאדם עוסק בדבר הלכה בעומק ליבון שיש כאן שכל עמוק רק אינו יודע השכל מה הוא עושה חוזר ועוסק בה וגם אינו יודע אותה בפעם השני' וכן כמה פעמים ולא מבין העומק מ\"מ נק' חכם רק שהוא לא ידוע אבל מ\"מ חכים הוא כי איש פשוט שיעסוק בדבר הלכה הזה לא ידע כלל שיש בה עומק וזה יודע שיש בה שכל עמוק רק אינה יודע מה הוא השכל, ה\"ה חכים לא בחכ' ידיעה. או עד\"מ אדם שהוא מוחזק לחכם גדול שואלים אותו כמה ענינים ואף שאינו יודע הענין וזר מהענין ולמה שואלים אותו רק מפני שמוחזק לחכם גדול וזה כמה פעמים שאלו אותו ועלתה בידם לכן סובר מסתמא כשיספר לו יבין טוב ממנו ויתן לו עצה ע\"ז, וזהו ג\"כ בחי' חכים אך לא בחכ' ידיעה, או",[["5157","31","<b>ידועה. . אינה</b>: כ\"ה בהכת\"י."],["5158","32","<b>אור שכלול במאור. . בשם אור כלל</b>: ראה שער היחוד והאמונה פ\"ג."],["5159","33","<b>המאיר לארץ ולדרים עליה</b>: נוסח ברכת יוצר."],["5160","34","<b>מחברים שעשו בעצמם השאלה והתשובה</b>: לדוגמא שו\"ת תרומת הדשן — ראה שם הגדולים מערכת מהר\"ר ישראל. . איסרלאן (אות תב)."]]],[2000480489,"כמארז\"ל איזה חכם הרואה את הנולד<sup data-n=\"5161\">35</sup> פי' נולד לא שכבר הוליד שא\"כ כל אדם יכול לראות וידע ולמה דוקא חכם אלא פי' נולד שיולד לאחר זמן וזהו מפני שהוא חכם גדול ע\"כ יכול להבין לפי ההנהגה דעכשיו מה שיהי' לאחר כמה שנים, ואפי' לאחר מאה שנה, וזהו דוקא חכם כי אדם שאינו חכם אינו יודע איך יהי' צורת הוולד אחר שיצא מבטן אמו רק חכ' שמבין לפי ההנהגה דעכשיו מה שיהי' לאחר זמן כמו שאנו רואים ששואלים אצל חכם ענין מה שלא שמע וזר מהענין ולמה הולכים לשאול אצלו אך לפי שהוא מוחזק לאדם גדול ויבין מה שיהי' מזה, וזהו לגבי הזולת הוא לא ידוע, וגם מצד עצמו הלא קודם ששמע הענין מה ששואלים אותו איך יכול להכניס עצמו שיענה ע\"ז והוא מפני שמרגיש את רוב חכמתו ורוב גדלו איך שהוא חכם בודאי ידע מה להשיב נמצא שזהו חכים רק לא בחכ' ידיעה, וזהו פי' ידיעת עצמותו שהידיעה היא כלולה בעצמי' והיא ממוצע בין א\"ס שפשוט בתכלית הפשיטות לבין חכ' התורה שהיא חכ' ידועה, לכן מוכרח שנאצל תחילה ענין ידיעת עצמותו שהידיעה היא כלולה בעצמי'. אך באמת אין המשל דומה לנמשל, רק מפני שיש אצלינו ענין ידוע מוכרח לומר שיש ג\"כ הבחי' הזו למעלה, כי כדי להבין ענין אלקות מוכרחים לתאר ולכנה כמו שהיא אצלינו.\n<b>וזהו</b> העלי' דנשמה מאיהו וגרמוהי לאיהו וחיוהי, והוא ע\"י שירדה הנשמה בגוף ונה\"ב ומקיים תורה ומצות גשמי' אז העלי' הוא לאיהו וחיוהי, ופי' איהו וחיוהי חד אין הפי' שאיהו מתייחד עם חיוהי אלא אחד הוא ממש. ולכאורה איך יכולה הנשמה לעלות לבחי' איהו וחיוהי שהוא בחי' בלי גבול ונת' שהעלי' הוא ע\"י תורה ומצות<sup data-n=\"5162\">36</sup> הלא מצות הם ענין הגבלה כמו סוכה ז' טפחים ומשהו, וד' מינים שבלולב, ולולב יוצא טפח<sup data-n=\"5163\">37</sup> מן ההדס, וסוכה שהיא גבוה<sup data-n=\"5164\">38</sup> מעשרים אמה פסולה, ואתרוג דוקא שהוא גדול כך ואם פחות פסול<sup data-n=\"5165\">39</sup>, נמצא שהו\"ע הגבלה ואיך יכול להיות שע\"י נתעלה הנשמה לאיהו וחיוהי שהיא בלי גבול שאין ערוך גבול לבלי גבול. אך ע\"ז כתי' לכל תכלה ראיתי קץ רחבה מצותך מאוד פי' לכל תכלה לכל דבר שיש כלות פי' כלות כמ\"ש כלתה לך נפשי<sup data-n=\"5166\">40</sup>, כלה שארי ולבבי<sup data-n=\"5167\">41</sup>, ע\"ז ראיתי קץ שיש סיום וקץ להדבר כי אפי' ג\"ע שיש להאדם תשוקה וכלות לזה ה\"ה סיום וקץ, כי הוא גבוה מעולם עשי' כי עשי' הוא מז' תחתונות והג\"ע הו\"ע ג\"ר<sup data-n=\"5168\">42</sup> כי כשאדם הוא חסדן או רחמן ושיש לו אהוי\"ר או שיעמיק מוחין שלו באלקות נותנין לו השכר ע\"ז ג\"ר דעשי', שהו\"ע ג\"ע דעשי' כי המדות הם נמשכים ממוחין כי כשאדם מבין",[["5161","35","<b>איזה חכם. . הנולד</b>: ראה תמיד לב, א."],["5162","36","<b>ונת'. . תורה ומצות</b>: לעיל הנחה ד\"ה יפה שעה אחת."],["5163","37","<b>ולולב יוצא טפח</b>: ראה שו\"ע אדה\"ז הל' לולב סתר\"נ."],["5164","38","<b>וסוכה שהיא גבוה</b>: משנה סוכה ב, א [ושם גבוהה — ראה שנויי נוסחאות במשניות שם. סה\"מ תרל\"ח ע' רלו. וש\"נ]."],["5165","39","<b>ואתרוג. . פחות פסול</b>: ראה שו\"ע אדה\"ז הל' לולב סתרמ\"ח, סכ\"ט."],["5166","40","<b>כלתה לך נפשי</b>: תהלים פד, ג (בהוספת תיבת לך)."],["5167","41","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["5168","42","<b>והג\"ע הו\"ע ג\"ר</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן הערה 275."]]],[2000480490,"שטוב הדבר לפניו יש לו המדה וכשיש אצלו המדות והוא עובד בהם לאלקי' אז נותנין לו השכר היינו ההשכלה מהדבר. והנה אנו רואים שג\"ר דעשי' אין בערוך לגבי יצי', כי ממל' דיצי' נעשה כתר ועתיק לעשי'<sup data-n=\"5169\">43</sup> וכש\"כ לגבי ג\"ר דיצי' בודאי אין ערוך, וכן ג\"ר דיצי' לגבי בריאה וכן בריאה לגבי אצי', ונמצא שלכל דבר שיש להאדם כליון לזה, יש סיום וקץ, שג\"ע הו\"ע הגבלה והוא עד\"מ אב ובן שהבן הוא מוגבל הרי האב הוא ג\"כ גבול כי האב יש לו אב שהוא בנו, וזהו לכל תכלה לכל דבר שיש להאדם כלות יש לה סיום וקץ שהשיג שאפי' ג\"ע יש מד' גבוה הימנה ה\"ה ענין הגבלה, אבל רחבה מצותך מאד ופי' אדמו\"ר נ\"ע<sup data-n=\"5170\">44</sup> שמצות הם כלים רחבים למאד העליון שהוא בלי גבול.\n<b>ולהבין</b> ענין מה שמצות הם כלים רחבים למאוד העליון הענין הוא כי הנה יש ג' מיני אהבה כמ\"ש ואהבת את ד'<sup data-n=\"5171\">45</sup> בכל לבבך בכל נפשך ובכל מאודך וארז\"ל בכל לבבך בשני יצריך<sup data-n=\"5172\">46</sup> שגם היצה\"ר יבוא לידי אהבה ונת' איך יכול להיות שגם היצה\"ר יכול לבוא לידי אהבה<sup data-n=\"5173\">47</sup>, כי העיקר הוא שירצה וכשירצה בודאי יכול, ובכל נפשך בכל כוחות נפשך וכמו שלעצמו הוא טוב כמו\"כ יהי' להזולת ושיהי' רחמן וחסדן ושיעמיק חב\"ד שלו בתורה ועבודה, ובכל מאודך הוא בלי גבול, כי בכל לבבך הוא רק אהבה שתלוי' בלב כמ\"ש במד\"ר הלב אוהב<sup data-n=\"5174\">48</sup> ואפי' בכל נפשך שהוא בכל כוחות הנפש ה\"ה כמה שיש בכל כוחות הנפש ולא יותר, אבל בכל מאודך הוא בלי גבול שהוא רעו\"ד למעלה מהגבלת הכלי והוא בחי' מ\"ש מי לי בשמים<sup data-n=\"5175\">49</sup> ועמך לא חפצתי בארץ ופי' שמים וארץ הוא ג\"ע העליון וג\"ע התחתון אינו רוצה בזה כי עמך מקור חיים<sup data-n=\"5176\">50</sup> שאפי' מקו\"ח מקור התענוגים הוא עמך פי' טפל ובטל לך, והנה למי יחפוץ לדבר הבטל או למי שבטל, הלא מסתמא למי שהוא טפל ובטל, וזהו בכל מאודך למעלה מהגבלת הכלי. אך מ\"מ לא כתי' רק בכל מאודך פי' מאוד שלך<sup data-n=\"5177\">51</sup> כי יכול להיות שאצלו הוא מאוד בלי גבול ולגבי הזולת אין זה מאד וכמארז\"ל על בכל מאודך בכל ממונך<sup data-n=\"5178\">52</sup> שלפי האמת הוא מס\"נ שנותן את כל רכושו לצדקה אך לגבי העושר אין זה מס\"נ, וכן יובן בכל העולמות עד רום המעלות שבעולם הנמוך הוא מאוד ולגבי העולם שלמעלה הימנה אין זה מאוד, ומאוד הוא מאוד היותר נעלה. אך",[["5169","43","<b>ממל' דיצי' נעשה כתר ועתיק לעשי'</b>: ראה ע\"ח שער כסה\"כ שמ\"ו, פ\"ב. פ\"ה ופ\"ו."],["5170","44","<b>ופי' אדמו\"ר נ\"ע</b>: באגה\"ק סי\"ז."],["5171","45","<b>ואהבת את ד'</b>: ראה ואתחנן ו, ה."],["5172","46","<b>בכל לבבך בשני יצריך</b>: ברכות נד, א. ראה לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 18."],["5173","47","<b>ונת'. . היצה\"ר. . אהבה</b>: ראה (לעיל בחלק המאמרים) המשך יונתי כאן פי\"א."],["5174","48","<b>הלב אוהב</b>: קה\"ר פ\"א, טז."],["5175","49","<b>מי לי בשמים</b>: תהלים עג, כה. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גל נעול ובהערה 65."],["5176","50","<b>כי עמך מקור חיים</b>: תהלים לו, י. ראה לקו\"ת אמור לא, ד. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 50."],["5177","51","<b>בכל מאודך פי' מאוד שלך</b>: ראה גם תו\"א מקץ לט רע\"ד. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך ובהערה 30."],["5178","52","<b>בכל מאודך בכל ממונך</b>: ראה ברכות נד, א (במשנה). ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 102."]]],[2000480491,"זהו חסד ד' עלינו שאינו מבקש אלא לפי מאוד שלך, כמו שאי' במד\"ר כשהוא מבקש אינו מבקש אלא לפי כוחן וכשהוא נותן נותן לפי כוחו<sup data-n=\"5179\">53</sup>, כשהוא מבקש אינו מבקש אלא לפי כוחן כמ\"ש שור או כשב או עז כי יולד<sup data-n=\"5180\">54</sup> ואינו מבקש איל וצבי ויחמול<sup data-n=\"5181\">56</sup> שאינו מצוי ורגיל<sup data-n=\"5182\">55</sup>, וכשהוא נותן נותן לפי כוחו כמ\"ש הן אל ישגיב בכוחו<sup data-n=\"5183\">57</sup> מי אל כמוהו מורא<sup data-n=\"5184\">58</sup>, וזהו בכל מאודך שהוא מאוד שלך אבל ע\"י תורה ומצות יכולים להמשיך מאוד העליון שהוא בלי גבול מפני שמצות הם כלים רחבים למאוד העליון. וצ\"ל הלא מצות הם ענין הגבלה כמו שיעור סוכה ז' טפחים ומשהו, וד\"מ שבלולב, וסוכה שהוא גבוה למעלה מעשרים אמה פסולה ולולב צריך שיוצא טפח מההדס, ואתרוג שהוא גדול כביצה אבל אם פחות פסול, ובתפילין דוקא ד' בתים והאומר חמשה הרי זהו זקן ממרא<sup data-n=\"5185\">59</sup>, ואנו רואים שע\"י מצות סוכה ממשיכים מקיפים דאימא<sup data-n=\"5186\">60</sup> וענין מקיף הוא שאינו יכול לימשך בפנימי', נמצא שהמצות הם ענין הגבלה איך אפשר להיות שהם כלים לבלי גבול. ובאם שבאמת יכול להיות גבול כלי לבלי גבול א\"כ למה צריכים מה שאי' בע\"ח כשעלה ברצונו להיטיב לברואיו צמצום א\"ע ונעשה מקום פנוי<sup data-n=\"5187\">61</sup> וסילק את אורו הגדול אל הצד<sup data-n=\"5188\">62</sup> ושיהי' רשימה<sup data-n=\"5189\">63</sup> והוא מקום אחר<sup data-n=\"5190\">64</sup> שהוא כללות סדר השתל' דד' עולמות אבי\"ע, למה הי' צריכים לזה הלא בלאו הכי יכול להיות גבול כלי לבלי גבול, אך מפני שהי' כך מוכרח לומר שגבול אינו יכול להיות כלי לבלי גבול שבאמת רחוקים זה מזה, וצ\"ל איך מצות שהם ענין הגבלה הם כלים למאוד העליון שהוא בלי גבול.\n<b>אך</b> הענין הוא שתרי\"ג מצות<sup data-n=\"5191\">65</sup> הם תרי\"ג ארחין דגלגלתא<sup data-n=\"5192\">66</sup> ופי' ארחין הו\"ע דרך ושביל ששביל הוא כדי שבל ימוט ימין ושמאל אלא כדי שילך בדרך הישר. כך מצות הם שלוחי הוי' שע\"י יומשך גילוי אלקות למקום הראוי דוקא, ומצות נתלבשו בדברים גשמי' כדי לברר הניצוצים שנפלו בקליפת נוגה, כי דבר הגשמי' הוא מק\"נ שנפלו בשבה\"כ בע' שרים<sup data-n=\"5193\">67</sup> דנוגה שיש בהם ניצוצי דתוהו וע\"י הבירור מעלה אותו",[["5179","53","<b>כשהוא מבקש. . כחן. . כחו</b>: ראה במדב\"ר פכ\"א, כא. לקו\"ש ר\"ה כרך ט ע' 452 בהערה."],["5180","54","<b>שור או כשב או עז כי יולד</b>: אמור כב, כז."],["5181","56","<b>ויחמול</b>: כנשצ\"ל: ויחמור."],["5182","55","<b>ואינו מבקש איל. . שאינו מצוי ורגיל</b>: ראה ויק\"ר פכ\"ז, ו."],["5183","57","<b>הן אל ישגיב בכחו</b>: איוב לו, כב."],["5184","58","<b>מי אל כמוהו מורא</b>: שם: מי כמהו מורה."],["5185","59","<b>ובתפילין. . זקן ממרא</b>: ראה רמב\"ם הל' ממרים פ\"ג, ה\"ה. פ\"ד, ה\"ג."],["5186","60","<b>מצות סוכה. . מקיפים דאימא</b>: ראה ביאוה\"ז אמור פ, ב. לעיל ח\"א (בחלק הנחות הנחת כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואתה תצוה ובהערה 85."],["5187","61","<b>כשעלה ברצונו. . פנוי</b>: ראה ע\"ח שער הכללים בתחלתו. דרוש עגו\"י ש\"א, ענף ב."],["5188","62","<b>וסילק את אורו הגדול אל הצד</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 216."],["5189","63","<b>ושיהי' רשימה</b>: ראה שם הערה 217."],["5190","64","<b>והוא מקום אחר</b>: כ\"ה בהכת\"י."],["5191","65","<b>שתרי\"ג מצות</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטיליא מערכת שש מאות [צפת תשנ\"ב ע' 208]. לקו\"ש יתרו כרך כו ס\"ע 424 ואילך. אג\"ק שלו ח\"ג ע' רג."],["5192","66","<b>שתרי\"ג מצות. . ארחין דגלגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א. אגה\"ק ס\"כ. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"א ובהערה 219."],["5193","67","<b>בע' שרים</b>: ראה זהר בראשית מו, סע\"ב. שע\"ת עד, א הערה 2."]]],[2000480492,"ועי\"ז נמשכים אורות דתהו בכלים דתיקון שהוא מאוד דתיקון, כי כלים דתיקון הם רק לפי אורות דתיקון ולא לפי אורות דתוהו, וע\"י שמעלה האורות דתוהו יכולים להמשיך אותם בכלים דתיקון כי עולם התוהו קדמה לעולם התיקון<sup data-n=\"5194\">68</sup>, ופי' קדם אינו בזמן כי זמן ה\"ה נברא וגבול, אלא קדם במעלה, כי מה שהי' ריבוי אורות בתוהו ומיעוט אורות בתיקון אין הפי' שהאור אחד הוא רק ההפרש הוא שבתוהו הי' הרבה ובתיקון מיעוט, אלא האור דתוהו הוא באופן היותר נעלה<sup data-n=\"5195\">69</sup>, והראי' הוא מתיקון גופא כי ארז\"ל אור שברא הקב\"ה ביום הראשון אדם צופה ומביט בה מסוף העולם ועד סופו<sup data-n=\"5196\">70</sup> ופי' מסוף העולם ועד סופו מסוף עלדאת\"כ עד סוף עלדאת\"ג שהם רחוקים זה מזה שלא בערך ועכשיו נתמעט כ\"כ האור עד שאינו רואים בו אלא עד פרסא או מיל<sup data-n=\"5197\">71</sup>, נמצא שאין ערוך האור דעכשיו ממה שהי' קודם, שזהו בתיקון גופא, וכש\"כ תיקון לגבי תוהו בודאי אין ערוך, וע\"י מצות ממשיכים אורות דתוהו בכלים דתיקון שזהו מאד דתיקון.\n<b>והנה</b> יש מאוד דתוהו שהוא באופן היותר מעלה<sup data-n=\"5198\">72</sup>, כי בכלל יש עקודים נקודים וברודים<sup data-n=\"5199\">73</sup>, נקודים הו\"ע תוהו וברודים הו\"ע תיקון<sup data-n=\"5200\">74</sup>, ועקודים הוא גבוה משניהם שהוא עקוד בכלי אחד<sup data-n=\"5201\">75</sup> שהוא מאד דתוהו ועל שמות לשון הענין הוא שיש ד' שמות ע\"ב ס\"ג מ\"ה ב\"ן<sup data-n=\"5202\">76</sup>, והנה השבירה הי' בש' ס\"ג<sup data-n=\"5203\">77</sup> ונפלה בש' ב\"ן<sup data-n=\"5204\">78</sup> ומ\"ה הוא מברר ב\"ן<sup data-n=\"5205\">80</sup> ונתעלה בש' ס\"ג<sup data-n=\"5206\">79</sup>. והנה ש' ס\"ג<sup data-n=\"5207\">81</sup> ומ\"ה המה מחודשים<sup data-n=\"5208\">82</sup> שהי'",[["5194","68","<b>עולם התוהו קדמה לעולם התיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ד. וש\"נ. (לעיל בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת ובהערה 51."],["5195","69","<b>האור. . באופן היותר נעלה</b>: ראה סה\"מ תר\"ל ע' קנ. לעיל מאמר ד\"ה ביום השמיני עצרת ובהערה 57."],["5196","70","<b>אור שברא. . אדם. . סופו</b>: ראה חגיגה יב, א. ב\"ר פי\"ב, ו. פי\"א, ב. רמ\"ז ר\"פ במדבר. הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת נח כרך ו ע' 2136. סה\"מ תרכ\"ט ע' ס. וש\"נ. לעיל במאמר שם על יד הערה 59. פלח הרמון פסח ע' עח."],["5197","71","<b>רואים. . פרסא או מיל</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא' ובהערה 84."],["5198","72","<b>מעלה</b>: כנשצ\"ל: נעלה."],["5199","73","<b>עקודים נקודים וברודים</b>: ויצא לא, י. ראה גם ע\"ח שער העקודים ש\"ו, פ\"א."],["5200","74","<b>נקודים הו\"ע תוהו וברודים הו\"ע תיקון</b>: ראה לקו\"ת אמור לד, ג. בהעלותך לא, ג."],["5201","75","<b>ועקודים. . בכלי אחד</b>: ראה ע\"ח שער העקודים שם. תו\"א נח י, ג ואילך. תו\"ח וארא ח\"א נב, ד. וש\"נ. סה\"מ תרנ\"ב ע' ק ואילך. תרל\"ח ס\"ע עה ואילך ובהערה 274."],["5202","76","<b>ע\"ב ס\"ג מ\"ה ב\"ן</b>: נסמן לעיל (בהנחת כ\"ק אדמו\"ר מהורש\"ב — בחלק הנחותיו) בהנחה כאן הערות 79-82."],["5203","77","<b>השבירה הי' בשם ס\"ג</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, פ\"א. מאמרי אדה\"א דברים ח\"ב ע' שעט. וש\"נ. תו\"ח וארא ח\"א פה, ג. וש\"נ."],["5204","78","<b>ס\"ג. . בש' ב\"ן</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג."],["5205","80","<b>ומ\"ה הוא מברר ב\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["5206","79","<b>ב\"ן. . ונתעלה בש' ס\"ג</b>: ראה לקו\"ת בחוקותי מז, ג. תו\"ח וארא ח\"א ע, ג. וש\"נ."],["5207","81","<b>ס\"ג. . המה מחודשים</b>: ראה לעיל (בהנחת כ\"ק אדמו\"ר מהורש\"ב — בחלק הנחותיו) בהנחה כאן הערה 87."],["5208","82","<b>ומ\"ה. . מחודשים</b>: ראה ע\"ח שער שבה\"כ ש\"ט, פ\"ז. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1627."]]],[2000480493,"במכוון, כי מי שאומר שהוא מקרה ה\"ה מקליפת עמלק כמ\"ש אשר קרך בדרך<sup data-n=\"5209\">83</sup>, אלא שהי' במכוון, בונה עולם התוהו על מנת לסתור וסותר עולם התוהו על מנת לבנות<sup data-n=\"5210\">84</sup> עולם התיקון, וזהו רק ש' מ\"ה וס\"ג<sup data-n=\"5211\">85</sup> אבל ש' ע\"ב<sup data-n=\"5212\">86</sup> הוא הבחי' מ\"ש כל האזרח בישראל תשבו<sup data-n=\"5213\">87</sup>, שאינו מחודש אלא הו\"ע תושב ואזרח, והעלי' הוא בש' ע\"ב שהוא בלי גבול וזהו מאוד דתוהו. ובלשון החסידות הנה עולם הו\"ע העלם<sup data-n=\"5214\">88</sup>, ויש ב' מיני עולם, יש בחי' עולם כמ\"ש מל' מל' כ\"ע<sup data-n=\"5215\">89</sup> וזהו בחי' יש מאין דבר יש בפני עצמו, אבל יש בחי' עולמות הא\"ס שפי' ג\"כ עולם לשון העלם שמעלים בו הא\"ס שמאיר שם. אבל ע\"י מצות יכול להשיג א\"ס עצמותו ומהותו, ועכשיו הוא בהעלם אבל לע\"ל יהי' גילוי מאוד העליון שהוא בלי גבול כמ\"ש ולא יכנף עוד מוריך<sup data-n=\"5216\">90</sup> והי' עיניך רואות את מוריך, כי עין בעין יראו<sup data-n=\"5217\">91</sup>, כי פי הוי' דיבר<sup data-n=\"5218\">92</sup> וכמ\"ש וחשף הוי' את זרוע קדשו<sup data-n=\"5219\">93</sup>, פי' וחשף עס וועט אנפלעגט ווערין את זרוע קדשו שקאי על מצות, שכל המצות נק' בש' צדקה כמ\"ש וצדקה תהי' לנו<sup data-n=\"5220\">94</sup> כי נשמור לעשות את כל המצוה הזאת. אך באמת גם עכשיו מלובש בהמצוה הגשמי' בחי' מאוד העליון רק שהוא בהעלם, כי הנה יש שני<sup data-n=\"5221\">*95</sup> בחי', יש מצות שהם רצונות פרטיים ויש מצות ע\"ד מ\"ש נחת רוח לפני שאמרתי ונעשה רצוני<sup data-n=\"5222\">95</sup>, נעשה רצוני קאי על פרטי המצות אבל לפני הוא א\"ס בעל הרצון<sup data-n=\"5223\">*96</sup>, לכן המצות הגם שהם רצונות פרטיים ומוגבלים מ\"מ הרי מלובש בהם בחי' א\"ס בעל הרצון שהוא בלי גבול אך עכשיו הוא בהעלם כי בכדי שיקיים אותה איש הישראלי והוא מלובש בחומר גוף ונה\"ב מוכרח להיות שגם א\"ס בעל הרצון יהי' מלובש בגשם הדבר. אך לע\"ל שגם גוף יזדכך ע\"ד אדה\"ר קודם החטא אז יהי' בגילוי.\n<b>ועפי\"ז</b> יובן מה שכתי' כי נר מצוה<sup data-n=\"5224\">96</sup> ותורה אור כי מצות נק' בש' נר כי פי' נר הוא בלע\"ז ליכט, שעיקר הוא האור שפי' אור הוא ג\"כ ליכט, כי אדם",[["5209","83","<b>שהי' במכוון. . אשר קרך בדרך</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם לאחר הערה 99 ואילך ובהנסמן שם."],["5210","84","<b>בונה עולם התוהו. . לסתור. . לבנות</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשכח. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1699."],["5211","85","<b>התוהו. . התיקון. . מ\"ה וס\"ג</b>: ראה גם סה\"מ תש\"ג ע' 73. וש\"נ."],["5212","86","<b>שם ע\"ב. . כל האזרח</b>: ראה לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב (בחלק הנחותיו) בהנחה כאן הערה 93."],["5213","87","<b>כל האזרח בישראל תשבו</b>: אמור כג, מב [ושם: ישבו]."],["5214","88","<b>עולם הו\"ע העלם</b>: ראה ספר הבהיר ס\"י. תו\"ח שמות ח\"א יח, ד הערה 783."],["5215","89","<b>מל' מל' כ\"ע</b>: תהלים קמה, יג."],["5216","90","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."],["5217","91","<b>כי עין בעין יראו</b>: שם נב, ח."],["5218","92","<b>כי פי הוי' דיבר</b>: שם מ, ה."],["5219","93","<b>וחשף ה' את זרוע קדשו</b>: ישעי' נב, י [ושם: חשף<sup data-n=\"e327\">**</sup>]. ראה גם לקמן הנחה ד\"ה אני לדודי הב' על יד הערה 53. (לעיל בחלק המאמרים) המשך יונתי כאן על יד הערה 384."],["5220","94","<b>שכל המצות. . וצדקה תהי' לנו</b>: ואתחנן ו, כה. ראה גם (לעיל בחלק המאמרים) המשך יונתי הערה 27."],["5221","*95","<b>יש שני</b>: אוצ\"ל: יש במצות שני."],["5222","95","<b>נחת רוח. . רצוני</b>: ספרי שלח טו, ז. י. ראה לקו\"ש ויקרא כרך לב ע' 1. וש\"נ."],["5223","*96","<b>לפני הוא א\"ס בעל הרצון</b>: ראה גם לקמן הנחה ד\"ה כנשר יעיר קנו על יד הערה 12."],["5224","96","<b>כי נר מצוה</b>: משלי ו, כג."],["e327","**","אבל כ\"ה גם לקמן בהנחה ד\"ה אני לדודי שם."]]],[2000480494,"שמבקש נר אינו אומר שיתנו לו ח לב או שמן או פתילה אלא דוקא אור, וענין אור הוא אש, והנה אנו רואים שאש הוא מחולק משארי נבראים, כמו אש ומים אף ששניהם הם נבראים מחודשים ומוגבלים, מ\"מ אנו רואים שיש הפרש גדול ביניהם, כי מים אנו רואים באם שיש ריבוי מים ושותים משם ריבוי עם, יהי' נחסר רק שיכול לנבוע עוד אחרים אבל המים שהי' יהי' נחסר, או למשל עפר באם שיחפרו במקום זה ונזרקים במקום אחר יהי' נחסר כאן וניתוסף כאן, אבל ענין אש אנו רואים שאעפ\"י שידליקנו<sup data-n=\"5225\">97</sup> כמה אלפי אלפים נרות מנר אחד לא יהי' נחסר בהאור כלום ולא יפעול בו שום שינוי מפני שבאש יש בחי' א\"ס שהו\"ע בלי גבול לכן כתי' והוי' אלקיך אש אוכלה הוא<sup data-n=\"5226\">98</sup> שנמשל א\"ס לאש שיש בה בחי' בל\"ג. ובאמת כשתעיין היטב בענין אש אנו רואים שבהעצם האור אין לו תכלה כי מה שניכלה אינו רק השמן והפתילה אבל עצם האור אין לו תכלה, שמה שאנו רואים שנעשה כהה, זהו רק מפני הפתילה אבל עצם האור הו\"ע א\"ס, כי באם שיתנו שמן ופתילה להנר לא יכלה האור לעולם ויהי' דולק אפי' שית אלפי שני ועוד יותר אלא שאין קיום העולם יותר משית אלפי שני<sup data-n=\"5227\">99</sup> ולכן כתי' הוי' אלקיך אש אוכלה הוא שנמשל לאש דוקא. ומפני טעם זה נמשלו המצות ג\"כ לנר שהו\"ע אור, מפני שמצות הם בחי' בל\"ג. רק פעם נת' שיש הפרש בין נר לאור, אבל כאן הו\"ע אחד. וכמו\"כ נשמות ישראל נמשלו ג\"כ לנר כמ\"ש נר הוי' נשמת אדם<sup data-n=\"5228\">100</sup>, כי הנה אנו רואים מה שמביאין נר לבית חשך אין המכוון הנר אלא האור שיהי' מאיר בבית וידח החושך, כמו\"כ נתלבש הנשמה בגוף ונה\"ב שיהי' מאיר ויזדכך חומריות הגוף שהנשמה היא ג\"כ מד' א\"ס בל\"ג הגם שכתי' ימי שנותינו בהם<sup data-n=\"5229\">101</sup> שבעים שנה שהו\"ע גבול אך זהו מפני שאינם צריכים יותר שהוא מצד הגוף וכדי שיברר חלקו בעת הזה אבל עצם הנשמה הו\"ע א\"ס כי היא חלק אלקה ממעל<sup data-n=\"5230\">102</sup> כמ\"ש חלק הוי' עמו<sup data-n=\"5231\">103</sup> כמו שהוי' הו\"ע הוה הי' ויהי' כאחד<sup data-n=\"5232\">104</sup> כמו\"כ הנשמה הו\"ע א\"ס כמו קודם התלבשותה בגוף, והוא עד\"מ כשסותמים חלון שלא יהי' נכנס אור השמש הלא אין פועל שינוי בעצם השמש כמו\"כ לא פעל מה שתתלבש בגוף שהוא גבול שום שינוי בעצם הנשמה.\n<b>וזהו</b> מ\"ש לכל תכלה ראיתי קץ רחבה מצותיך מאד, לכל תכלה לכל דבר שיש כלות ואפי' לג\"ע יש סיום וקץ שהו\"ע גבול, אבל רחבה מצותיך מאד שמצות הם כלים רחבים למאד העליון. אך עכשיו אינו יכול להיות בגילוי הבלי גבול המלובש בהם והוא מפני שמוכרחים המצות להיות מלובש בדברים גשמיים מחמת",[["5225","97","<b>שידליקנו</b>: אוצ\"ל: שידליקו."],["5226","98","<b>והוי' אלקיך אש אוכלה הוא</b>: ואתחנן ד, כד [ושם: כי הוי']."],["5227","99","<b>משית אלפי שני</b>: ראה ר\"ה לא, א. מאמרי אדה\"א בראשית ע' נג. וש\"נ."],["5228","100","<b>נר הוי' נשמת אדם</b>: משלי כ, כז."],["5229","101","<b>ימי שנותינו בהם</b>: תהלים צ, י. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ספכ\"ט."],["5230","102","<b>חלק אלקה ממעל</b>: איוב לא, ב. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 395."],["5231","103","<b>חלק הוי' עמו</b>: האזינו לב, ט. ראה גם לעיל הנחה ד\"ה כמים הפנים סוף פיסקא א."],["5232","104","<b>שהוי' הו\"ע הוה הי' ויהי' כאחד</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."]]],[2000480495,"שגוף האדם הוא ג\"כ גוף חומר עב וגס ובכדי שיקיים המצות צ\"ל המצות מלובש בדברים גשמיי' דוקא אבל מ\"מ מלובש בהם גם עכשיו א\"ס בעל הרצון. וכמו שאנו רואים בנפש במה ניכר כוחות הנפש דוקא במה שמלובש בגוף, ומי מרגיש הכוחות הרי הנפש ולא הגוף, שעיקר הוא הנפש, כמו\"כ במצות עיקר הוא הא\"ס בעל הרצון המלובש בהם, וכשעושה המצוה נעשה כלי למאוד העליון שהוא בל\"ג כי בהמצוה מלובש א\"ס בעל הרצון, אך עכשיו הוא בהעלם אבל לע\"ל שיזדכך הגוף ונה\"ב אזי יהי' בגילוי. וזהו לכל תכלה ראיתי קץ, לכל דבר שיש כלות ראיתי קץ שהו\"ע גבול, אבל רחבה מצותיך מאד אין הפי' כמו שפירשו המפרשים שאין להם סיום וקץ, כי א\"כ הלל\"ל<sup data-n=\"5233\">105</sup> ולמצותך אין קץ, אלא שהם כלים רחבים למאוד העליון שהשיג, שהם כלים לא\"ס בעל הרצון, כי נחת רוח לפני שאמרתי ונעשה רצוני שפי' לפני קאי על א\"ס בעל הרצון, וזהו לכל תכלה ראיתי קץ רחבה מצותך מאד.\n<b>הנחה</b> מה שרשמתי בעת שהייתי בליבאוויץ על מה ששמעתי מאת כ\"ק אדמו\"ר שליט\"א שנת תר\"מ ביום ש\"ק פ' כי תצא חודש אלול",[["5233","105","<b>הלל\"ל</b>: כ\"ה בהכת\"י."]]],[2000480496,"<h3>אני לדודי הא'</h3>\n<b>הנחה פ' תצא שנת תר\"מ</b>\n<b>אני</b> לדודי<sup data-n=\"5234\">1</sup> ודודי לי הרועה בשושנים<sup data-n=\"5235\">2</sup>, וצ\"ל מהו הקישור וחיבור הרועה בשושנים לאני לדודי, מהו השייכות זל\"ז. אך צ\"ל תחילה הג' מיני אהבה כמ\"ש ואהבת כו' בכל מאודך<sup data-n=\"5236\">3</sup>, וצ\"ל מאחר שהוא בכל לבבך מהו ההוספה בכל נפשך, פי' בכל לבבך הוא האהבה כי אהבה היא בלב כמו שאי' במד\"ר הלב אוהב<sup data-n=\"5237\">4</sup>, וצ\"ל מאחר שהוא בכל לבבך מהו ההוספה בכל נפשך ומאחר שהוא בכל נפשך מהו ההוספה בכל מאודך. אך בכדי להבין כ\"ז צ\"ל תחילה ענין ירידת הנשמה בגוף שהיא ירידה גדולה ועצומה, ונתבאר שבשביל מה הי' הירידה בשביל העלי' שהיא ירידה צורך עלי'<sup data-n=\"5238\">6</sup>, והעלי' הוא מאיהו וגרמוהי לאיהו וחיוהי<sup data-n=\"5239\">5</sup> כי שורש הנשמות הם מגרמוהי, ואפי' הנשמות שהם מטה\"ע<sup data-n=\"5240\">7</sup> הוא ג\"כ גרמוהי אבל העלי' הוא לחיוהי ובאיהו שמתייחד עם חיוהי, והוא ע\"י שירדה הנשמה בגוף ונה\"ב ומברר אותה עי\"ז עולה",[["5234","1","<b>אני לדודי</b>: הנחה ממאמר הה' מהמשך יונתי (פי\"ג-פט\"ו) שנדפס לעיל בחלק המאמרים [ושם הפתיחה: והנה כל מה שנת\"ל בענין עליית נה\"א]. הנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לעיל (בחלק הנחותיו).\nהכותרת שמופיעה בריש המאמר: ”הנחה. . חודש אלול\" נרשמה בהכת\"י בע' שלפנ\"ז."],["5235","2","<b>אני לדודי ודודי לי הרועה בשושנים</b>: שה\"ש ו, ג."],["5236","3","<b>ואהבת. . מאודך</b>: ואתחנן ו, ה."],["5237","4","<b>שאי' במד\"ר הלב אוהב</b>: קה\"ר פ\"א, טז."],["5238","6","<b>ירידה. . צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["5239","5","<b>ונתבאר. . לאיהו וחיוהי</b>: ראה לעיל הנחה ד\"ה יפה שעה על יד הערה 69."],["5240","7","<b>הנשמות שהם מטה\"ע</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 211."]]],[2000480497,"נפה\"א ג\"כ. ובאמת אפשר לומר שבלא\"ה יכול נפה\"א לעלות מצ\"ע<sup data-n=\"5241\">8</sup>. ונוכל להבין זאת ממה שאנו רואים נהר שהולך ממקום למקום הרי ההילוך הוא בהדרגה לאט לאט, או עד\"מ אמת של מים שהולך ההילוך הוא לאט לאט שאין בו ריבוי מעיינות אלא א' ב' מעינות לכן אינו הולך במהירות כ\"כ אלא לאט לאט, ואנו רואים באם שיסתמו באמצע ההילוך או בסוף הרי ונפסק ההילוך ויקבצו ריבוי מים, שאין הריבוי מים מחודשים אלא מצד שנסתם הילוכה ע\"כ נקבצו מים הרבה עד שגובר המים ובוקעים את הסתימה ואז הולך המים במהירות וברעש ובתגבורת ובתוקף עוז, ופעם בוקע מן הצדדים וה\"ז ג\"כ מצד הסתימה. ועוד יש באופן אחר כשאינו בוקע הסתימה אלא נתמלא על כל גדותיו ושוטף על השדות.\n<b>וזהו</b> עד\"מ כמו\"כ בנמשל כי הנה\"א הוא חלק אלקה ממעל<sup data-n=\"5242\">9</sup> כי חלק הוי' עמו<sup data-n=\"5243\">10</sup> ויש בנש\"י חלק הוי' אותיו' י\"ה ו\"ה, וקוש\"י<sup data-n=\"5244\">11</sup> הוא ביטול למעלה מטו\"ד כמ\"ש כי עם קשה עורף וסלחת<sup data-n=\"5245\">12</sup> וזהו\"ע שנשמה נק' נר הוי' נשמת אדם<sup data-n=\"5246\">13</sup> שזהו נר שיש בה ש' הוי' בשלם, וזהו נשמת אדם וכמו נר העיקר הוא האור שהוא אש ואנו רואים שטבע של אש להתעלות למעלה<sup data-n=\"5247\">14</sup> שהלהב עולה ונכלל במקורו ושרשו, רק יש דבר הנאחז בו וכמו שאנו רואים באם שיתקרבו נר לאבוקה נמשך ונדבק לאור האבוקה כך הנשמה רצונה ותשוקתה ליכלל באלקות כמ\"ש ורוח האדם היא העולה למעלה<sup data-n=\"5248\">15</sup>, ואפי' הנשמה לאחר שירדה בגוף רצונה ג\"כ ליכלל למעלה רק בע\"כ אתה חי<sup data-n=\"5249\">16</sup> שהגוף הוא מעכב, כי כדי שירד<sup data-n=\"5250\">17</sup> הנשמה להתלבש בגוף יש לזה כמה הכרחים שמכריחים אותה שתרד כי באופן אחר לא יכול להיות שצריכה להיות בגוף ונה\"ב, ובזה יש כמה אופנים שיש גוף שאינו עב וגס ונה\"ב ג\"כ אינו עב וגס שיהי' מונע ומעכב, היינו שאינו נוגע לו באם שיעשה האדם מצוה כראוי, דהיינו שיתפלל וילמוד כראוי ויעשה צדקה בפועל ממש, ואין הפי' שיעשה בקרירות, כי זהו מצות אנשים מלומדה<sup data-n=\"5251\">18</sup> וע\"ז בודאי אינו מעכב, כי זהו אינו מצוה כלל, אלא שיעשה המצוה בהתלהבות וכראוי ויתפלל באהוי\"ר וע\"ז ג\"כ אינו מעכב מצד שאינו עב וגס.",[["5241","8","<b>נפה\"א לעלות מצ\"ע</b>: ראה לקו\"ת בלק עג, סע\"א. (לעיל בחלק המאמרים) בההמשך כאן הערה 304."],["5242","9","<b>חלק אלקה ממעל</b>: איוב לא, ב. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 395."],["5243","10","<b>כי חלק הוי' עמו</b>: האזינו לב, ט. ראה גם לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים סוף פיסקא א."],["5244","11","<b>בנש\"י. . י\"ה ו\"ה וקוש\"י</b>: ראה (לעיל בחלק המאמרים) המשך יונתי פ\"ה."],["5245","12","<b>כי עם קשה עורף וסלחת</b>: תשא לד, ט [בדילוג]. ראה שמו\"ר פמ\"ב, ט. לקו\"ת בלק סז, ד. עא, ב. תו\"ח תצוה ח\"ב שעט, ד. וש\"נ. סה\"מ תרכ\"ז ס\"ע עד ואילך. וש\"נ."],["5246","13","<b>נר הוי' נשמת אדם</b>: משלי כ, כז."],["5247","14","<b>שטבע של אש להתעלות למעלה</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ד, ה\"ב. תניא פי\"ט. סה\"מ תרל\"ח ע' תצא. וש\"נ."],["5248","15","<b>ורוח האדם היא העולה למעלה</b>: ראה קהלת ג, כא. לעיל הנחה ד\"ה יפה שעה אחת ובהערה 53."],["5249","16","<b>בע\"כ אתה חי</b>: ראה אבות ספ\"ד."],["5250","17","<b>שירד</b>: אוצ\"ל: שתרד."],["5251","18","<b>מצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם תניא פל\"ט (נג, ב). לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אי' כו' נביאים וכתובים הערה 12."]]],[2000480498,"<b>ואין</b> הכונה שנהפך לאיש אחר, כי אנו קוראים אותו יצה\"ר, יש לו השכל והמדות לדברים אחרים ותאות רעות, מ\"מ אינו מעכב אם יעשה אדם מצוה כראוי. אך המשל לזה אינו לפי שנת' לעיל מהמשל דסתימה אלא המשל לזה הוא שנתקבץ ריבוי מים מצד הפשרת שלגים, או ממי גשמים שנתפשט על כל גדותיו ועל שדות שסביב לה כך בנה\"א ע\"י ריבוי עסק בתו' ותפלה לכל אחד כפי ערכו ויותר לפי ערכו וילמוד בשקידה ובהתלהבות וכדינו, דהיינו בעל עסק פרק אחד שחרית<sup data-n=\"5252\">19</sup> ופרק אחד ערבית ויושבי אוהלים יקיימו והגית בו יומם ולילה<sup data-n=\"5253\">20</sup>, והנה\"ב אינו מונע ומעכב, ומ\"מ אינו נהפך לאיש אחר הוא רק יש בו הכנעה שמכניע אותו. וזהו בכל נפשך כי בכל לבבך הוא רק האהבה שהיא בלב שהלב הוא כלי לבחי' אהבה כמו שאי' במד\"ר הלב אוהב אבל כוחות החיצונים דהיינו כוח הזן או כח העיכול וכוח הדוחה או רגלים אינם שייכים לאהבה אבל בכל נפשך הם בכל כוחות הנפש אפי' בכוחות החיצונים עד\"מ האדם שהוא טרוד בטרדה גדולה אינו מרגיש כח הדוחה וכח הזן או כשהוא טרוד רץ במהירות כ\"כ שבלא הטרדה לא הי' ביכולתו לרוץ מהר כ\"כ אלא מחמת הטרדה ומי הוא הרץ הרי המוח ולא הרגלים, שכמו\"כ שילמוד ויתפלל באופן שישכח על אכילה ושתי' ועל כוח הדוחה, או שירוץ לדבר מצוה עד שאינו מרגיש א\"ע, וזהו בכל נפשך אפי' בכוחות החיצוני', כי בכל לבבך אינו רק לפי הלב שהוא אהבה אבל בכל נפשך הם בכל כוחות הנפש.\n<b>אך</b> כ\"ז גוף ונה\"ב שאינו מונע ומעכב, אבל יש גוף ונה\"ב שמונע ומעכב שהוא עב וגס עד שמטמטם הלב והמוח<sup data-n=\"5254\">21</sup> כמארז\"ל חמרא דפרגמיתא ומי' דאימסית קיפחו לעשרת השבטים איקלע ר\"א להתם בעי למקרא החודש הזה לכם<sup data-n=\"5255\">23</sup> אמר החרש הי' לבם<sup data-n=\"5256\">22</sup>, ועל טמטום פי' רש\"י שהוא עטום<sup data-n=\"5257\">24</sup> וסתום מלקבל דבר חכ', והוא עד\"מ כשסותמין הילוך המים נפסק ההילוך ואח\"כ כשבוקע הסתימה אז המים הולך ברעש ותגבורת כמו\"כ ע\"י שהנה\"ב מונע ומעכב מלעשות דבר מצוה ונפ\"א טבעו לעלות למעלה וכשבוקע נפ\"א את נה\"ב פי' למה יהי' מונע ומעכב, אז יכול לבוא לבחי' בכל מאדך. ובעבודה בכל מאודך הו\"ע אריכות ההתבוננו' מי לי בשמים<sup data-n=\"5258\">25</sup> ועמך לא חפצתי בארץ, פי' שמים וארץ הוא געה\"ע וגעה\"ת לא חפצתי לא יהי' פנימי' הרצון<sup data-n=\"5259\">26</sup>, ואפי' עוה\"ב לא יחפוץ כי אפי' עולמות עליונים ה\"ה עולם לשון העלם<sup data-n=\"5260\">27</sup>, כי עמך מקור חיים<sup data-n=\"5261\">28</sup> פי' מקור חיים הוא מקור התענוגים הוא עמך טפל",[["5252","19","<b>פרק אחד שחרית</b>: ראה מנחות צט, א. הל' ת\"ת לאדה\"ז פ\"ג, ה\"ד."],["5253","20","<b>והגית בו יומם ולילה</b>: יהושע א, ה."],["5254","21","<b>שמטמטם הלב והמוח</b>: ראה יומא לט, א. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 343."],["5255","23","<b>החודש הזה לכם</b>: בא יב, ב."],["5256","22","<b>חמרא דפרגמיתא. . לבם</b>: ראה שבת קמז, ב."],["5257","24","<b>פי' רש\"י. . עטום </b>[כנצ\"ל: אטום]: ראה יומא שם."],["5258","25","<b>מי לי בשמים</b>: תהלים עג, כה. ראה גם לעיל ח\"א (בחלק הנחת כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גל נעול ובהערה 65."],["5259","26","<b>חפצתי. . פנימי' הרצון</b>: ראה שו\"ת הצ\"צ אבהע\"ז ח\"ב סרס\"ג (ח, ג). לקו\"ת שה\"ש כח, ד. וש\"נ. תו\"ח בא ח\"א קכה, ד ובהערה 597. סה\"מ ליקוט ח\"ב ע' רעו."],["5260","27","<b>עולם לשון העלם</b>: ראה ספר הבהיר ס\"י. תו\"ח שמות ח\"א יח, ד הערה 783."],["5261","28","<b>כי עמך מקור חיים</b>: תהלים לו, י. ראה לקו\"ת אמור לא, ד. לעיל ח\"א (בחלק המאמרים) ד\"ה ואעשך לגוי גדול ובהערה 50."]]],[2000480499,"ובטל לך, ולמי יחפוץ בדבר הטפל ובטל או בעיקר, הלא בודאי העיקר, כי כללות השתל' העולמות הוא מש' והארה בעלמא ועז\"נ אני הוי' לא שניתי<sup data-n=\"5262\">29</sup> אתה קודם שנה\"ע<sup data-n=\"5263\">30</sup> ואתה הוא לאחר שנה\"ע שאין שייך בו שום שינוי בין קודם הבריאה ובין לאחר הבריאה, ולכאו' הלא הי' בריאת העולמות כמ\"ש בראשית ברא<sup data-n=\"5264\">31</sup> כו' אך זהו רק מש' והארה בעלמא שאינו נוגע בעצמיו', ולאו דוקא עד שלא נברא אלא אפי' עד שלא נאצל<sup data-n=\"5265\">32</sup> כי אי' בעבוה\"ק בפירוש אתה הוא קודם שנאצל<sup data-n=\"5266\">33</sup> ואתה הוא לאחר שנאצל, ואיך שנפרש אצי' הן שהוא הפרשת הארה מא\"ס והן שהוא גילוי העלם<sup data-n=\"5267\">34</sup> מאלקות ה\"ז רק אלקות ולא אלקה, שאלקות הו\"ע געטליכקייט ולא אלקה<sup data-n=\"5268\">35</sup>, ומה שגרמוהי הוא לברוא בריאה יש מאין הוא ע\"י שאיהו מתייחד עם גרמוהי<sup data-n=\"5269\">36</sup>, אבל עיקר הבריאה היא מאיהו, ולכן נק' אלקות ולא אלקה. והראי' הוא מש' אלקים שמתייחד עם המדה, ואם המדה הוא אלקה למה צריכה להיחוד דש' אלקים, אלא שזהו רק אלקות. וכשיתבונן בכ\"ז שכללות התהוות עולמות הוא רק מש' והארה בעלמא יבוא לבכל מאודך שהוא בל\"ג.\n<b>ומעתה</b> יש להבין למי נתייחד האהבה דבכל מאודך אם הוא ע\"י נה\"ב<sup data-n=\"5270\">37</sup> זה א\"א לומר והוא כמו שאנו רואים בהמשל דלעיל שהנהר ההולך ממקום למקום הולך לאט לאט וכשיסתמו את ההילוך בנסרים או בעפר ואח\"כ כשהוא בוקע את הסתימה והולך ברעש גדול זהו מצד המים עצמם ולא מצד הסתימה כי אדרבה הסתימה ה\"ה מונע ומעכב ההילוך לגמרי אלא מצד המים עצמם רק שהסתימה הו\"ע גרם כמו\"כ בהנמשל לכאו' מהו ההתגברות דנה\"א הוא ע\"י נה\"ב ובאמת אנו רואים שאדרבה הוא מונע ומעכב, אלא העיקר הוא ע\"י נפ\"א, והנה\"ב הוא גרם שבו וע\"י יכול לבוא הנפה\"א לבכל מאודך, נמצא שנה\"א מצ\"ע יכול ג\"כ לעלות, אך מ\"מ הגרם הוא שיבוא לזה הוא הנה\"ב, שיכול ע\"י הנה\"ב לבוא לבחי' הליכה. כמו שמצינו אצל אברהם שהי' מרכבה למדת החסד<sup data-n=\"5271\">38</sup> כמ\"ש הלוך ונסוע הנגבה<sup data-n=\"5272\">39</sup> שאי' בזהר שהו\"ע שירותא דעלמא עילאה, כי למעלה קודם שירדה הנשמה בגוף הי'",[["5262","29","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 29."],["5263","30","<b>אתה קודם שנה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["5264","31","<b>בראשית ברא</b>: בראשית א, א."],["5265","32","<b>עד שלא נברא. . נאצל</b>: ראה עבודת הקודש חלק היחוד פ\"ב."],["5266","33","<b>בעבוה\"ק. . אתה הוא קודם שנאצל</b>: וכ\"ה בהנחת כ\"ק אדמו\"ר מהורש\"ב (לעיל בחלק הנחותיו) בהנחה כאן ובהערה 34."],["5267","34","<b>אצי'. . הפרשת הארה. . גילוי העלם</b>: ראה לעיל שם ובהערות 35-36."],["5268","35","<b>אצי'. . געטליכקייט ולא אלקה</b>: ראה גם סהמ\"צ להצ\"צ ע' נב וע' קלב ואילך. המשך וככה תרל\"ז פע\"ח. הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת בראשית כרך ו ע' תתרמו. סה\"מ תרל\"ח ע' תכה. וש\"נ."],["5269","36","<b>שאיהו. . גרמוהי</b>: ראה ת\"ז בהקדמה (ג, ב). אגה\"ק ס\"כ."],["5270","37","<b>ע\"י נה\"ב</b>: אוצ\"ל: בנה\"ב."],["5271","38","<b>אברהם. . החסד</b>: ראה זהר בראשית מז, ב. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול בתחילתו. וש\"נ."],["5272","39","<b>הלוך ונסוע הנגבה</b>: לך יב, ט. ראה זהר לך פ, א. פד, א."]]],[2000480500,"בבחי' עמידה כמו במלאכים שכתי' אצלם ויעמידם לעד לעולם<sup data-n=\"5273\">40</sup>, אפי' העלי' דלעד לעולם מ\"מ ה\"ז רק עמידה כי מהו\"ע עמידה כמו אדם שהוא עומד הרי במקום א' הוא אבל כשהולך הרי במקום שהי' תחילה עכשיו אינו שם כן ענין ויעמידם לעד לעולם שאפי' העלי' דלעד לעולם מ\"מ ה\"ה בבחי' א'. וכן מ\"ש שרפים עומדים<sup data-n=\"5274\">41</sup> ממעל לו<sup data-n=\"5275\">42</sup>, ואפי' המלאכים שאומרים שירה משימ\"ב<sup data-n=\"5276\">43</sup>, ה\"ה ענין עמידה שהוא במד' א'. וכמו\"כ הנשמה כתי' חי הוי' אשר עמדתי לפניו<sup data-n=\"5277\">44</sup> שהי' בבחי' עמידה כמו במלאכים רק ההפרש הוא שמלאכים הם מחיצוני' הכלים<sup data-n=\"5278\">45</sup> ונשמות מפנימי' הכלים שההפרש הוא מצד הבריאה ומיצי' לחוד אבל מ\"מ ה\"ה בבחי' עמידה, וכדי שיהי' ונתתי לך מהלכים<sup data-n=\"5279\">46</sup> בין העומדים זהו דוקא כשירדה בגוף ונה\"ב ומונע ומעכב וכשגובר נה\"א יכול לבוא לבחי' בכל מאודך שהו\"ע הליכה.\n<b>ומוכרח</b> לומר שגם נה\"ב עולה, כי לפי שנת' שהוא גרם שיכול לבוא להבחי' דבכל מאודך וארז\"ל אין הקב\"ה מקפח שכר<sup data-n=\"5280\">47</sup> כל ברי' והוא כמשל זונה ובן המלך<sup data-n=\"5281\">48</sup> שהזונה אין ברצונה שיציית לה בן המלך ומ\"מ מוכרחת להוליד בו תאוה וחום שזהו אין ברצונה נמצא שהוא עובדא גדולה וצריך ליתן לה השכר, וכמו\"כ הנה\"ב שע\"י בא הנה\"א לבכל מאודך צריך ג\"כ להתעלות, והוא כמו במשל שנתבאר שסותמים הילוך המים בנסרים או בעפר ואח\"כ כשבוקע הסתימה אז הולך המים ברעש גדול ואנו רואים כשגובר המים את הסתימה אז נושאים גם הנסרים שקודם שגובר את הסתימה הי' סותמים ההילוך ועכשיו שגובר פועל הילוך גם בנסרים שהם בלתי הילוך, או אפי' שהסתימה הוא מעפר שאינו צף למעלה מ\"מ פועל שיהי' הילוך בעפר למטה, כמו\"כ מוכרח לומר בהנמשל שע\"י העלי' דנה\"א יתעלה הנה\"ב ג\"כ, כי הרי הגוף הוא עפר כמ\"ש אדם יסודו מעפר<sup data-n=\"5282\">49</sup> ומוכרח לומר שיש בו חיות המחי' עצם הגוף כמו שמצינו באדה\"ר שכתי' אצלו וייצר הוי' את האדם<sup data-n=\"5283\">50</sup> עפר מן האדמה קודם ויפח באפיו נשמת חיים שלא הי' בו החיות הזו ומ\"מ הי' ציור ודמות הגוף, מוכרח לומר שיש בו חיות המחי' אותו, ול\"ד גוף האדם אלא כל החיות שיש להם גוף מוכרח",[["5273","40","<b>ויעמידם לעד לעולם</b>: תהלים קמח, ו. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א. וש\"נ."],["5274","41","<b>שרפים עומדים</b>: ראה גם סה\"מ תרל\"ח ע' לז. וש\"נ."],["5275","42","<b>שרפים עומדים ממעל לו</b>: ישעי' ו, ב. ראה גם לקו\"ת אמור לב, ב. סה\"מ תרל\"ח ע' טו. וש\"נ. לעיל שם פ\"ג."],["5276","43","<b>המלאכים שאומרים שירה משימ\"ב</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 24."],["5277","44","<b>חי הוי' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["5278","45","<b>שמלאכים הם מחיצוני' הכלים</b>: ראה ע\"ח שער העיבורים שכ\"ח, פ\"א. שער פו\"ח ש\"מ, דרוש י. מאמרי אדה\"א ויקרא ח\"א ע' צט. וש\"נ. דברים ח\"ג ע' תשסח. וש\"נ. תו\"ח בשלח ח\"א רמ, ד ואילך."],["5279","46","<b>ונתתי לך מהלכים</b>: זכרי' ג, ז. ראה תו\"א וישב ל, סע\"א. ש\"א ח, ב ובהערה 42."],["5280","47","<b>אין הקב\"ה מקפח שכר</b>: ב\"ק לח, ב."],["5281","48","<b>כמשל זונה ובן המלך</b>: ראה זהר תרומה קסג, א. תניא פ\"ט ופכ\"ט ובמ\"מ הגהות והע\"ק לשם. תו\"ח מקץ רטז, ד הערה 67."],["5282","49","<b>כמ\"ש אדם יסודו מעפר</b>: נוסח כי כשמך (תפלת מוסף לימים נוראים — קודם כתר)."],["5283","50","<b>וייצר הוי' את האדם</b>: בראשית ב, ז [ושם: וייצר ה\"א]."]]],[2000480501,"לומר שיש בהם חיות כיון שהוא מציאות, והראי' שצריך להיות גוף חומר מוכן לקבל צורת הנפש שאל\"כ מהו עונש הגלגולים מאחר ששוה מוכרח לומר שבעצם הגוף יש חיות מלבד הנשמה, והגם שארז\"ל מאימתי נותנין נשמה באדם משעת יצי' שלא יסריח<sup data-n=\"5284\">51</sup>, אין הפי' שזהו חיות הגוף, אלא שהנשמה נותן חיות בהבשר ומחמם אותה שלא יסריח אבל עצם הגוף מוכרח לומר שיש לו חיות. ומה שארז\"ל תינוק בבטן אמו מלמדין אותו כל התו'<sup data-n=\"5285\">52</sup>, אך זהו כמו שאי' בלק\"ת<sup data-n=\"5286\">53</sup> שנותנין לו כחות בכדי שיוכל ללמוד כשיצא לאויר עולם, וזהו רק כוחות נעלמים, אבל כחות הגלוים הוא דוקא כשיצא, כי באם שתאמר שמלמדין את התו' בגילוי, מהו העבודה שילמוד אח\"כ, כי אפי' מה שבא מלאך וסוטרו על פיו<sup data-n=\"5287\">54</sup> עכ\"ז הי' נשאר אצלו כטבע ומהו העבודה ובאמת אנו רואים שהגוף הוא מונע ומעכב. ובלאו כל הראי' האלו מוכרח לומר שיש הפרש אם הוא מחי' דבר החי או דבר שאינו חי וכיון שהגוף הוא מציאות מוכרח<sup data-n=\"5288\">*55</sup> לומר שיש בו חיות המחיהו, נמצא שנה\"ב הוא עפר ורוח הבהמה היא היורדת למטה לארץ<sup data-n=\"5289\">55</sup>, ובאמת אי' הכל הי' מן העפר<sup data-n=\"5290\">56</sup> אפי' גלגל חמה שיש שם ג\"כ ענין עפרוריות שעי\"ז פועל ההליכה, וע\"י העלי' שנתעלה נפה\"א עי\"ז יתעלה נה\"ב ג\"כ, והעלי' מנה\"א הוא מגרמוהי לחיוהי שאפי' נשמות שהם מטה\"ע ה\"ה רק גרמוהי אבל העלי' הוא בחיוהי, ולא בחיוהי לחוד אלא באיהו שמתייחד עם חיוהי שבאה לאשתאבה בגופא דמלכא<sup data-n=\"5291\">57</sup>, וע\"י העלי' הזו דנה\"א יתעלה נה\"ב ג\"כ.\n<b>וכשם</b> שנתבאר העלי' דנה\"א ונה\"ב כך יש הפרש בין נשמה למצות כי הנה בד\"כ מצות הם מלובשים בדברים גשמי' ושרש המצות הם תרי\"ג ארחין דגלגלתא<sup data-n=\"5292\">58</sup>, פי' גלגלתא הו\"ע רצה\"ע<sup data-n=\"5293\">59</sup> שלמעלה מטו\"ד, וארחין הוא אורח ושביל וצינורות להמשיך רצה\"ע בדברים גשמי', שופר בקרן הגשמי' ותפילין בקלף הגשמי' וציצית בצמר גשמי' ותרומות ומעשרות, שהו\"ע גוף ונפש, שדבר הגשמי' הו\"ע גוף ורצה\"ע שמלובש בדבר הגשמי' הוא הנשמה, והדבר הגשמי' אין לה ערוך לגבי רצה\"ע ע\"ד עשי' לגבי רצון שרצון הוא דק ורוחני' כמו\"כ הדבר הגשמי' אין ערוך גבי רצה\"ע. והנה אנו רואים דאימתי הוא מצוה דוקא שיעשה אותה איש ישראל, כמו שופר ה\"ה גשמי' וע\"י מה הוא מצוה ע\"י שיתקע בו ישראל או תפילין וציצית שסתם",[["5284","51","<b>מאימתי נותנין נשמה באדם. . יסריח</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן הערות 317-318."],["5285","52","<b>תינוק. . כל התו'</b>: ראה נדה ל, ב. מפרשי הע\"י שם. תו\"ח בא ח\"א קכט, א. וש\"נ. בשלח קפ, ג. וש\"נ."],["5286","53","<b>שאי' בלק\"ת</b>: שלח מד, א."],["5287","54","<b>שבא מלאך וסוטרו על פיו</b>: נדה שם."],["5288","*55","<b>מציאות מוכרח</b>: אוצ\"ל: מציאות חי מוכרח."],["5289","55","<b>ורוח הבהמה. . לארץ</b>: קהלת ג, כא [ושם: היורדת היא]."],["5290","56","<b>הכל הי' מן העפר</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1811."],["5291","57","<b>לאשתאבה בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 51."],["5292","58","<b>תרי\"ג ארחין דגלגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א."],["5293","59","<b>גלגלתא הו\"ע רצה\"ע</b>: ראה לקו\"ת שלח מח, ב. ר\"ה נד, ב. תו\"ח בא ח\"א צ, א. (לעיל בחלק המאמרים) מאמר ד\"ה עטרת תפארת שיבה על יד הערה 76. ובחלק הנחות כ\"ק אדמו\"ר מהורש\"ב שם על יד הערה 60."]]],[2000480502,"תפילין הם תשמישי קדושה<sup data-n=\"5294\">60</sup> וציצית הם תשמישי מצוה<sup data-n=\"5295\">61</sup> אלא דוקא שיעשה ישראל אזי הוא מצוה, או עד\"מ אתרוג הרי הוא פרי וכשיאכל אותה בלא ברכה לא די שלא מעלה אותה אלא מורידה, או כשיאכל אותה אדם דנוגה ה\"ה נוגה ונוגה שאינו מצווה אין זה כלום<sup data-n=\"5296\">62</sup> אבל כשישראל מברך עליו מעלה אותה, וזהו מ\"ש צו את בנ\"י<sup data-n=\"5297\">63</sup> פי' שיהי' החיבור בנ\"י להמצוה, וכן איש ישראל בלא דבר הגשמי' ג\"כ א\"א להיות, נמצא שכל המצות הם מלובשים בדברים גשמי' וע\"י שיעשה מצוה נתעלה בא\"ס בעל הרצון, והעלי' דנשמה הוא בש' ע\"ב<sup data-n=\"5298\">65</sup> שהוא בחי' והחכ' תחי'<sup data-n=\"5299\">66</sup> וע\"י שמ\"ה מברר ב\"ן<sup data-n=\"5300\">67</sup> המצוה נתעלה בש'<sup data-n=\"5301\">68</sup> ס\"ג<sup data-n=\"5302\">64</sup>. ולכאו' צ\"ל מאחר שהעלי' הוא בש' ס\"ג הלא השבירה הי' ג\"כ בש' ס\"ג<sup data-n=\"5303\">69</sup> ומכיון השבירה הי' ירידה צורך עלי' שהם מחודשים<sup data-n=\"5304\">70</sup> ומי שאומר שהוא מקרה ה\"ה קליפת עמלק כמ\"ש אשר קרך<sup data-n=\"5305\">71</sup> אלא שהי' המכוון ירידה צורך עלי' ומאחר שהשבירה הי' בש' ס\"ג והעלי' הוא בש' ס\"ג א\"כ אין זה עלי'. אך הענין הוא שעלי' הוא בג\"ר דש' ס\"ג ולכאו' הלא נתבאר שג\"ר הו\"ע ג\"ע<sup data-n=\"5306\">72</sup> לפי ערך העולם ה\"ה אינו עלי'. ואפשר לתרץ זה בב' תירוצי', הא' שש' ס\"ג וש' ע\"ב הם ע\"ד חכ' ובינה שחכ' ובינה הם תרדל\"מ<sup data-n=\"5307\">73</sup> כך ע\"ב וס\"ג הם תרדל\"מ, והב' כי מתי הג\"ר הו\"ע ג\"ע הוא המוחין שלפי המדות אבל בעצם המוחין לא הי' השבירה<sup data-n=\"5308\">74</sup> ולשם הוא העלי'. ובאמת אינם צריכים להראיות האלו כי אימתי המוחין לפי המדות הוא בתיקון דוקא אבל כיון בש' ס\"ג הוא תוהו<sup data-n=\"5309\">75</sup> ובתוהו לא יש",[["5294","60","<b>שסתם תפילין הם תשמישי קדושה</b>: כ\"ה בכ\"מ — ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 55. ראה שו\"ע אדה\"ז הל' תפילין סמ\"ב, ס\"ו."],["5295","61","<b>וציצית הם תשמישי מצוה</b>: ראה שו\"ע אדה\"ז הל' ציצית רסכ\"א. הל' תפילין שם."],["5296","62","<b>אתרוג. . אדם דנוגה. . כלום</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי ובהערה 178."],["5297","63","<b>צו את בנ\"י</b>: ויקרא כד, ב. ועוד. ראה גם סידור שחרית לו, ד. לקו\"ת פינחס עו, א."],["5298","65","<b>בש' ע\"ב. . והחכ'</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' שנג."],["5299","66","<b>והחכ' תחי'</b>: קהלת ז, יב [ושם: החכמה — ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 292]."],["5300","67","<b>שמ\"ה מברר ב\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["5301","68","<b>נתעלה בש' ס\"ג</b>: ראה לקו\"ת בחוקותי מז, ג. תו\"ח וארא ח\"א ע, ג. וש\"נ."],["5302","64","<b>בש' ע\"ב. . שמ\"ה. . ב\"ן. . ס\"ג</b>: ראה (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה לכל תכלה ראיתי קץ ובהערות 79-82."],["5303","69","<b>השבירה. . בש' ס\"ג</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, פ\"א. מאמרי אדה\"א דברים ח\"ב ע' שעט. וש\"נ. תו\"ח וארא ח\"א פה, ג. וש\"נ."],["5304","70","<b>שהם מחודשים</b>: ראה לקמן ובהערה 86."],["5305","71","<b>שהוא מקרה. . אשר קרך</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם לאחר הערה 99 ואילך ובהנסמן שם. ענין זה מובא גם בסיום המאמר כאן."],["5306","72","<b>נתבאר שג\"ר הו\"ע ג\"ע</b>: ראה לעיל הנחה ד\"ה לכל תכלה ובהערה 42."],["5307","73","<b>שחכ' ובינה הם תרדל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. תו\"ח בראשית כא, ב ובהערה 8."],["5308","74","<b>בעצם המוחין לא הי' שבירה</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. מאמרי אדה\"א דברים ח\"א ע' ט. וש\"נ."],["5309","75","<b>בש' ס\"ג הוא תוהו</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, פ\"א. תו\"ח בראשית ט, א ובהערה 2."]]],[2000480503,"ענין התכללות כי אפי' במדות אינו התכללות חסד וגבורה אלא הם נקודות זת\"ז<sup data-n=\"5310\">76</sup> לכן עליה הוא בש' ס\"ג.\n<b>וזהו</b> מ\"ש אני לדודי ודודי לי הרועה בשושנים פי' שושנה הוא כמארז\"ל ששונים ששונים בהלכות<sup data-n=\"5311\">77</sup> ולכן נק' שושנה כמו בשושנה יש תליסר עלין<sup data-n=\"5312\">78</sup> דסחרין לשושנה כך יש י\"ג מדות שהתו' נדרשת בהן<sup data-n=\"5313\">79</sup> שהוא פי' וביאור על תושב\"כ כמו מ\"ש יום תרועה הוא לכם<sup data-n=\"5314\">80</sup> ואי' במשנה כמה שיעור תקיעה<sup data-n=\"5315\">81</sup> ג' תרועות ושיעור תרועה כו', או סוכה שכתי' בסוכת תשבו ז\"י<sup data-n=\"5316\">82</sup> ותושבע\"פ מבאר איך ומה שיהי', או מ\"ש ולקחתם לכם<sup data-n=\"5317\">83</sup> פרי עץ הדר ומשנה מבאר וכן גמרא אמר פלוני אמר פלוני, וזהו הי\"ג מדות כלל ופרט וכהנה, וע\"י שושנה שהו\"ע הלכות יכולים לבוא לאני לדודי שסופה תיבות הם ד\"י שהו\"ע ש' ע\"ב<sup data-n=\"5318\">84</sup>, כי מה הוא במילוי אלפין וש' ב\"ן באופן אחר וש' ס\"ג יוד א'<sup data-n=\"5319\">85</sup> אבל ש' ע\"ב הוא במלוי ד\"י, וס\"ג ומ\"ה הם מחודשים<sup data-n=\"5320\">86</sup> וא\"א לומר שהוא מקרה שהוא קליפת עמלק כמ\"ש אשר קרך כי בונה עולם התהו<sup data-n=\"5321\">87</sup> על מנת לסתור וסותר עולם התהו על מנת לבנות עולם התיקון, אבל ש' ע\"ב הוא מד'<sup data-n=\"5322\">88</sup> ע\"ש כל האזרח בישראל<sup data-n=\"5323\">89</sup> ישבו בסוכות, אך עכשיו הוא בהעלם כמו ע\"י סוכה ממשיך מקיפים<sup data-n=\"5324\">90</sup> אבל לע\"ל יהי' בגילוי שזהו אינו מחודש שהוא מ\"ש משכיל לאיתן האזרחי<sup data-n=\"5325\">91</sup> שהוא מאז ומקדם. וזהו אני לדודי ודודי לי שע\"י הרועה בשושנים מתעלה לאני לדודי ודודי לי והוא ע\"י שירדה הנשמה בגוף ונה\"ב ומקיים תומ\"צ יתעלה בש' ע\"ב שהוא במילוי ד' יודין.",[["5310","76","<b>ובתוהו. . זת\"ז</b>: ראה ע\"ח שער הכללים פ\"א. שער התיקון ש\"י, פ\"ה. מאמרי אדה\"א קונטרסים ע' תז. וש\"נ. וראה גם סה\"מ תרל\"ח ע' רסא. וש\"נ."],["5311","77","<b>ששונים ששונים בהלכות</b>: אוצ\"ל: [אל תקרי] שושנים [אלא] ששונים בהלכות — ראה זח\"ב תוספות עדר, א. מאמרי אדה\"א דברים ח\"ד ע' א'קפח. וש\"נ. סה\"מ תרל\"ח ע' רפה. וש\"נ. לקמן הנחה ד\"ה אני לדודי הב' בסופה."],["5312","78","<b>בשושנה יש תליסר עלין</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן הערה 338."],["5313","79","<b>י\"ג מדות שהתו' נדרשת בהן</b>: תו\"כ ר\"פ ויקרא."],["5314","80","<b>יום תרועה הוא לכם</b>: פינחס כט, א [ושם: יהי']. הובא בגמ' דהערה הבאה."],["5315","81","<b>כמה שיעור תקיעה</b>: ר\"ה לג, ב."],["5316","82","<b>בסוכות תשבו ז\"י</b>: אמור כג, מב."],["5317","83","<b>ולקחתם לכם</b>: אמור שם, מ."],["5318","84","<b>אני לדודי. . ד\"י </b>[ ד' יודי\"ן]<b>. . ע\"ב</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן הערות 341-340."],["5319","85","<b>מה. . ב\"ן. . ס\"ג יוד א'</b>: ראה בהנחת כ\"ק אדמו\"ר מהורש\"ב (לעיל בחלק הנחותיו) בהנחה כאן הערות 85-87."],["5320","86","<b>ס\"ג ומ\"ה הם מחודשים</b>: ראה לעיל הנחה ד\"ה לכל תכלה הערות 82-81."],["5321","87","<b>בונה עולם התהו</b>: ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם הערה 102."],["5322","88","<b>מד'</b>: כ\"ה בהכת\"י."],["5323","89","<b>כל האזרח בישראל</b>: אמור כג, מב."],["5324","90","<b>סוכה ממשיך מקיפים</b>: ראה ביאוה\"ז אמור פ, ב. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואתה תצוה ובהערה 85."],["5325","91","<b>משכיל לאיתן האזרחי</b>: תהלים פט, א."]]],[2000480504,"<h3>אני לדודי הב'</h3>\n<b>בס\"ד שנת תר\"מ</b>\n<b>אני</b> לדודי<sup data-n=\"5326\">1</sup> ודודי לי הרועה בשושנים<sup data-n=\"5327\">2</sup>, הנה אני לדודי ודודי לי הוא ר\"ת אלול וס\"ת המה ד\"י<sup data-n=\"5328\">3</sup> שהם רומזים על הארבעים יום שהי' משה בהר שהם מר\"ח אלול עד אחר יוהכ\"פ שע\"ז כתי' ואנכי עמדתי בהר ארבעים יום כימים הראשונים וארז\"ל מה הראשוני' ברצון<sup data-n=\"5329\">4</sup> כך אחרונים ברצון נמצא שימי אלול הם ימי רצון, ולפ\"ז יתיישב כפשוטו, וע\"כ כתי' אח\"כ הרועה בשושנים שהוא בחי' יגמדה\"ר כמ\"ש בזהר מה שושנה זו אית לה תליסר עלין<sup data-n=\"5330\">5</sup> דסחרין לה אוף הכי כנס\"י אית להון תליסר מכילין דרחמים דסחרין להון<sup data-n=\"5331\">6</sup>, נמצא מובן מכאן הכתוב כפשוטו מאחר שהם ימי רצון לכן מאיר אז יגמדה\"ר. אך צ\"ל מה שבפסוק דודי לי ואני לו<sup data-n=\"5332\">7</sup> כתי' ג\"כ הרועה בשושנים שע\"פ הזה פי' כל המפרשים<sup data-n=\"5333\">8</sup> שקאי על יצ\"מ ומ\"ת שאז הי' גילוים מלמעלמ\"ט לכאו' מה שייך שם יגמדה\"ר. אך הנה מצינו עוד פסוק שכתי' אני לדודי ועלי תשוקתו<sup data-n=\"5334\">9</sup> שלכאו' אינו מובן שלשון הפסוק נושא עליו שתשוקת הקב\"ה לישראל הוא יותר מתשוקת ישראל להקב\"ה שבתשוקת ישראל נא' אני לדודי ובתשוקת הקב\"ה לישראל כתי' לשון תשוקה שפי' תשוקה הוא חמדה שבלב, ולכאו' אפי' אם אנו אומרים ששוה כמו אני לדודי ודודי לי ג\"כ אינו מובן ובפרט תשוקה שהו\"ע חמדה גדולה שבלב זהו בודאי אינו מובן. וכענין זה הקשו כל המפרשים על ענין עבודה כמ\"ש ועבדת את<sup data-n=\"5335\">10</sup> כו' ולעבדו בכל לבבכם<sup data-n=\"5336\">11</sup> כו', לכאורה מה שייך ענין עבודה למעלה הלא עבודה אינו שייך אלא באדון ועבד שמה שחסר אצל האדון העבד ע\"י עבודתו משלים אותו אבל למעלה שאנת הוא שלימותא<sup data-n=\"5337\">12</sup> וכלום חסר מה צריך לעבודה. אך הנה באמת אי' נתאוה הקב\"ה להיות לו ית'<sup data-n=\"5338\">14</sup> דירה בתחתונים<sup data-n=\"5339\">13</sup>, והגם שאינו ידוע לנו מפני מה נתאוה<sup data-n=\"5340\">15</sup>, ואין הפי' שאין לזה טעם כי באמת יש טעם אך לנו אינו מושג, אבל עכ\"פ זאת ידוע לנו שנתאוה, וכן אי' במד\"ר שוקיו עמודי",[["5326","1","<b>אני לדודי</b>: הנחה ממאמר הו' מהמשך יונתי (פט\"ז-פי\"ח) שנדפס לעיל בחלק המאמרים [ושם הפתיחה: והנה אני לדודי ודודי לי].\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לעיל (בחלק הנחותיו)."],["5327","2","<b>אני לדודי ודודי לי הרועה בשושנים</b>: שה\"ש ו, ג."],["5328","3","<b>אני לדודי. . ר\"ת אלול וס\"ת המה ד\"י</b>: ראה לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן. וש\"נ."],["5329","4","<b>ואנכי עמדתי בהר. . מה הראשונים ברצון</b>: עקב י, י (בשינוי הסדר). ראה רש\"י עקב ט, יח. י, י. לקו\"ש בין המצרים כרך יג ע' 266 בהערה."],["5330","5","<b>מה שושנה. . תליסר עלין</b>: ראה (לעיל בחלק המאמרים) המשך יונתי כאן הערה 338."],["5331","6","<b>מה שושנה. . דסחרין להון</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן הערה 345."],["5332","7","<b>דודי לי ואני לו</b>: שה\"ש ב, טז."],["5333","8","<b>המפרשים</b>: ראה רש\"י שם."],["5334","9","<b>אני לדודי ועלי תשוקתו</b>: שה\"ש ז, יא."],["5335","10","<b>ועבדת את</b>: וכ\"ה לקמן בפנים בין הערות 61-62. כנשצ\"ל: ועבדתם את — משפטים כג, כה. ראה הערה 348 (לעיל בחלק המאמרים) בההמשך כאן."],["5336","11","<b>ולעבדו בכל לבבכם</b>: עקב יא, יג."],["5337","12","<b>שאנת הוא שלימותא</b>: ת\"ז בהקדמה יז, ב."],["5338","14","<b>ית'</b>: ראה גם (לעיל בחלק המאמרים) בההמשך כאן ובהערה 351."],["5339","13","<b>נתאוה הקב\"ה. . דירה בתחתונים</b>: ראה תניא רפל\"ו. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1693."],["5340","15","<b>מפני מה נתאוה</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1776."]]],[2000480505,"שש זה העולם שנשתוקק הקב\"ה לבראותו<sup data-n=\"5341\">16</sup>, עמודי שש בששה ימים, שגם שם הגם שאינו ידוע לנו מפני מה נשתוקק אבל זאת ידוע לנו עכ\"פ שנשתוקק.\n<b>ובכדי</b> לקרב אל השכל קצת, הענין הוא דהנה אי' בתד\"א שני דברים קדמו לעולם<sup data-n=\"5342\">17</sup> תורה וישראל ועדיין אינו ידוע איזה מהן קדם אומר אני ישראל קדם, והביא אדמו\"ר נ\"ע ראי' ע\"ז<sup data-n=\"5343\">18</sup> ממה שכתי' בתורה דבר אל בנ\"י<sup data-n=\"5344\">19</sup> צו את בנ\"י<sup data-n=\"5345\">20</sup> משמע שישראל קדם, וזה כתי' אפי' בתורה הקדומה דמשמע שאפי' בתוה\"ק ג\"כ קדמו, ופי' קדם אינו בזמן אלא במעלה<sup data-n=\"5346\">21</sup> שהוא שכל המכוון בבריאת העולמות ותורה ומצוות הי' בשביל האדם, אך מה שניתנו תומ\"צ הוא מחמת שהמכוון הי' שהאדם יהי' עובד כדי שיהי' מקושר לאלקות ע\"כ ניתנו התומ\"צ שמזה יהי' הוכחה להתקשרותו כמו עד\"מ בשני ב\"א אימתי מוכח שהם מקושרים כשאחד מצוה והב' מקיים אז מוכח שהם מקושרים וזהו מ\"ש אתה בחרתנו<sup data-n=\"5347\">22</sup> מכל העמים כו' וקדשתנו במצותיך שהבחירה הי' בנו דוקא אך וקדשתנו במצותיך, או כמ\"ש בך בחר הוי' להיות לו לעם סגולה<sup data-n=\"5348\">23</sup>. ונמצא שאין הפי' שיש רצונות למעלה וכדי „ז עס ז ל אויס גיפירט ווערין הרצונות לכן נברא האדם, זה אינו, כי באמת מאי איכפת לי' אם שוחט מן העורף און מן הצואר כי כל המצות נק' בש' צדקה כמ\"ש כל מצותיך צדק<sup data-n=\"5349\">24</sup>, אלא עיקר המכוון הי' בשביל האדם והתומ\"צ לא ניתנו כ\"א שע\"י המצות יהי' עובד להשי\"ת, והגם שכתי' אנכי עשיתי ארץ<sup data-n=\"5350\">25</sup> ואדם עלי' בראתי ונת'<sup data-n=\"5351\">26</sup> שמה שעשיתי ארץ ואדם עלי' הוא בשביל בראתי, שבראתי בגימט' תרי\"ג<sup data-n=\"5352\">27</sup> שעיקר הבריאה הוא בשביל תומ\"צ הי'. אך באמת אין מקרא יוצא מידי פשוטו<sup data-n=\"5353\">28</sup> שפי' בראתי הוא ב„ש„פין.\n<b>ולהבין</b> שרש ענין התומ\"צ הענין הוא כי הנה אי' בע\"ח כשעלה ברצונו הפשוט<sup data-n=\"5354\">29</sup> להיטיב לברואיו צמצם א\"ע, ופעם כתי' סילק את אורו הגדול אל הצד<sup data-n=\"5355\">30</sup>",[["5341","16","<b>שוקיו עמודי שש. . לבראותו</b>: שה\"ש ה, טו. במד\"ר רפ\"י."],["5342","17","<b>בתד\"א שני דברים קדמו לעולם</b>: רבא קרוב לספי\"ד בשינויים. ראה גם (לעיל בחלק המאמרים) המשך יונתי כאן ובהערה 355."],["5343","18","<b>והביא אדמו\"ר נ\"ע ראי' ע\"ז</b>: ראה גם (לעיל בחלק המאמרים) שם בשוה\"ג 5."],["5344","19","<b>דבר אל בנ\"י</b>: בשלח יד, ב. טו. תרומה כה, ב. תשא לא, יג. ויקרא א, ב. ועוד."],["5345","20","<b>צו את בנ\"י</b>: ויקרא כד, ב. ועוד."],["5346","21","<b>קדם. . אלא במעלה</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 899."],["5347","22","<b>אתה בחרתנו</b>: בתפלת העמידה ליו\"ט."],["5348","23","<b>בך בחר הוי' להיות לו לעם סגולה</b>: ואתחנן ז, ו [ושם: ה\"א]."],["5349","24","<b>מאי איכפת לי'. . כל מצותיך צדק</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם ובהערות 38-39."],["5350","25","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב."],["5351","26","<b>ונת'</b>: לעיל הנחה ד\"ה יפה שעה אחת פיסקא והענין הוא."],["5352","27","<b>שבראת\"י בגימט' תרי\"ג</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1688 מהרמ\"ז והה\"מ."],["5353","28","<b>אין מקרא יוצא מדי פשוטו</b>: שבת סג, א."],["5354","29","<b>בע\"ח כשעלה ברצונו הפשוט</b>: ראה שם דרוש עגוי\"ש ש\"א, ענף ב."],["5355","30","<b>סילק את אורו הגדול אל הצד</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 216."]]],[2000480506,"ונשאר חלל ומק\"פ, ופי' מקו\"פ אינו פנוי לגמרי כי דבר שבקדושה אינו נעקר ממקומה לגמרי<sup data-n=\"5356\">32</sup> ואדרבא שם הוא מעמד ומצב לכללות השתל' אבי\"ע, אלא שנשאר רשימה<sup data-n=\"5357\">31</sup>. והגם שנא' שברשימה לא נגע בה הצמצום<sup data-n=\"5358\">33</sup> שרשימה הוא קודם הצמצום אך מ\"מ ה\"ה העלם ובכדי שיהי' פרטי גילוים בעולמות נמשך קו וחוט והקו\"ח מסתיים באצי'<sup data-n=\"5359\">34</sup> ומאצי' לבי\"ע יש פרסא<sup data-n=\"5360\">35</sup> המפסקת וזהו\"ע תומ\"צ שע\"י תומ\"צ ממשיכים תוס' אורות באצי'<sup data-n=\"5361\">36</sup> ועי\"ז הקו בוקע הפרסא<sup data-n=\"5362\">37</sup> ונמשך הארת הקו\"ח עד עולם העשי'.\n<b>ולכאורה</b> אינו מובן מהו\"ע תוס' אורות באצי' הלא אצי' הוא אלקות<sup data-n=\"5363\">38</sup> לא כמו ברי' שהוא בריאה יש מאין אלא הוא אלקות ממש, ועל ע\"ס דאצי' אי' בעה\"ק שהוא אינון ואינון הוא<sup data-n=\"5364\">39</sup> שהוא מתייחד עם הע\"ס ומה שייך שם תוס' אורות. אך הענין הוא שמה שאצי' הוא<sup data-n=\"5365\">40</sup> אלקות הוא רק לגבי בריאה שאפי' לגבי ע\"ס דברי' נק' אצי' אלקות, כי הע\"ס דברי' הוא לאחר הפרסא, אך מ\"מ מה שאצי' הוא אלקות רק אלקות שהו\"ע געטליכקייט<sup data-n=\"5366\">41</sup> אבל מה שאנו קורין בש' גא\"ט<sup data-n=\"5367\">42</sup> הוא בורא יחיד ומיוחד אבל ע\"ס דאצי' הוא עשר ולא תשע<sup data-n=\"5368\">43</sup> כו' ולכן אי' בתני' שאיהו מתייחד עם גרמוהי<sup data-n=\"5369\">44</sup> לברוא בו וע\"י בריאה יש מאין מוכרח לומר שמגרמוהי לחוד לא הי' יכול להיות התהוות העולמות דאל\"כ למה הי' היחוד דאיהו, אלא העיקר התהוות הוא מאיהו ומה שמתייחד עם גרמוהי הוא בכדי שיהי' מציאות היש מוגבל שזהו לכאו' היפך המכוון, אף שבסוף נשלם הכוונה שנעשה ביטול היש לאין מ\"מ בעת מציאות ישותו הוא היפך המכוון נמצא שמגרמוהי לא יכול להיות התהוות אלא דוקא מאיהו רק גרמוהי פעלו ההגבלה והגבלה לגבי המהווה הוא באין ערוך כי ההתהוות הוא",[["5356","32","<b>דבר שבקדושה. . לגמרי</b>: ראה אלשיך ר\"פ לך[ednref_328_א]. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אז ישיר ובהערה 45."],["5357","31","<b>ונשאר חלל ומק\"פ. . רשימה</b>: ראה שם הערה 217."],["5358","33","<b>שברשימה לא נגע בה הצמצום</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"ו."],["5359","34","<b>והקו\"ח מסתיים באצי'</b>: ראה ע\"ח שער סדר אצי' ש\"ג בתחלתו. תו\"ח ויצא קעו, ג הערה 45."],["5360","35","<b>ומאצי' לבי\"ע יש פרסא</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא."],["5361","36","<b>תומ\"צ. . אורות באצי'</b>: ראה פע\"ח בהקדמה. ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש יא כלל טז. מאמרי אדה\"א דברים ח\"ד ע' א'תסז. וש\"נ. תו\"ח בשלח ח\"א קנו, ב הערה 312."],["5362","37","<b>הקו בוקע הפרסא</b>: ראה אגה\"ק ס\"כ (תניא קלא, ב). (לעיל בחלק המאמרים) המשך יונתי כאן הערה 372."],["5363","38","<b>אצי' הוא אלקות</b>: ראה עבודת הקדש חלק היחוד פ\"ב. רפ\"ד. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1599."],["5364","39","<b>בעה\"ק שהוא אינון ואינון הוא</b>: ראה שם חלק היחוד פ\"ד. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ו הערה נ."],["5365","40","<b>הוא</b>: תיבה זו הוכפלה בהכת\"י."],["5366","41","<b>אצי'. . געטליכקייט</b>: ראה לעיל הנחה ד\"ה אני לדודי ובהערה 35."],["5367","42","<b>גא\"ט</b>: ראה גם בענין כתיבת תיבה זו בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן ובהערה 50 (נדפס לעיל בחלק הנחותיו)."],["5368","43","<b>עשר ולא תשע</b>: ס\"י פ\"א, מ\"ג (מהדורת מנטובא שכ\"ב)."],["5369","44","<b>בתניא שאיהו מתייחד עם גרמוהי</b>: אגה\"ק ס\"כ (קל, ב). ראה סה\"מ תרל\"ח ע' ד.\n\n[edn_328_א] הובא באוה\"ת לך כרך ד ע' תרעה וע' תרפא. ושם מציין לפרדס שער המציאות פ\"א."]]],[2000480507,"דבר מלא דבר<sup data-n=\"5370\">45</sup>, הרי שאצי' אינו רק אלקות ולא אלקה ולזה הי' הצמצום שע\"י הצמצום נתהוה אצי' אלקות שהו\"ע געטליכקייט, אבל ע\"י תומ\"צ ממשיכים מאורות שלפני אצי' באצי' וה\"ז תוס' אורות שתוס' של הקב\"ה מרובה על העיקר<sup data-n=\"5371\">46</sup>. ואף שלמעלה מאצי' יש בחי' רצון שהוא אותיו' צינור<sup data-n=\"5372\">47</sup> שהוא כמו צמצום מ\"מ ה\"ה למעלה מאצי', והגם שבע\"ס דאצי' מאיר הקו בדרך התלבשות אבל מ\"מ ה\"ה רק בדרך קו וכמו שהוא באצי' אבל ע\"י תומ\"צ ממשיכים אורות בלתי מצומצמים באצי' כי בכלל ההפרש הוא בין אצי' ללפני אצי' שלפני אצי' מאירים אורות בלתי מצומצמים ובאצי' מאיר אורות מצומצמים.\n<b>אך</b> צ\"ל איך הוא בכח המצות שהם מוגבלים שע\"י יומשך אורות בלתי מצומצמים. אך הענין הוא דהנה לא לבד שמצות שרשם הוא בבעל הרצון כמ\"ש נחת רוח לפני שאמרתי ונעשה רצוני<sup data-n=\"5373\">48</sup>, שלפני קאי על א\"ס בעל הרצון, שלא לבד זה הם כלים לבעל הרצון, דהנה מצות נתלבשו בדברים גשמי' כמו ציצית בצמר גשמי' תפילין בקלף גשמי' סוכה בסכך גשמי' ואתרוג בצומח גשמי' הנה האתרוג בעת שהוא צומח אם יאכל אותו אחד מישראל בלא ברכה הוא מוריד אותו שנשאר תחת ממשלת ק\"נ, ואם יאכל אותו אדם שאינו מצווה לברך אינו מעלה אותו רק לצומח<sup data-n=\"5374\">50</sup> למדבר<sup data-n=\"5375\">49</sup> שזהו עלי' מועטת, ועיקר העלי' הוא כשישראל מברך עלי' אז מעלה אותו העליה גמורה, אך אינו בערך שאם יעשה אותה בעצם למצוה ה\"ה נעשה כלי לבעל הרצון כי המצוה הוא רצון פרטי ובזה נכלל רצון הכללי וגם עצמות א\"ס בעלה\"ר פי' מי שנושא עליו הכלל, שפי' בעל הוא מלשון מרא וריבון כמו שאנו רואים באדם שיש לו רצונות פרטיות ורצון הכלל<sup data-n=\"5376\">51</sup> והאדם הנושא הרצונות, רק שעכשיו הוא בהעלם, ובאמת כמו שבעולם אלמלא ניתנה רשות לעין לראות<sup data-n=\"5377\">52</sup> כח המהוה הי' רואה שהמתהוה הוא בטל כאין ואפס כמו\"כ במצות אלמלא ניתנה רשות לעין לראות הרוחניות מהדבר מצוה הי' רואים שמלובש בה א\"ס בעל הרצון אך הגשם הוא מעלים ומסתיר ע\"ז, אבל לע\"ל כתי' וחשף הוי' זרועו קדשו<sup data-n=\"5378\">53</sup> פי' וחשף „נטפלעגט ווערין הדבר שהי' תחילה בהעלם, ופי' זרוע קדשו כי כל המצות נק' בש' צדקה כמ\"ש וצדקה תהי' לנו<sup data-n=\"5379\">54</sup> כי נשמור לעשות את המצוה הזאת,",[["5370","45","<b>דבר מלא דבר</b>: אולי צ\"ל: דבר לא מדבר — ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 479."],["5371","46","<b>שתוס' של הקב\"ה. . העיקר</b>: ראה ב\"ר פס\"א, ד. לקו\"ש וישלח כרך ה ע' 422 הערה 3. ע' 423 הערה 10. סה\"מ תרל\"ח ע' מט. וש\"נ."],["5372","47","<b>רצון שהוא אותיו' צנור</b>: ראה זהר הרקיע לזהר בראשית נא, א (כה, ב בדפי הספר). מאמרי אדה\"א בראשית ע' לו. וש\"נ."],["5373","48","<b>נחת רוח. . ונעשה רצוני</b>: ספרי שלח טו, ז. י. ראה לקו\"ש ויקרא כרך לב ע' 1. וש\"נ."],["5374","50","<b>לצומח</b>: אוצ\"ל: מצומח."],["5375","49","<b>יאכל. . שאינו מצווה לברך. . למדבר</b>: ראה (לעיל הנחת כ\"ק אדמו\"ר מהורש\"ב — בחלק הנחותיו) הנחה ד\"ה יונתי ובהערה 178."],["5376","51","<b>הכלל</b>: אוצ\"ל: הכללי."],["5377","52","<b>אלמלא ניתנה רשות לעין לראות</b>: ברכות ו, א."],["5378","53","<b>וחשף הוי' זרועו קדשו</b>: נסמן לעיל הנחה ד\"ה לכל תכלה ראיתי קץ הערה 93."],["5379","54","<b>כל המצות. . וצדקה תהי' לנו</b>: ואתחנן ו, כה. ראה גם (לעיל בחלק המאמרים) המשך יונתי הערה 27."]]],[2000480508,"כי עכשיו אחד שנותן צדקה הרי היד הוא גשמי' והעמל הוא גשמי' והמעות הם גשמי', וע\"כ מעלים ומסתיר שלא יראה בה השראת בעל הרצון אבל לע\"ל יהי' וחשף שמתגלה, וכן בתו' כתי' ונגלה כבוד הוי' וראו<sup data-n=\"5380\">55</sup> כל בשר כי פי הוי' דיבר היינו כשישראל ילמד תורה יראה פה הוי' המדבר כנגדו כמארז\"ל כל העוסק בתורה הקב\"ה קורא ושונה כנגדו<sup data-n=\"5381\">56</sup>, או י\"ל שיראה האנכי ולא יהי' לך שמפי הגבורה שמענו<sup data-n=\"5382\">57</sup>, וגם עכשיו פועלים הדבר הזה ע\"י תומ\"צ שמזככים הגשם וממילא נראה ונגלה עצמות א\"ס, וכן כתי' גם את העולם נתן בלבם<sup data-n=\"5383\">58</sup> של בנ\"א שע\"י תומ\"צ פועלים הזדככות גם בעולם, כי באמת אלקות שורה גם עכשיו בעולם כמ\"ש את השמים ואת הארץ אני מלא<sup data-n=\"5384\">59</sup> אך עכשיו הוא בהעלם שעולם מעלים ומסתיר אבל לע\"ל כתי' עין בעין יראו<sup data-n=\"5385\">60</sup> שבעין הגשמי' יראו אלקות בעולם כמ\"ש ולא יכנף עוד מוריך והי' עיניך רואות את מוריך<sup data-n=\"5386\">61</sup>, וגם עכשיו ע\"י תומ\"צ פועלים זה שיראה עצמות א\"ס בגילוי, וזהו\"ע עבודה ועבדת את ה' אלקיך שפי' עבודה הוא כמו עורות עבודים<sup data-n=\"5387\">62</sup> היינו אויסארבעטין שגם קודם הי' זאת אך הי' בהעלם ואחר העיבוד הוא יוצא מהעלם אל הגילוי שזהו\"ע עבודה.\n<b>אך</b> להבין ביותר איך הוא אפשר להיות שהגשם כמו שהוא יהי' כלי לעצמות א\"ס בעל הרצון, הענין הוא דהנה ארז\"ל עוה\"ב אין בו לא אכילה ולא שתי' אלא צדיקים יושבין ועטרותיהן בראשיהן ונהנין מזיו השכינה<sup data-n=\"5388\">63</sup>, שלכאורה אינו מובן איך אפשר להיות שהגוף הגשמי' יהי' ניזון מזיו השכינה, הענין הוא דהנה א\"ר עכשיו הרי הגוף ניזון מצומח וחי אך זהו כשנוטלין מהם חיותם היינו הבע\"ח צריך שחיטה<sup data-n=\"5389\">64</sup> ובלא שחיטה אסור, וצומח צריך תלישה, כי ידוע שבד\"כ יש בכל דבר גוף ונפש הגוף הוא גשם הדבר והנפש הוא החיות מהדבר וידוע שהנפש שרשו ממכ\"ע והגוף שהוא הגשם שרשו מסוכ\"ע<sup data-n=\"5390\">65</sup>, והגם שארז\"ל אין לך עשב<sup data-n=\"5391\">66</sup> למטה שאין לו מזל מלמעלה המכה בו ואומר לו גדל, אך זהו הצמיחה מקטנות לגדלות אבל עצם התהוות הגשם הוא מסוכ\"ע, נמצא שהאדם ניזון מסוכ\"ע. ואף שגם גוף האדם הוא",[["5380","55","<b>ונגלה כבוד הוי' וראו</b>: ישעי' מ, ה [בדילוג]."],["5381","56","<b>כל העוסק. . כנגדו</b>: ראה לקמן הנחה ד\"ה כנשר יעיר קנו על יד הערה 79 שמציין: אי' בגמ' — ראה תדא\"ר רפי\"ח. מאמרי אדה\"א דברים ח\"ב ע' שפז. וש\"נ. תו\"ח וארא ח\"א נח, ג. וש\"נ."],["5382","57","<b>האנכי. . שמפי הגבורה שמענו</b>: מכות כד, א. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה עשה צדקה ומשפט הערה 138."],["5383","58","<b>גם את העולם נתן בלבם</b>: קהלת ג, יא."],["5384","59","<b>את השמים. . מלא</b>: ירמי' כג, כד."],["5385","60","<b>עין בעין יראו</b>: ישעי' נב, ח."],["5386","61","<b>ולא יכנף. . את מוריך</b>: שם ל, כ."],["5387","62","<b>עבודה. . עורות עבודים</b>: ראה שבת מט, ב. תו\"ח יתרו ח\"ב רסח, ב. וש\"נ. סה\"מ תרל\"ח ע' שפ. וש\"נ."],["5388","63","<b>עוה\"ב. . מזיו השכינה</b>: ראה ברכות יז, א. מאמרי אדה\"א ויקרא ח\"א ע' קלה ואילך. המשך וככה תרל\"ז פצ\"א. פצ\"ב."],["5389","64","<b>הבע\"ח צריך שחיטה</b>: פ' ראה יב, כא. סהמ\"צ להרמב\"ם מ\"ע קמו. רמב\"ם הל' שחיטה רפ\"א."],["5390","65","<b>והגוף. . מסוכ\"ע</b>: ראה לעיל (בחלק המאמרים) מאמר ד\"ה סוכה שחמתה מרובה מצלתה ובהערה 25."],["5391","66","<b>אין לך עשב</b>: ראה ב\"ר פ\"י, ו. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 549."]]],[2000480509,"מסוכ\"ע, אך מוכרח לומר שהסוכ\"ע המחי' צומח וחי הוא גבוה יותר<sup data-n=\"5392\">67</sup>. וכן לע\"ל יוזן מסוכ\"ע. אך עכשיו ה\"ה מלובש בגוף הגשמי' ולכן מוכרח ליזון מסוכ\"ע המלובש בצומח וחי הגשמי' אבל לע\"ל שיזדכך גוף האדם שיהי' כמו אדה\"ר קודם החטא<sup data-n=\"5393\">68</sup> שכתי' עליו עקבו של אדה\"ר הי' מכה בגלגל חמה<sup data-n=\"5394\">69</sup> והוא מחמת שהי' יציר כפיו של הקב\"ה ע\"כ מחמת רוב בהירות הי' מכה<sup data-n=\"5395\">70</sup> בגלגל חמה ולע\"ל שיהי' כל אדם יציר כפו של הקב\"ה שיהי' תחית המתים ולא יהי' חלק אב ואם<sup data-n=\"5396\">71</sup>, ע\"כ יכול להיות<sup data-n=\"5397\">72</sup> גם הגוף מרוחני' דסוכ\"ע. וכמו\"כ יובן במצות שבאמת שורה במצות הגשמי' עצמות אוא\"ס והוא ע\"י אמצעות הסוכ\"ע המהווה הגשם, אך עכשיו הוא בהעלם אבל לע\"ל יתגלה, וגם עכשיו ע\"י תומ\"צ מזככים הגשם ואז מאיר עצמות א\"ס בגילוי, ועי\"ז יש בכח התומ\"צ להמשיך אורות בלתי מצומצמים באצי'. וזהו דודי לי ואני לו, שע\"י שהי' דודי לי שהי' גילוים מלמעלמ\"ט כמארז\"ל עד שנגלה עליהם<sup data-n=\"5398\">73</sup> מלך מלכי המלכים הקב\"ה וגאלם, פי' מלך הו\"ע המלאכים<sup data-n=\"5399\">75</sup> נועדו יחדיו<sup data-n=\"5400\">76</sup> שקאי על יחוד זו\"נ, מלך מלכי הו\"ע חו\"ב, ממה\"מ הוא מד' כתר<sup data-n=\"5401\">74</sup> שנתגלה העטרה מכל העולם, וע\"י שהי' גילוים גבוהים עי\"ז הי' ואני לו מלמטלמ\"ע נפשי יצא בדברו<sup data-n=\"5402\">77</sup>, ועל כל דיבור ודיבור פרחה נשמתן<sup data-n=\"5403\">78</sup>, ובנ' יום באו לקבלת התו'<sup data-n=\"5404\">79</sup>. וכמו\"כ עכשיו צריך להיות ואני לו והיינו כשעושה המצוה צריך לשעבד בה כל העשר כוחות כמו בהנחת תפילין לשעבד המוח והלב<sup data-n=\"5405\">80</sup> ובשופר כמ\"ש ברמב\"ם<sup data-n=\"5406\">81</sup> שהיד צריך לידע שאוחז השופר והפה צריך לידע שהוא תוקע והראש צריך שיהי' משועבד לבעל המצוה, ואם עושין מצוה באופן כזו אז מזדככין המצוה, ועי\"ז נגלה השראת א\"ס בעל הרצון המלובש באותה מצוה בגילוי.",[["5392","67","<b>שהסוכ\"ע המחי'. . גבוה יותר</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תקעה. וש\"נ. תו\"ח וארא ח\"א נה, ב ואילך. וש\"נ. סה\"מ מלוקט א' ע' קצא."],["5393","68","<b>לע\"ל. . כמו אדה\"ר קודם החטא</b>: ראה גם שע\"ת ח, א ובהנסמן במ\"מ לשם. מאמרי אדה\"א הנחות תקע\"ז ע' קכו."],["5394","69","<b>עקבו. . חמה</b>: ראה ויק\"ר פ\"כ, ב. זהר רע\"מ קדושים פג, ריש ע\"ב. מאמרי אדה\"א ויקרא ח\"ב ע' תרפו. וש\"נ. תו\"ח בראשית לב, א הערה 15. סה\"מ מלוקט א' ע' קעח. וש\"נ."],["5395","70","<b>מכה</b>: אוצ\"ל: מכהה."],["5396","71","<b>ולע\"ל. . ולא יהי' חלק אב ואם</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קלה. וש\"נ. ח\"ב שם. מאמר ד\"ה דור לדור מכ\"ק אדה\"א (קה\"ת תשנ\"ב) ע' 16."],["5397","72","<b>להיות</b>: אוצ\"ל: לחיות."],["5398","73","<b>עד שנגלה עליהם</b>: נוסח ההגדה."],["5399","75","<b>המלאכים</b>: אוצ\"ל: המלכים."],["5400","76","<b>המלכים נועדו יחדיו</b>: תהלים מח, ה. זהר ויגש רו, א."],["5401","74","<b>מלך. . ממה\"מ. . כתר</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 106."],["5402","77","<b>נפשי יצא בדברו</b>: שה\"ש ה, ו [ושם: יצאה]."],["5403","78","<b>ועל כל. . פרחה נשמתן</b>: ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה צאינה וראינה ובהערה 35."],["5404","79","<b>ובנ' יום באו לקבלת התו'</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1217."],["5405","80","<b>תפילין לשעבוד המוח והלב</b>: ראה שו\"ע אדה\"ז הל' תפילין סכ\"ה, סי\"א. סידור שם [נדפס גם בהוספות לשו\"ע שם ע' קנו]."],["5406","81","<b>ובשופר כמ\"ש ברמב\"ם</b>: בפרקי הצלחה — ראה בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן ובהערות 74-75 (נדפס לעיל בחלק הנחותיו)."]]],[2000480510,"<b>אך</b> זהו כשאכשיר דרא<sup data-n=\"5407\">82</sup> היינו כשעושין מצות וכדבעי למהוי, אבל אם פגם הן במ\"ע וכש\"כ במל\"ת ואפי' קיים מ\"ע ושומר א\"ע ממל\"ת אך פגם בהרהורי עבירה שבאמת הרהורי עבירה קשים מעבירה<sup data-n=\"5408\">83</sup> עצמה. ולכאורה צ\"ל איך הם קשים מהעבירה עצמה, הענין הוא כי מח' הוא לבוש דק ורוחני' ע\"כ הפגם מגיע שם יותר, כמו למשל בגד של פשתן אם נופל בו כתם מועיל בו כביסה אבל בבגד של משי אינו מועיל לו כביסה כי בכביסה מקלקל לו, או י\"ל כי מח' אף שהוא לבוש אך מ\"מ הוא לבוש להרצון שהרצון מלביש כל העשר כוחות ולכן הפגם מגיע שם יותר, כי אם פגם במ\"ע פוגם באבר א' ובמל\"ת פוגם בגיד אחד כי רמ\"ח פקודין אינון רמ\"ח אברים דמלכא<sup data-n=\"5409\">84</sup> ושס\"ה ל\"ת הם שס\"ה גידין<sup data-n=\"5410\">85</sup> אבל אם פגם במחשבה הפגם מגיע בכל הכוחות. ועוד י\"ל פי' קשה שקשה ליפרד ממנה כי כשעושה עבירה בפועל ממש אז נפסק התאווה אבל בהרהורי עבירה כל זמן שלא ימלא את צמאונו עוד הוא מהרהר אחריה. ואם פגם באחת מאלה נעשה בחי' חולה וכמו שאנו רואים בחולה שאכילה ושתי' אינו מועיל לו אלא צריך לרפואות כך מי שפגם אינו מועיל לו תורה שנק' בש' לחם ומים כמ\"ש הוי כל צמא לכו למים<sup data-n=\"5411\">86</sup>, לכו לחמי בלחמי<sup data-n=\"5412\">87</sup>, אלא צריך לרפואות שהו\"ע תשובה כמארז\"ל גדולה תשובה שמביאה רפואה לעולם<sup data-n=\"5413\">88</sup>, וענין תשובה הוא חרטה על שעבר וקבלה על להבא שהו\"ע עקירת הרצון כמו למשל חולה שיש לו צלקת או חבורה שצריך תחילה למושחו בסמני רפואות עד שיעקר הבשר החי וע\"י רפואות שאח\"כ נעשה בשר ברי כך הו\"ע תשובה כי ידוע שתשובה הו\"ע סור מרע ועש\"ט<sup data-n=\"5414\">89</sup> ונת' שסור מרע הוא יסוד כמו למשל בבנין שאם עושין יסוד תחילה אז חזק הבנין אבל אם לא יעשה היסוד אז קרוב לינפל<sup data-n=\"5415\">90</sup>. כמו\"כ קודם צריך לעשות יסוד סומ\"ר ואח\"כ הועש\"ט הוא באופן אחר. אך בסדר המצות נת' שסומ\"ר קאי על מל\"ת וע\"ט הוא מ\"ע, אך לפי הדרוש הזה שאם פגם, סומ\"ר קאי בכלל על תשובה אז אח\"כ המע\"ט באופן היותר נעלה כמו עד\"מ שאנו רואים ברוב חולים פנימי' שע\"י רפואות אז אח\"כ ע\"י אכילה ושתי' נעשה חזק יותר כך ע\"י תשובה נעשה אח\"כ חזק יותר בועש\"ט.",[["5407","82","<b>כשאכשיר דרא</b>: ע\"פ יבמות לט, ב. חולין צג, ב."],["5408","83","<b>הרהורי עבירה קשים מעבירה</b>: ראה יומא כט, א. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 381."],["5409","84","<b>רמ\"ח פקודין אינון רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["5410","85","<b>ושס\"ה ל\"ת הם שס\"ה גידין</b>: ראה תרגום יוב\"ע בראשית א, כז. זהר וישלח קע, ב."],["5411","86","<b>הוי כל צמא לכו למים</b>: ישעי' נה, א."],["5412","87","<b>לכו לחמי בלחמי</b>: משלי ט, ה [ושם: לחמו]."],["5413","88","<b>גדולה תשובה. . לעולם</b>: יומא פו, סע\"א."],["5414","89","<b>סור מרע ועש\"ט</b>: תהלים לד, טו. ראה גם לקמן הנחה ד\"ה שובה ישראל הב' על יד הערה 68. לקו\"ת אמור לג, ב. שלח לו, ד. המשך מים רבים תרל\"ו פקצ\"א. סה\"מ תרל\"ח ס\"ע שו ואילך. ע' תצט."],["5415","90","<b>לינפל</b>: כ\"ה בהכת\"י."]]],[2000480511,"<b>ולהבין</b> זה איך נעשה ע\"י תשובה חזק יותר מקודם, הנה כתי' כי חלק הוי' עמו כי<sup data-n=\"5416\">92</sup> יעקב חבל נחלתו<sup data-n=\"5417\">91</sup>, כי הנשמה נמשלה לחבל שכמו חבל שראשה העליון קשור למעלה וראשה התחתון למטה וכשמתנענע הקצה התחתון מתנענע גם הקצה העליון, כך הנשמה שרשה למעלה, ומה שמתלבשת בגוף אינו אלא הארה ממנה, וע\"י מה הקישור השורש עם ההארה הוא ע\"י חבל דתומ\"צ כי כמו חבל הוא מריבוי נימין נעשה חבל כך ע\"י רמ\"ח מ\"ע ושס\"ה מל\"ת<sup data-n=\"5418\">93</sup> עי\"ז נעשה החבל, וכשפוגם באיזה מצוה פוגם בהחבל, וע\"י ריבוי פגמים נפגם כל החבל, וע\"י ענין כריתות נכרת החבל משרשו. אך עכ\"ז מועיל תשובה, כי מה שארז\"ל באחר שובו בנים שובבים חוץ מאחר<sup data-n=\"5419\">94</sup>, זהו רק תשובה תתאה לא הי' מועיל לו אבל תשובה עילאה הי' מועיל, והראי' מר' מאיר שאמר דומה רבי שמתוך תשובה מת<sup data-n=\"5420\">95</sup> נמצא שתשובה מועלת לו. ובאמת גם תשובה תתאה מועיל אך אין מספיקין בידו לעשות תשובה<sup data-n=\"5421\">96</sup>, אין נותנין לו עזר מלמעלה אבל מ\"מ תשובה מועיל, ואדרבא ע\"י תשובה נעשה חזק יותר כמו למשל שאנו רואים בחבל שאם נכרת במקום אחד וע\"י קשר שסתם קשר הוא בת ד' פקיעות<sup data-n=\"5422\">97</sup> נעשה במקום הזה חזק יותר, שאם יהי' נפסק החבל לא יהי' נפסק במקום הקשר, כמו\"כ ע\"י תשובה נעשה חזק יותר מבתחילה כמו למשל בחולה הנ\"ל שע\"י אכילה ושתי' שלאחר הרפואות נעשה חזק מכמו שהי' קודם שהי' חולה.\n<b>אך</b> כדי שיבוא לתשובה צריך מקודם לעורר רחמים רבים על נפשו, שבאמת על ירידת הנשמה בגוף הרחמנות גדולה עד אין שיעור, שקודם בואה בגוף כתי' עלה חי הוי' אשר עמדתי לפניו<sup data-n=\"5423\">98</sup> ופי' עמדתי הוא עמידה בביטול באהבה ויראה כמו על מלאכים שכתי' אצלם ויעמידם לעד לעולם<sup data-n=\"5424\">99</sup> וכמ\"ש שרפים עומדים<sup data-n=\"5425\">100</sup> ממעל לו שבמלאכים אינו שייך עמידה גשמי' אלא הוא עמידה בבחי' ביטול, והנה מה מלאכים שהם מחיצוני' הכלים עמידתם הוא באהבה ויראה וכש\"כ נשמה שהיא מפנימי' הכלים<sup data-n=\"5426\">101</sup> בודאי עמידתה היא באהבה ויראה, ואח\"כ ירדה בגוף ונה\"ב שהגוף מעלים ומסתיר על הנפש והירידה הי' בשביל העלי'<sup data-n=\"5427\">102</sup> שיהי' אח\"כ, והנה אפי' כשאינה",[["5416","92","<b>כי</b>: תיבה זו לכאורה מיותרת."],["5417","91","<b>כי חלק. . יעקב חבל נחלתו</b>: האזינו לב, ט. ראה גם תניא פמ\"ה. אגה\"ת פ\"ו. מאמרי אדה\"א שמות ח\"ב ע' תרז. וש\"נ. לקו\"ת תצא לה, ב. ולהעיר מר\"ח שער היראה פי\"ד."],["5418","93","<b>רמ\"ח מ\"ע ושס\"ה מל\"ת</b>: מכות כג, סע\"ב."],["5419","94","<b>שובו בנים שובבים חוץ מאחר</b>: ירמי' ג, יד. כב. חגיגה טו, א."],["5420","95","<b>מר' מאיר. . שמתוך תשובה מת</b>: ראה ירושלמי חגיגה פ\"ב, ה\"א. רו\"ר פ\"ו, ד (יג). קה\"ר פ\"ז, ח. יל\"ש קהלת ז, ח (סוף רמז תתקעד). עמק המלך שער עולם התהו ש\"ו, פמ\"ט."],["5421","96","<b>אין מספיקין בידו לעשות תשובה</b>: יומא פה, ב (במשנה)."],["5422","97","<b>הקשר. . ד' פקיעות</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן ובהערה 410."],["5423","98","<b>חי הוי' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["5424","99","<b>ויעמידם לעד לעולם</b>: תהלים קמח, ו. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א. וש\"נ."],["5425","100","<b>שרפים עומדים</b>: ישעי' ו, ב. ראה סוטה לט, א (צויין אליו ב) לקו\"ת נשא כ, ג. כב, ג."],["5426","101","<b>מלאכים שהם מחיצוני'. . מפנימי' הכלים</b>: נסמן לעיל הנחה ד\"ה אני לדודי הערה 45."],["5427","102","<b>והירידה הי' בשביל העלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."]]],[2000480512,"מורידה אם אינו מעלה אותה כתי' ע\"ז צללו<sup data-n=\"5428\">103</sup> במים אדירים והעלה בידו חרס<sup data-n=\"5429\">104</sup>, ובפרט ע\"י ריבוי פגמים שמכף רגל ועד ראש אין בו מתום, פצע וחבורה ומכה טרי'<sup data-n=\"5430\">105</sup>, ולפעמים ע\"י ריבוי עוונות נכרת לגמרי משרשו כי עוונותיכם מבדילים<sup data-n=\"5431\">106</sup> שע\"ז כתי' ומעיין טהור יצא מבית הוי'<sup data-n=\"5432\">107</sup> והורדתם למקום הטינופת אשת הזימה. וכשמתבונן בכל זה נעשה מזה צעקה פנימי' מעומקא דלבא וזהו\"ע שופר פשוטה לפני' ופשוטה לאחרי'<sup data-n=\"5433\">108</sup> ושברים תרועה באמצע, פשוטה לפניה שזהו כמו חולה שמרגיש שהוא חולה אז צועק בצעקה פנימי', וכן יובן בענין אם מתבונן בנפשו אז צועק בצעקה פנימי' על מה שרואה שעולם כמנהגו נוהג<sup data-n=\"5434\">109</sup> שזהו שייך לקליפת עמלק אשר קרך<sup data-n=\"5435\">110</sup>, ואח\"כ הוא שברים תרועה גינוחי גניח ילילי יליל<sup data-n=\"5436\">111</sup> כמו חולה שמרגיש פרטי מכאביו אז הוא מגנח ואח\"כ מתבונן בכלל חליותו צועק עוד צעקה פנימי' וזהו\"ע שופר אף שיש ריבוי טעמים ע\"ז אך זהו העיקר הטעם. ועי\"ז בא לתשובה שהו\"ע החזרת פנים בפנים, דהנה כתי' כי פנו אלי עורף<sup data-n=\"5437\">112</sup> ולא פנים, הגם שפנו אלי שעושה מצות אך זהו מ\"מ בבחי' עורף באחוריים וחיצוני', היינו שנותנים צדקה ווייל עס פאסט אזוי, או מה יאמרו הבריות<sup data-n=\"5438\">113</sup> באם שלא אתן צדקה, שזהו יחוד אחור באחור עד\"מ בשני בני אדם הגם שעומדים בקרוב זל\"ז אך אם הוא אחור באחור אין לך ריחוק גדול מזה, ואח\"כ כשחוזרין להיות פנים בפנים אז הם מקורבים. וכשעושה המצוה ע\"ד כי פנו אלי עורף עי\"ז נעשה גם למעלה ענין מ\"ש ואנכי הסתר אסתיר פני<sup data-n=\"5439\">114</sup> ביום ההוא, אבל ע\"י אני לדודי החזרת פנים מלמטלמ\"ע עי\"ז נעשה ודודי לי החזרת פנים מלמעלמ\"ט כמ\"ש שובה אלי ואשובה אליכם<sup data-n=\"5440\">115</sup>, סלח לנו<sup data-n=\"5441\">116</sup> כו'. ע\"כ ניחא מ\"ש כאן הרועה בשושנים שהו\"ע התעוררות ר\"ר לבוא לתשובה.\n<b>אך</b> מה שכתי' בפסוק דודי לי ואני לו כתי' התם ג\"כ הרועה בשושנים, מה ענין שושנים שם. אך הנה ארז\"ל אל תיקרא שושנים אלא ששונים<sup data-n=\"5442\">117</sup> ששונים בהלכות, ולכאו' אינו מובן מהו ענין אל תקרא הלא באמת כתי' שושנים, אך הענין",[["5428","103","<b>צללו</b>: כשצ\"ל: צלל."],["5429","104","<b>צלל במים אדירים והעלה בידו חרס</b>: ראה בב\"ק צא, סע\"א. רמב\"ם הל' קדוש החדש פי\"א, ה\"ב."],["5430","105","<b>שמכף רגל. . ומכה טרי'</b>: ישעי' א, ו."],["5431","106","<b>עוונותיכם מבדילים</b>: ישעי' נט, ב."],["5432","107","<b>ומעיין טהור יצא מבית הוי'</b>: יואל ד, יח [ושם: ומעין מבית ה' יצא]."],["5433","108","<b>פשוטה לפני' ופשוטה לאחרי'</b>: ראה ר\"ה לד, א. שו\"ע אדה\"ז חאו\"ח הל' ר\"ה רסתק\"צ."],["5434","109","<b>שעולם כמנהגו נוהג</b>: ע\"ז נד, ב. ראה גם לקמן הנחה ד\"ה ושאבתם מים על יד הערה 44."],["5435","110","<b>אשר קרך</b>: תצא כה, יח. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 560."],["5436","111","<b>גינוחי גניח ילילי יליל</b>: ר\"ה לג, ב. לד, א."],["5437","112","<b>כי פנו אלי עורף</b>: ירמי' ב, כז. ראה גם (לעיל בחלק המאמרים) בההמשך כאן על יד הערה 513. סה\"מ תרל\"ג ח\"ב ס\"ע שצו ואילך. וש\"נ. מאמרי אדה\"א נ\"ך ס\"ע רי ואילך. וש\"נ."],["5438","113","<b>מה יאמרו הבריות</b>: במדב\"ר פי\"ט, יג. יומא פו, א."],["5439","114","<b>ואנכי הסתר אסתיר פני</b>: וילך לא, יח."],["5440","115","<b>שובה אלי ואשובה אליכם</b>: מלאכי ג, ז [ושם: שובו]."],["5441","116","<b>סלח לנו</b>: נוסח תפלת שמו\"ע."],["5442","117","<b>אל תיקרא שושנים אלא ששונים</b>: נסמן לעיל הנחה ד\"ה אני לדודי הא' הערה 77."]]],[2000480513,"הוא כי בעת שאמר משה רבינו ע\"ה אנא אל נא רפא נא לה<sup data-n=\"5443\">118</sup> השיבו לו ואביה ירק בפניה<sup data-n=\"5444\">119</sup> קו\"ח לשכינה ד'<sup data-n=\"5445\">120</sup> ימים, ולכאו' מה ענין קו\"ח לענין הנ\"ל, ואמר ה\"ה<sup data-n=\"5446\">121</sup> המגיד ממעזריטש ז\"ל ע\"ז מחמת שמשה הזכיר ש' אל<sup data-n=\"5447\">122</sup> שהוא מדה ראשונה מיגמדה\"ר<sup data-n=\"5448\">123</sup> ע\"כ השיבו לו קו\"ח שהוא מדה ראשונה מי\"ג מדות שהתורה נדרשת בהן<sup data-n=\"5449\">124</sup>, נמצא מובן שע\"י קו\"ח יכול להמשיך בחי' אל שבאמת הם ענין א', וע\"כ בפסוק אני לדודי שקאי על תשובה ניחא מה שכתי' התם הרועה בשושנים שהוא יגמה\"ר אך בפסוק דודי לי שהו\"ע תורה אז ארז\"ל א\"ת שושנים אלא ששונים שבאמת שרש י\"ג מדות שהתורה נדרשת בהן שרשם הוא ביגמה\"ר. אך כדי לבוא להתעוררות רחמים רבים שעי\"ז יבוא לתשובה החזרת פנים בפנים שעי\"ז יהי' ודודי לי לזה צריך גם עזר מלמעלה וזהו\"ע הד' יודי\"ן שרומזים על המ' יום שע\"ז כתי' כימים הראשונים ברצון, ומאחר שהם ימי רצון בימים אלו יש כח מלמעלה לבוא להתעוררות רחמים שעי\"ז יבוא לתשובה אני לדודי ועי\"ז יהי' ודודי לי.",[["5443","118","<b>אנא אל נא רפא נא לה</b>: בהעלותך יב, יג [בהוספת תיבת אנא — וכ\"ה גם לעיל בהנחות כ\"ק אדמו\"ר מהורש\"ב בהנחה כאן]."],["5444","119","<b>השיבו לו ואביה ירק בפניה</b>: שם שם, יד [בדילוג]. רש\"י וספרי שם. ב\"ק כה, א."],["5445","120","<b>ד'</b>: כנשצ\"ל: י\"ד."],["5446","121","<b>ה\"ה</b>: הרב הגאון הרב החסיד"],["5447","122","<b>המגיד ממעזריטש ז\"ל. . ש' אל</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן הערות 427. 429."],["5448","123","<b>ש' אל. . מיגמדה\"ר</b>: ראה לקו\"ש אלול כרך ד ע' 1348 ואילך. ובאג\"ק שלו ח\"ב ע' שסט ואילך."],["5449","124","<b>מי\"ג מדות שהתורה נדרשת בהן</b>: תו\"כ ר\"פ ויקרא."]]],[2000480514,"<h3>יפה שעה אחת הב'</h3>\n<b>בס\"ד</b>\n<b>יפה</b> שעה אחת<sup data-n=\"5450\">1</sup> בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב<sup data-n=\"5451\">2</sup>, ולכאו' צ\"ל מהו\"ע החיבור תשובה למע\"ט, עפ\"י סדר עבודה הלא ענין תשובה הוא על חטא ועון ומאחר שהמעשים הם טובים א\"כ מה שייך תשובה. ולהבין זה י\"ל מ\"ש אני לדודי ועלי תשוקתו<sup data-n=\"5452\">3</sup>, ולכאורה לפי לשון הכתוב אני לדודי הי' צריך לכתוב ואלי תשוקתו בא', והענין הוא שאי' במד\"ר ד' תשוקות הן<sup data-n=\"5453\">4</sup>, תשוקת אשה לבעלה שנא'",[["5450","1","<b>יפה שעה אחת</b>: הנחה ממאמר הז' מהמשך יונתי (פי\"ט-פכ\"א<sup data-n=\"e329\">*</sup>) שנדפס לעיל בחלק המאמרים [ושם הפתיחה: ומעתה כו' אני לדודי ועלי תשוקתו].\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לעיל (בחלק הנחותיו)."],["5451","2","<b>יפה שעה א'. . העוה\"ב</b>: אבות פ\"ד, מי\"ז."],["5452","3","<b>אני לדודי ועלי תשוקתו</b>: שה\"ש ז, יא. ראה גם (לעיל בחלק המאמרים) המשך יונתי כאן ובהערה 435."],["5453","4","<b>במד\"ר ד' תשוקות הן</b>: ראה ב\"ר פ\"כ, ז. שהש\"ר פ\"ז, יא."],["e329","*","חלק מפרק כא נכנס בדרוש ויובן ענין הטוב (ר\"ה תרמ\"א)."]]],[2000480515,"ואל אישך תשוקתך<sup data-n=\"5454\">5</sup>, תשוקת יצה\"ר לקין וחביריו שנא' ואליך תשוקתו<sup data-n=\"5455\">6</sup>, תשוקת גשמים לארץ שנא' פקדת הארץ ותשוקקיה<sup data-n=\"5456\">7</sup>, אין תשוקת הקב\"ה אלא על ישראל שנא' אני לדודי ועלי תשוקתו, וצ\"ל הד' תשוקות בשלמא תשוקת אשה לבעלה הוא תשוקת המקבל להמשפיע כי לזאת יקרא אשה<sup data-n=\"5457\">8</sup> כי מאיש לקחה זאת, אשה הוא אש ה'<sup data-n=\"5458\">9</sup> ואיש הוא אש יו\"ד<sup data-n=\"5459\">10</sup> והה' הוא מקבל מיו\"ד שהתשוקה הוא מהמקבל להמשפיע. וכן תשוקת גשמים להארץ הוא תשוקת המשפיע למקבל כמ\"ש בזהר מטרא בעלה דארעא<sup data-n=\"5460\">11</sup>, אבל תשוקת הקב\"ה על ישראל לכאורה אינו מובן איך שייך למעלה תשוקה הלא מה שאנו קוראים למטה תשוקה הוא דוקא שייך באדם כשחסר לאדם אחד איזה דבר ויודע שאם ישיגנה ישלים רצונו בזה, משתוקק לדבר ההוא, אבל למעלה שאנת הוא שלימותא דכולהו<sup data-n=\"5461\">12</sup> וכלום חסר הוא שאפי' רצון סתם אינו שייך למעלה ובפרט ענין תשוקה שהוא פי' רצון בתוקף בודאי אינו שייך למעלה, ובאמת מצינו כמה פעמים שיש ענין תשוקה למעלה כמ\"ש רק באבותיך חשק הוי'<sup data-n=\"5462\">13</sup> או כמו שאי' נתאוה הקב\"ה להיות לו ית'<sup data-n=\"5463\">15</sup> דירה בתחתוני'<sup data-n=\"5464\">14</sup> אף שאין ידוע לנו הטעם מפני מה נתאוה<sup data-n=\"5465\">16</sup> מ\"מ זאת ידוע לנו שנתאווה או כמו שאי' במד\"ר ע\"פ שוקיו עמודי שש מלמד שנשתוקק הקב\"ה<sup data-n=\"5466\">17</sup> שהו\"ע תשוקה שלכאו' אינו מובן איך שייך למעלה תשוקה וענין נתאווה. ועוד ממה שאמר במד\"ר הנ\"ל דד' תשוקות שאין תשוקת הקב\"ה אלא על ישראל משמע מזה שלשון הכתוב מה שכתי' ועלי תשוקתו עלי בע' הוא מדויק וצ\"ל למה כתי' כן ולא בא'.\n<b>ולהבין</b> כ\"ז יש להבין מה שכתי' אני לדודי ודודי לי ונת' שקאי על ענין תשובה<sup data-n=\"5467\">19</sup> כי הוא ר\"ת אלול וס\"ת ד' יודי\"ן<sup data-n=\"5468\">18</sup> שרומזים על הארבעים יום שהם ימי רצון שבהם נותנים כח מלמעלה לעשות תשובה, אך באמת י\"ל שהפסוק הזה קאי על כללות עבודה בתומ\"צ כי הנה אי' בילקוט אני לדודי בעוה\"ז ודודי לי בעוה\"ב<sup data-n=\"5469\">20</sup>, ולפי",[["5454","5","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["5455","6","<b>ואליך תשוקתו</b>: בראשית ד, ז."],["5456","7","<b>פקדת הארץ ותשוקקיה</b>: תהלים סה, י."],["5457","8","<b>כי לזאת יקרא אשה</b>: בראשית ב, כג [בהוספת תיבת כי]."],["5458","9","<b>אשה הוא אש ה'</b>: ראה סוטה יז, א. זהר בראשית מח, ב. ביאוה\"ז נח ז, ב. תו\"ח שבהערה הבאה."],["5459","10","<b>ואיש הוא אש יו\"ד</b>: ראה סוטה שם. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אשה. תו\"ח בשלח ח\"א רלח, ב. וש\"נ."],["5460","11","<b>בזהר מטרא בעלה דארעא</b>: ראה גם המשך מים רבים תרל\"ו פק\"ו ובהערה לשם תענית ג, ב. וכנשצ\"ל: תענית ו, ב."],["5461","12","<b>שאנת הוא שלימותא דכולהו</b>: ראה ת\"ז בהקדמה יז, ב."],["5462","13","<b>רק באבותיך חשק הוי'</b>: עקב י, טו."],["5463","15","<b>ית'</b>: ראה גם (לעיל בחלק המאמרים) בההמשך כאן ובהערה 351."],["5464","14","<b>נתאוה הקב\"ה. . דירה בתחתוני'</b>: ראה תניא רפל\"ו. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1693."],["5465","16","<b>אף. . מפני מה נתאוה</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1776."],["5466","17","<b>שוקיו עמודי שש מלמד שנשתוקק הקב\"ה</b>: שה\"ש ה, טו. ראה במד\"ר רפ\"י."],["5467","19","<b>ונת'. . תשובה</b>: לעיל הנחה ד\"ה אני לדודי הב'."],["5468","18","<b>אני לדודי. . ר\"ת אלול וס\"ת ד' יודי\"ן</b>: שה\"ש ו, ג. ראה (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה רד\"ה אני לדודי הב'. וש\"נ."],["5469","20","<b>אני לדודי בעוה\"ז ודודי לי בעוה\"ב</b>: ילקוט שמעוני שה\"ש ו, ג (סוף רמז תתקצא)."]]],[2000480516,"פי' הזה א\"א לומר שקאי על תשובה דוקא כי באמת עיקר המכוון בעוה\"ז הוא בכדי שיהי' צדיקים גמורים ולא בע\"ת, אלא מוכרח לומר שקאי על כללות עבודה דתומ\"צ אך תשובה הוא ג\"כ מצוה<sup data-n=\"5470\">21</sup> וצ\"ל איך תשובה היא מצוה הלא היא כמו פתח ושער בתורה לחטוא<sup data-n=\"5471\">22</sup>. ולכאורה הוא כמו שהקשינו למעלה מה ענין תשובה ומע\"ט. אך התם יש לתרץ שעה א' בתשובה הוא מלשון פ קערין ואח\"כ המעשים הם טובים<sup data-n=\"5472\">23</sup>, אבל מה שמצינו כל ימיו בתשובה<sup data-n=\"5473\">24</sup> אינו מובן הלא תשובה הוא על חטא ועון שהוא ע\"ד אחטא ואשוב<sup data-n=\"5474\">25</sup> ואחטא ואשוב שעליו כתי' אין מספיקין בידו לעשות תשובה, פי' אין מספיקין לא לבד שאין מועיל לו תשובה, גם מלמעלה אין מניחין אותו לשוב. אלא מוכרח לומר שפי' תשובה הוא לא כמו שהעולם סובר שהוא על חטא ועון דוקא אלא פי' תשובה הוא חזרה ובזה יש כמה אופנים באמת עיקר תשובה הוא כשפגם מתחילה שאז שייך בודאי תשובה חזרה כי קודם הי' בבחי' אחור באחור ואח\"כ ע\"י תשובה נעשה החזרת פנים בפנים אך ענין חזרה נושא עליו גם כשלא חטא כלל<sup data-n=\"5475\">26</sup> אפי' בדקדוק קל של דברי סופרים, כי אפי' דקדוק קל נק' ג\"כ חטא, כי פי' חטא הוא מלשון חסרון<sup data-n=\"5476\">27</sup> כמ\"ש קולע אל השערה ולא יחטיא<sup data-n=\"5477\">28</sup> פי' ולא יחטיא שלא יחסיר, ומאחר שחסר הרי חטא, או כמ\"ש אני ובני שלמה חטאים ופרש\"י כלומר חסרים<sup data-n=\"5478\">29</sup> שפי' שחסרים מהציווי של דוד. נמצא שאם חטא פי' שחסר אפי' מדקדוק קל של ד\"ס נק' ג\"כ חטא, והתשובה הוא אינו על חטא ועון כלל אלא אפי' כשעשה הכל כדבעי מ\"מ שייך ענין תשובה כמו שאי' משיחא אתא לאתבא צדיקיא בתיובתא<sup data-n=\"5479\">30</sup> שאפי' בצדיקים גמורים שייך ענין תשובה שהו\"ע והרוח תשוב אל אלקי'<sup data-n=\"5480\">31</sup> אשר נתנה שהנפש הוא חלק אלקה ממעל<sup data-n=\"5481\">32</sup> כמ\"ש כי חלק הוי' עמו<sup data-n=\"5482\">33</sup> וירדה להתלבש בגוף ונה\"ב וכשחוזרת אל חיק אביה גם זה נק' תשובה היינו חזרה למקורה ושרשה והוא",[["5470","21","<b>תשובה הוא ג\"כ מצוה</b>: ראה (לעיל בחלק המאמרים) המשך יונתי כאן הערה 464."],["5471","22","<b>תשובה היא מצוה. . לחטוא</b>: ראה ברכת שמואל לר' אהרן שמואל קאיידנבור פ' וילך נד, ג."],["5472","23","<b>אפ קערין. . המעשים הם טובים</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'קעט. וש\"נ. תו\"ח וארא ח\"א ריש ע' סו. וש\"נ. סה\"מ תרל\"ח ע' שטז. וש\"נ."],["5473","24","<b>כל ימיו בתשובה</b>: שבת קנג, א. ראה גם לקו\"ת בלק עד, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקטו. לקמן קרוב לסיום המאמר."],["5474","25","<b>אחטא ואשוב</b>: ראה יומא פה, ב (במשנה)."],["5475","26","<b>תשובה הוא חזרה. . גם כשלא חטא כלל</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי כאן ובהערה 454."],["5476","27","<b>חטא הוא מלשון חסרון</b>: ראה לקו\"ת מטות פב, א. נצבים נא, א. מאמרי אדה\"א דברים ח\"ג ע' תתקיד. נ\"ך ע' נא. סה\"מ תרל\"ב ח\"א ע' קמד. המשך תער\"ב ח\"ג ע' א'תנט. סה\"מ מלוקט א' ע' רצב. שם ב' ע' קכח ובהנסמן בהנ\"ל."],["5477","28","<b>קולע אל השערה ולא יחטיא</b>: ס' שופטים כ, טז [בדילוג]."],["5478","29","<b>אני ובני שלמה חטאים ופרש\"י כלומר חסרים</b>: מלכים-א א, כא. תיבת כלומר לא הובא ברש\"י שם — ראה לקמן הנחה ד\"ה שובה ישראל הא' ובהערה 66."],["5479","30","<b>משיחא אתא לאתבא צדיקיא בתיובתא</b>: ראה זהר רע\"מ בהעלותך קנג, ב. מאמרי אדה\"א קונטרסים ע' רפא. וש\"נ. תו\"ח שמות ח\"א מא, ב. וש\"נ."],["5480","31","<b>והרוח תשוב אל אלקי'</b>: קהלת יב ז [ושם: האלקי']."],["5481","32","<b>חלק אלקה ממעל</b>: איוב לא, ב. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 395."],["5482","33","<b>כי חלק הוי' עמו</b>: האזינו לב, ט. ראה גם לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים סוף פיסקא א."]]],[2000480517,"עד\"מ אחד שהולך בדרך אשר צריך לילך בה אך כשחוזר אח\"כ למקומו נק' בש' חזרה וזהו\"ע תשובה.\n<b>ולהבין</b> כ\"ז צ\"ל תחילה מה שאי' ששבת הו\"ע תשובה<sup data-n=\"5483\">34</sup> כי שבת הוא אותיו' תשב<sup data-n=\"5484\">35</sup> ולכאורה אינו מובן מה שייך שבת לתשובה הלא שבת היא מצוה בפ\"ע<sup data-n=\"5485\">36</sup> ותשובה הוא מצוה בפ\"ע מהו\"ע זל\"ז. אך הנה פי' שבת הוא לשון שביתה כי הנה כתי' ששת ימים עשה הוי' את השמים ואת הארץ וביום השביעי שבת<sup data-n=\"5486\">37</sup>, כתי' ששת ולא בששת ימים שהי' משמע שבזמן ששת ימים הי' המפעל פועל בנפעל אלא כתי' ששת ימים שמשמע שהששת ימים עצמם נשפלו בהעשי', ופי' ששת ימים הוא ששה מדות העליונות והם נשפלו למטה בהעשי', והוא כמ\"ש בזהר כל יומא ויומא עביד עבידתי'<sup data-n=\"5487\">38</sup> ביום הראשון הי' מאיר מדת החסד וביום השני מדת הגבורה וכן ביום השלישי ת\"ת, ופי' שנשפל למטה החסד ופעל הפעולה של יום הראשון, כי חסד שלמעלה אינו כמו חסד שלמטה<sup data-n=\"5488\">39</sup>, שחסד שלמטה הוא גרם ההשפעה מחמת שהוא חסדן לכן משפיע לזולתו, אבל למעלה החסד הוא עצם ההשפעה כמ\"ש מכלכל חיים בחסד<sup data-n=\"5489\">40</sup> שהחסד עצמו הוא המשפיע חיים, ול\"ד חיות אלא גם התהוות כמאמר א\"ת מחי' אלא מהוה<sup data-n=\"5490\">41</sup>, נמצא שהמדות עצמן נשפלו בעשיות שמים וארץ. ובאמת כתי' בעשרה דברים ברא הקב\"ה<sup data-n=\"5491\">42</sup> את עולמו בחכ' ובתבונה ובדעת שנא' הוי' בחכ' יסד ארץ<sup data-n=\"5492\">43</sup> כונן שמים בתבונה בדעתו תהומות נבקעו<sup data-n=\"5493\">44</sup>, ואין זה סתירה כי מדות דתיקון התכללותם מעשר<sup data-n=\"5494\">45</sup> ונמצא בהם גם בחי' מוחין. והוא כמו שאנו רואים למטה באדם כשעושה מלאכה שרוב פעולותיו הוא ביד ומיעוטו הוא ברגל, ואף כשעושה המלאכה באבר אחד ביד או ברגל מ\"מ מוכרח להלביש בזה כל כחותיו כמו העין לראות את הדבר העושה כי סומא אינו יכול לעשות מלאכה מחמת שחסר לו כח הראי', וכן ראי' השכל שהוא כללות השכל חב\"ד מוכרח להלביש בהפעולה כמו חכ' הוא להמצאות הדבר ובינה הוא השגה והבנה ודעת הוא התקשרות בהדבר<sup data-n=\"5495\">46</sup>, וכן",[["5483","34","<b>ששבת הו\"ע תשובה</b>: ראה אגה\"ת ספ\"י. וראה גם לקו\"ת ש\"ש סו, ג. המשך מים רבים תרל\"ו פקע\"ח. סה\"מ מלוקט ו' ע' שמה."],["5484","35","<b>שבת הוא אותיו' תשב</b>: ראה (לעיל בחלק המאמרים) המשך יונתי כאן ובהערה 462."],["5485","36","<b>שבת היא מצוה בפ\"ע</b>: ראה סהמ\"צ להרמב\"ם מ\"ע קנד. קנה. רמב\"ם הל' שבת רפ\"א. רפכ\"ט."],["5486","37","<b>ששת ימים. . שבת</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, ריש ע\"ב. האזינו חצר, ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["5487","38","<b>כל יומא. . עבידתי'</b>: ראה זהר ויגש רה, סע\"א. אמור שם. השמטות לזח\"א רסד, ב."],["5488","39","<b>חסד שלמעלה. . חסד שלמטה</b>: ראה אוה\"ת יתרו ס\"ע תתקכו ואילך. סה\"מ תרכ\"ו ע' ב."],["5489","40","<b>מכלכל חיים בחסד</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה והנה כובע ובהערה 95."],["5490","41","<b>א\"ת מחי' אלא מהוה</b>: ראה שער היחוה\"א פ\"ב ובמ\"מ, הגהות והע\"ק שם. הערה בסה\"מ תש\"ד ע' 20."],["5491","42","<b>בעשרה דברים ברא הקב\"ה</b>: ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וביום הביכורים ובהערה 41."],["5492","43","<b>הוי' בחכ' יסד ארץ</b>: משלי ג, יט."],["5493","44","<b>בדעתו תהומות נבקעו</b>: משלי שם, כ."],["5494","45","<b>מדות. . מעשר</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"א. לקו\"ת מטות פז, ב."],["5495","46","<b>ודעת הוא התקשרות בהדבר</b>: ראה גם לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 37."]]],[2000480518,"מצינו גם בחוש השמיעה שאף שהוא רחוק מפעולה מ\"מ מצינו שמוכרח להלביש חוש השמיעה בהפעולה דהיינו המלאכת<sup data-n=\"5496\">47</sup> אופן בתוך אופן שיש שם חשבון שהאופן הגדול מגלגל את אופן הקטן וצריך לשמוע היטיב שלא ילך בכבדות שאם ההילוך הוא בכבדות אפשר להיות שיהי' נפסק ההילוך לגמרי, ובאמת אנו רואים שכל הכוחות נשפלים כ\"כ וטרודים בהפעולה ואינו יכול לפעול בהם פעולה אחרת כמו למשל כשכותב או כשמצייר איזה ציור לא לבד שאינו יכול לעשות מלאכה אחרת אלא שאין יכול לדבר וכן לא יכול לשמוע מה שזולתו מדבר פי' אף שישמע אך יבלבל אותו.\n<b>וכמו\"כ</b> יובן למעלה אף שכתי' ששת ימים עשה שרק הששה מדות נשפלו למטה בעשי' אך בהתכללותם נכלל בהם גם מוחין ואדרבא עיקר ההתהוות הוא מהמוחין כי באמת כתי' בשלשה דברים ברא הקב\"ה<sup data-n=\"5497\">48</sup> את עולמו בחכ' ובתבונה ובדעת בשלשה לחוד כי מי הוא המוליד ומגלה המדות הלא המוחין, ואף שהמדות הם גבוהים במד' מהמוחין כי ז\"א בעתיק תלי'<sup data-n=\"5498\">49</sup> פי' ע\"ד המעתיק הרים<sup data-n=\"5499\">50</sup> והמתנשא מימות עולם<sup data-n=\"5500\">51</sup>, אך זהו רק נקודת המדות אבל בהשתל' עיקר גילוי המדות הוא מהמוחין עד שנוכל לומר שעיקר התהות המדות הוא מהמוחין, כי אנו רואים כשאדם מתבונן במוחין שלו שטוב הדבר אז נתגלה מדת האהבה לדבר ההוא, אך הנה כאן כתי' בחכ' ושם כתי' ששת ולא בששת כמו הכי<sup data-n=\"5501\">52</sup> מפני שהמדות הם בעצמם נשפלו למטה אבל החכ' כתי' בחכ' בדרך התלבשות וכן כתי' בראשית נמי מאמר הוא<sup data-n=\"5502\">53</sup> ותרגומו בראשי' בחוכמתא<sup data-n=\"5503\">54</sup>, שהחכ' הוא מאמר כללי ואח\"כ נתחלק לט' מאמרות<sup data-n=\"5504\">55</sup> פרטים, נמצא מובן מזה שגם בחי' חכ' הי' נשפל בהעשי' ואף שהם מוחין שבמדות מ\"מ ה\"ה מוחין כי במוחין עצמם יש מד' הרבה זה למעלה מזה כמו שאי' לא כל מוחא סביל דא<sup data-n=\"5505\">56</sup>, אבל יש מוחא דסביל, וכמו בענין הלימוד זה מבין באופן כזה וזה מבין בעומק יותר כו' אבל עכ\"ז ה\"ה מוחין, וכמו\"כ הכי הגם שהם מוחין שבמדות מ\"מ ה\"ה מוחין, וזהו ששת ימים עשה שהו\"ע ששה מדות ובהם נכללו גם המוחין אבל ביום השביעי כתי' שבת וינפש שהי' השביתה. וענין השביתה הוא כמו שאנו רואים למטה באדם",[["5496","47","<b>המלאכת</b>: אוצ\"ל: במלאכת."],["5497","48","<b>בשלשה דברים ברא הקב\"ה</b>: ראה תנחומא ויקהל ה. שמו\"ר פמ\"ח, ד."],["5498","49","<b>ז\"א בעתיק תלי'</b>: ראה זהר אד\"ז האזינו רצב, א. ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 543."],["5499","50","<b>המעתיק הרים</b>: איוב ט, ה. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' רמה. וש\"נ. שעה\"י קכו, א ובהערה 5. תו\"ח בשלח ח\"א קמב, סע\"ב. וש\"נ."],["5500","51","<b>והמתנשא מימות עולם</b>: ברכת יוצר אור."],["5501","52","<b>הכי</b>: אוצ\"ל: הכא."],["5502","53","<b>בראשית נמי מאמר הוא</b>: בראשית א, א. ר\"ה לב, א."],["5503","54","<b>ותרגומו בראשי' בחוכמתא</b>: בראשית א, א ובתרגום ירושלמי שם. ראה גם (לעיל בחלק המאמרים) המשך יונתי כאן הערה 478."],["5504","55","<b>בראשי'. . כללי. . לט' מאמרות</b>: ראה לקו\"ת בהר מא, ד. במדבר יב, סע\"ד ואילך. מאמרי אדה\"א דברים ח\"ב ע' תעז. וש\"נ. תו\"ח וארא ח\"א פא, ג ובהערה 634."],["5505","56","<b>לא כל מוחא סביל דא</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 45."]]],[2000480519,"כשעושה מלאכה אז מייגע ומזיע כל הכוחות ואח\"כ כששובת ממלאכתו אז ה\"ה השביתה בהכוחות פי' שביתה שלילה ער טוט ניט ששובתים הכוחות. וכן יובן למעלה ענין השביתה אף שלא בעמל ולא ביגיע' ברא הקב\"ה את עולמו<sup data-n=\"5506\">57</sup> כ\"א במאמר ורוח פיו, אך דיבורו של הקב\"ה חשיב מעשה<sup data-n=\"5507\">58</sup> ושייך שביתה, ובדיבור הזה מלובש המדות וגם המוחין מלובש כמו שנת' כי באמת מוכרח לומר שבדיבור יש ג\"כ מוחין כי מאחר שמגלה מוחין מוכרח לומר שיש בו מוחין ובאמת אנו רואים שבדיבור נמצא בו ג\"כ חכ' בפ\"ע כמו שאנו רואים שיש אחד שיודע השכל בטוב ואינו יכול להשפיע אותו לזולתו<sup data-n=\"5508\">59</sup> ע\"י דיבור וגם לעצמו אינו יכול להלבישו באותיו' הדיבור ולכאורה מה חסר אצלו הלא השכל יודע וה' מוצאות הפה יש אצלו אך זה חסר לו חכ' שבדיבור וע\"כ אינו יכול להלביש השכל באותיות אף שהם רק אותיו' שהם לבושים אך שרשן הוא בקדמות השכל<sup data-n=\"5509\">60</sup> שבהם וע\"י יומשך השכל ולמעלה אותיו' שרשם ברשימה שלא נגע בה הצמצום<sup data-n=\"5510\">61</sup> ע\"כ בכוחם להתגלות<sup data-n=\"5511\">62</sup> הארת הקו.\n<b>ועוד</b> אנו רואים מהתהוות העולמות אשר נתהווה מדיבור שנמצא בההתהוות חכמה נפלאה כמ\"ש אשר יצר את האדם בחכ'<sup data-n=\"5512\">63</sup>, וחוקרים כבר חקרו כי כמו באדם יש גידי הדם וגידי רוח כן נמצא בעלין<sup data-n=\"5513\">64</sup> צמחים<sup data-n=\"5514\">65</sup> גשמי', ואחר כל חקירתם עדיין לתכלית החכ' לא באו, ומאחר שאנו רואים בעולם שנתהווה מדיבור שנמצא בו חכ' מוכרח להיות שבדיבור המהוה יש בו ג\"כ ענין חכ' כמו שאנו מכירין מכלי שנפעלה בחכ' שהאומן הוא חכם כמו\"כ ע\"י מה רבו ומה גדלו<sup data-n=\"5515\">66</sup> מוכרח הוא שבמקור המהוה נמצא בו חכ' מובן מזה אשר גם חכמתו נתלבש בעשי', וכן גם הרצון שבו מלובש בעשי' כמ\"ש שוקיו עמודי שש שנשתוקק הקב\"ה לבראותו שגם התשוקה הוא מלובש. ובאמת נת' כי התהוות א\"א להיות מגרמוהי לחוד אלא שאיהו מוכרח להתייחד עם גרמוהי<sup data-n=\"5516\">67</sup>, שאיהו הוא בחי' עצמות א\"ס שלמעלה מקריאת שם הי' מלובש בעשי' וע\"כ כתי' הוי' בחכ' יסד ארץ הוי' עצמות א\"ס הוא יסד ארץ והחכ' הוא רק כמו צבת שע\"י נעשית המלאכה אך העיקר הוא",[["5506","57","<b>שלא בעמל. . את עולמו</b>: ראה ב\"ר פ\"ג, ב. ספ\"י."],["5507","58","<b>דיבורו. . חשיב מעשה</b>: ראה ב\"ר פמ\"ד, כב. רש\"י לך טו, יח."],["5508","59","<b>אחד שיודע השכל. . להשפיע אותו לזולתו</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 51 ואילך."],["5509","60","<b>אותיו'. . בקדמות השכל</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי בחגוי הסלע ובהערה 62."],["5510","61","<b>אותיו' שרשם ברשימה. . הצמצום</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"ו."],["5511","62","<b>להתגלות</b>: כ\"ה כהכת\"י."],["5512","63","<b>אשר יצר את האדם בחכ'</b>: ברכת אשר יצר. ראה גם ש\"א פג, א."],["5513","64","<b>וחוקרים. . גידי הדם וגידי הרוח. . בעלין</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 55."],["5514","65","<b>צמחים</b>: אוצ\"ל: וצמחים."],["5515","66","<b>מה רבו ומה גדלו</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערות 36. 42."],["5516","67","<b>התהוות. . מגרמוהי. . עם גרמוהי</b>: ראה לעיל הנחה ד\"ה יפה שעה אחת הא' ובהערה 72. ד\"ה אני לדודי הב' ובהערה 44."]]],[2000480520,"המפעיל והוא הוי', ומה שאנו חושבים רק מחכ' הוא מחמת כי השגתינו הוא רק מחכ' שהיא ראשית הגילוי אבל באמת הכל נתלבש בעשי' וזהו ששת ימים ואח\"כ בקידוש היום הי' השביתה פי' החזרת הכוחות לשרשן, אך כמו שאנו רואים באדם כשמדבר איזה שכל עמוק ואח\"כ כשפוסק מלדבר הלא רק מדיבור נפסק אבל במח' נשאר השכל אצלו כי גם לאחר שפסק מלדבר יכול לחשוב הפרטים מהשכל אם לא יבלבלו אותו ואם יבלבלו אותו אינו יכול לחשוב כלל מהשכל. כך יובן למעלה אף שבשבת הי' השביתה מהכוחות פי' הסתלקות הכוחות למקורן ושרשן אך הוא רק מדיבור נסתלק אבל לא ממחשבה ומשם נמשך חיות לעולמות ביום השבת<sup data-n=\"5517\">68</sup> שאם לא כן מאין שבת מקבל חיות מאחר שנסתלק הכוחות. לכן כתי' ויכל אלקי'<sup data-n=\"5518\">69</sup> שהי' השביתה ביום השביעי, קרא אותו יום השביעי, כי אצלינו שייך תוס' מחול על הקודש אבל הקב\"ה יודע עיתים ורגעים<sup data-n=\"5519\">70</sup> לכן אינו צריך תוס' מחול כו', וע\"כ בכל הימים כתי' ויהי ערב ויהי בוקר ובשבת לא כתי' ערב<sup data-n=\"5520\">71</sup> כי לא הי' בו לילה כמו שאי' במד\"ר ל\"ו שעות שמשה אותה אורה<sup data-n=\"5521\">72</sup> י\"ב דע\"ש וי\"ב דליל שבת וי\"ב דיום שבת, וע\"כ ר\"ה שהוא יום שישי למע\"ב נק' זה היום<sup data-n=\"5522\">73</sup>, ויהי היום<sup data-n=\"5523\">74</sup>, שהוא יום ארוך<sup data-n=\"5524\">75</sup>, ובשבת כתי' ויברך אותו<sup data-n=\"5525\">76</sup> ויקדש אותו<sup data-n=\"5526\">77</sup> וארז\"ל ברכו וקדשו<sup data-n=\"5527\">78</sup> כי כמו שאנו רואים למטה באדם בעת שעושה איזה מלאכה אז מייגע כל הכוחות לעשות אותה היטב ואזי אין לו תענוג מהכלי כי עדיין לא נשלם רצונו אך לאחר הגמר שעשה המלאכה כדבעי ושובת בכל הכוחות וראה שטוב הכלי שעשה אז מתענג ממנה, וכמו\"כ יובן למעלה אף כי אינו שייך תענוג למעלה כמו שאינו שייך יגיע' אך שלמעלה ענין ברכו וקדשו בירכו הו\"ע ברכה והמשכה שהו\"ע תוס' אורות שתוס' של הקב\"ה מרובה על העיקר<sup data-n=\"5528\">79</sup> וקדשו ממקום קדש ומובדל, ובדרך פרט נמשך הגילוים דעונג בג' סעודות דשבת, וזהו שבת אותי' תשב שבשבת הוא השבת והחזרת הכוחות למקורן ושרשן.",[["5517","68","<b>ממחשבה. . חיות. . השבת</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערות 382-383."],["5518","69","<b>ויכל אלקי'</b>: בראשית ב, ב."],["5519","70","<b>הקב\"ה יודע עתים ורגעים</b>: ראה ב\"ר פ\"י, ט. וראה גם לקו\"ש בראשית כרך ה ע' 24 ואילך."],["5520","71","<b>ויהי ערב ויהי בוקר ובשבת לא כתי' ערב</b>: בראשית א, ה. ח. יג. יט. כג. לא. ראה מדרש תהלים צב, ד."],["5521","72","<b>ל\"ו שעות שמשה אותה אורה</b>: ב\"ר פי\"א, ב. פי\"ב, ו. ירושלמי ברכות פ\"ח, ה\"ה."],["5522","73","<b>ר\"ה. . זה היום</b>: מוסף לר\"ה (ברכת זכרונות). ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 59."],["5523","74","<b>ר\"ה. . ויהי היום</b>: איוב א, ו. ב, א. ראה הנסמן בהערה שלפנ\"ז."],["5524","75","<b>ר\"ה. . יום ארוך</b>: ראה ביצה ד, ב וב(רש\"י) מפרשים שם. רמב\"ם הל' יו\"ט ספ\"א. הל' אבל ספ\"י. שו\"ע אדה\"ז הל' שבת סשצ\"ג, ס\"א. הל' יו\"ט סתצ\"ז, ס\"ט. סתק\"א, סי\"ח. סתק\"ג, ס\"ג. סתקי\"ג, ס\"ח. ס\"י. סתקט\"ו, ס\"ו. ס\"ט. סתקכ\"ז, סכ\"ב. הל' ר\"ה סתקצ\"ז, ס\"ה. סת\"ר, ס\"ג ואילך."],["5525","76","<b>ויברך אותו</b>: בראשית ב, ג [בהוספת תיבת אותו]."],["5526","77","<b>ויקדש אותו</b>: בראשית שם."],["5527","78","<b>ויברך. . ויקדש. . ברכו וקדשו</b>: ראה מכילתא יתרו כ, יא. ב\"ר פי\"א, ב."],["5528","79","<b>שתוס' של הקב\"ה. . העיקר</b>: ראה ב\"ר פס\"א, ד. לקו\"ש וישלח כרך ה ע' 422 הערה 3. ע' 423 הערה 10. סה\"מ תרל\"ח ע' מט. וש\"נ."]]],[2000480521,"<b>וכן</b> יובן בנפש ענין תשובה, כי הנה הנפש הוא חלק אלקה ממעל<sup data-n=\"5529\">80</sup> כי חלק הוי' עמו<sup data-n=\"5530\">81</sup>, וענין חלק הענין הוא כי אנו רואים למטה חלק א' ממספר מאה או מאלף, ולמעלה הו\"ע חלק הוי' הי' הוה ויהי' כאחד<sup data-n=\"5531\">82</sup> כך הנשמה הוא למעלה מהגבלה והגשמה ומה שאנו רואים למטה הוא רק כוחות הנפש אבל הנפש עצמה לא תוכל להתלבש בגוף כי מה מלאך בשליש עולם הוא עומד<sup data-n=\"5532\">83</sup> כש\"כ הנפש בודאי הגוף קטן מהכיל אותה ע\"כ לא התלבשה בגוף רק הארה מהנפש<sup data-n=\"5533\">84</sup> אבל עצם הנפש נק' יחידה שמקבלת מיחיד<sup data-n=\"5534\">85</sup> ועלי' כתי' כי הוי' אלקיך אש אוכלה הוא<sup data-n=\"5535\">86</sup> כמו האש בטבעו לעלות למעלה כך הנשמה היא משתוקקת להסתלק למעלה, ואפי' להתלבש בכוחות הנפש ה\"ה הגבלה אצלה וכש\"כ בכוחות הגוף, ומה שירדה הארה להתלבש בגוף הוא ירידה צורך עלי'<sup data-n=\"5536\">87</sup>, ותיכף כשעומד ולומד ומתפלל מרגיש רוממות בנפשו כי בתורה כתי' סלסלה ותרוממך<sup data-n=\"5537\">88</sup> ע\"י סלסל הלכות ורמינהו, לא קשה, ועי\"ז תרוממך שנתרומם הנפש וכמו\"כ כתי' וצדקה תרומם גוי<sup data-n=\"5538\">89</sup> כי ע\"י שנותן צדקה עי\"ז נעשה היד מרכבה למדת החסד שהוא א\"ס בלי גבול אף שהמדות הם מוגבלים אך ענין הגבלתם הו\"ע חסד ולא גבורה אבל עצם מדת החסד הוא חסד בלי גבול שא\"ס להתפשטותן וזהו\"ע רוממות, ולא דוקא צדקה כי כל המצות נקראים בש' צדקה כמ\"ש וצדקה תהי' לנו<sup data-n=\"5539\">90</sup> כי נשמור לעשות את כל המצוה הזאת, אך זהו רק רוממות, אבל עיקר העלי' הוא בשינה שאז הוא הסתלקות כל הכוחות דהנפש ונשאר בהגוף רק קושטא<sup data-n=\"5540\">91</sup> דחיותא<sup data-n=\"5541\">92</sup> והנפש עולה אז למעלה ושואבת לה חיים<sup data-n=\"5542\">93</sup> שזהו ע\"י התורה ומצות של כל היום כי בכלל הנפש הוא שליח ואף שחזקה ששליח עושה שליחותו<sup data-n=\"5543\">94</sup> אבל יש מונעים ומעכבים שזהו תשוקת היצה\"ר לקין וחביריו שהי' ראשית מעורר'",[["5529","80","<b>הנפש הוא חלק אלקה ממעל</b>: ראה איוב לא, ב. תניא רפ\"ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 395."],["5530","81","<b>כי חלק הוי' עמו</b>: האזינו לב, ט. ראה גם לעיל הנחה ד\"ה כמים הפנים סוף פיסקא א."],["5531","82","<b>הוי' הי' הוה ויהי' כאחד</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."],["5532","83","<b>מלאך בשליש עולם הוא עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול הערה 44."],["5533","84","<b>התלבשה בגוף רק הארה מהנפש</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 595."],["5534","85","<b>יחידה שמקבלת מיחיד</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. לקו\"ת פ' ראה כה, א. (לעיל בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 152."],["5535","86","<b>כי הוי' אלקיך אש אוכלה הוא</b>: ואתחנן ד, כד."],["5536","87","<b>ירידה צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["5537","88","<b>סלסלה ותרוממך</b>: משלי ד, ח. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"א ובהערה 221."],["5538","89","<b>וצדקה תרומם גוי</b>: משלי יד, לד [ושם צדקה — ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 66]."],["5539","90","<b>כל המצות. . צדקה. . וצדקה תהי' לנו</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי הערה 27."],["5540","91","<b>קושטא</b>: וכ\"ה גם לקמן הנחה ד\"ה כנשר יעיר קנו על יד הערה 94. אוצ\"ל: קיסטא."],["5541","92","<b>קיסטא דחיותא</b>: ראה גם (לעיל בחלק המאמרים) בההמשך כאן ובהערה 225."],["5542","93","<b>והנפש. . ושואבת לה חיים</b>: ראה לעיל שם הערה 490."],["5543","94","<b>שחזקה ששליח עושה שליחותו</b>: ערובין לא, ב."]]],[2000480522,"מדנים ובפרט ליכלוך שע\"י חטא ועון שנדחה ממחיצתו של הקב\"ה אבל כשגובר על המונעים ומעכבים אז יש כח להנפש כי עולה למעלה ושואף לה חיים ממקור החיים מקור התענוגים ואז נעשה למחרת ברי' חדשה לגמרי כי כמו בלעו\"ז<sup data-n=\"5544\">95</sup> אם תעזבני יום יומים אעזבך<sup data-n=\"5545\">96</sup> כן מצוה גוררת מצוה<sup data-n=\"5546\">97</sup> כי באמת שאם מבחין יום א' לקיים תורה ומצות כתיקונן ירגיש שלמחר יהי' באופן אחר היותר נעלה. וזהו כל ימיו בתשובה כי כל יום ויום ע\"י תומ\"צ ישיב הנפש לשאוף חיים ממקור החיים מקור התענוגים.\n<b>וכן</b> יובן ענין תשובה משמיטה הנה כתי' שש שנים תזרע כרמיך<sup data-n=\"5547\">98</sup> ובשנה השביעית תשמטנה ונטשתה<sup data-n=\"5548\">99</sup> שהוא ע\"ד מ\"ש ששת ימים תעבוד<sup data-n=\"5549\">100</sup> וביום השביעי תשבות שמפסוק זה מצינו היתר לעשות מלאכה כי בלא זה מה מאן דמחוי קמי' מלכא<sup data-n=\"5550\">101</sup> קטלא חייב כש\"כ לגבי מלך מלכי המלכים הקב\"ה<sup data-n=\"5551\">102</sup> שמלא כל הארץ כבודו<sup data-n=\"5552\">103</sup> ולית אתר פנוי מיני'<sup data-n=\"5553\">104</sup> ובפרט מלאכת חרישה וזריעה שבודאי הי' אסור רק מפסוק זה הורה לנו היתר. והוא מצד ב' טעמים, א' שלמלך בשר ודם הכל תופס מקום אבל קמי' ית' הכל כלא חשיב<sup data-n=\"5554\">105</sup>, ועוד כי למלך בשר ודם אנו רואים בעיני בשר אבל הקב\"ה אינו נראה ונגלה שהוא בהעלם אף שכתי' את השמים והארץ אני מלא<sup data-n=\"5555\">106</sup> אך שזהו רק בהעלם והיא הנותנת מפני שמאיר שם אני שהוא עצמות א\"ס הוא דוקא בהעלם. וע\"כ רשימה שלא נגע בה הצמצום הוא מקור כלים<sup data-n=\"5556\">107</sup> להעלים לכן ששת שנים תזרע שמותר בעשי' מלאכה ובשנה השביעית הוא שביתה מכח הצומח, ואף שהכוחות הם מלובשים בהארץ שהרי יש צמחים דשאים ועשבים מ\"מ מאי איכפת לנו כי העיקר המלאכה הוא העלאת מ\"ן שע\"י הגרעין, מה שנרקב בעפר הארץ מעלה אותו לכח הצומח, ובשנה השביעית אז הוא שביתה מהעלאות מ\"ן לכח הצומח, וכן יובל הוא במדריגה גבוה שהוא מד' שמיני<sup data-n=\"5557\">108</sup> ושם כתי' בפירוש תשובו",[["5544","95","<b>בלעו\"ז</b>: ראה גם סה\"מ תרל\"ח ס\"ע קלד."],["5545","96","<b>אם תעזבני יום יומים אעזבך</b>: ראה ירושלמי סוף ברכות. לקו\"ש עקב כרך ט ע' 267 (ובאג\"ק שלו ח\"א ע' קלח)."],["5546","97","<b>מצוה גוררת מצוה</b>: אבות פ\"ד מ\"ב."],["5547","98","<b>שש שנים תזרע כרמיך</b>: בהר כה, ג [ושם: ושש]. לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 79. וכן (בחלק המאמרים) בההמשך כאן על יד הערה 492 הובא ראשית הכתוב: שש שנים תזרע שדך."],["5548","99","<b>ובשנה השביעית תשמטנה ונטשתה</b>: משפטים כג, יא [ושם: והשביעית]. לעיל שם הובא הכתוב: ובשנה השביעית שבת שבתון — בהר כה, ד."],["5549","100","<b>ששת ימים תעבוד</b>: תשא לד, כא. ראה (לעיל בחלק המאמרים) המשך יונתי כאן ובהערה 494 [ושם הובא הכתוב: ששת ימים תעשה מעשיך — משפטים כג, יב]."],["5550","101","<b>מאן דמחוי קמי' מלכא</b>: ראה חגיגה ה, ב."],["5551","102","<b>מלך. . הקב\"ה</b>: ברכות כח, ב."],["5552","103","<b>שמלא כל הארץ כבודו</b>: ישעי' ו, ג."],["5553","104","<b>ולית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. לקו\"ת בהר מא, א. שם בהוספות נב, ג."],["5554","105","<b>קמי' ית' הכל כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["5555","106","<b>את השמים. . מלא</b>: ירמי' כג, כד [ושם ואת]. ראה תניא פמ\"ח. תו\"ח בשלח ח\"א קסו, ג. וש\"נ."],["5556","107","<b>רשימה. . מקור כלים</b>: ראה גם שעה\"י קל, א ובהנסמן במ\"מ לשם. לקמן הנחה ד\"ה כנשר יעיר קנו ובהערה 149."],["5557","108","<b>יובל. . מד' שמיני</b>: ראה גם לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 87. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1337."]]],[2000480523,"איש אל אחוזתו<sup data-n=\"5558\">109</sup> שהשדות חוזרות לבעליהן, שדה שקנה שמעון מראובן שהי' שלו לגמרי ומאחר שבא יובל חוזרת לראובן אשר זהו חזרה למקורו ושרשו. וזהו\"ע יפה שעה א' בתשובה ומעשים טובים בעוה\"ז, פי' תשובה היא חזרה וכשהתשובה היא תשובה גמורה אז עולה הנשמה למעלה ושואבת לה חיים אז הוכחה שהמעשים הם טובים.",[["5558","109","<b>תשובו איש אל אחוזתו</b>: בהר כה, יג."]]],[2000480524,"<h3>שובה ישראל הנחה א'</h3>\n<b></b><b>בס\"ד שב\"ת ש' תרמ\"א לד\"ה</b>\nשב\"ת\n<b>שובה</b> ישראל<sup data-n=\"5559\">1</sup> עד ה' אלקיך<sup data-n=\"5560\">2</sup>. הנה לכאורה צ\"ל מפני מה נא' שם מלא כי בכלל ה' ואלקים הוא שם מלא<sup data-n=\"5561\">3</sup>, הי' צריך ליכתוב עד ה' ולא יותר, מה שייך תשובה לשם מלא דוקא. להבין זאת הנה ארז\"ל במד\"ר פ' ויצא פ\"ע<sup data-n=\"5562\">4</sup> ע\"פ והי' ה' לי לאלקים<sup data-n=\"5563\">5</sup> אמר הקב\"ה<sup data-n=\"5564\">6</sup> אתה אמרת והי' לי לאלקי' חייך כל טובות וברכות ונחמות שאני נותן לבניך איני נותן אלא בלשון הזה שנא' והיה ביום ההוא יצא מים חיים מירושלים<sup data-n=\"5565\">7</sup>, והי' ביום ההוא יוסיף ה' שנית ידו<sup data-n=\"5566\">8</sup> כו', והי' ביום ההוא יטפו ההרים עסיס<sup data-n=\"5567\">9</sup>, והי' ביום ההוא יתקע בשופר גדול<sup data-n=\"5568\">10</sup>, לכאורה צ\"ל מהו\"ע לשון והי' גם מהו מעלת בשו\"ג הלא מצינו מעלה בקטן כמארז\"ל ע\"פ אחות לנו קטנה<sup data-n=\"5569\">11</sup> לע\"ל עתידין כל שרי אומות העולם באין ומקטרגין את ישראל לפני הקב\"ה ואומרין רבש\"ע אלו עבדו ע\"ז ואלו עבדו ע\"ז כו' מפני מה אלו יורדין לגיהנם ואלו אינן יורדין אמר להם הקב\"ה אחות לנו קטנה מה קטן זה כל מה שהוא עושה אין ממחין על ידו למה",[["5559","1","<b>שובה ישראל</b>: הנחה ממאמר כ\"ק אדמו\"ר מהר\"ש ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ.\nבהכותרת כאן נרשם: ”לד\"ה\" כנראה הכוונה ששייך לד\"ה (המשך) יונתי תר\"ם, כמ\"ש גם בסה\"מ תרמ\"ג ע' נב: ”וע' בד\"ה שובה (שנר' בקצרה) הוא בד\"ה יונתי מ\"ם\".\nהנחת אחרת מדרוש זה נדפסה לאחרי הנחה זו."],["5560","2","<b>שובה ישראל עד ה' אלקיך</b>: הושע יד, ב."],["5561","3","<b>ה' ואלקים הוא שם מלא</b>: ראה זהר בראשית מח, ב. מט, א. ועוד. לקו\"ת צו יא, ב. נצבים נא, ג."],["5562","4","<b>במד\"ר פ' ויצא פ\"ע</b>: סימן ו."],["5563","5","<b>והי' ה' לי לאלקים</b>: ויצא כח, כא."],["5564","6","<b>אמר הקב\"ה</b>: וכ\"ה לקמן בהנחה שני' כאן. במדרש שם: אמר לו הקב\"ה."],["5565","7","<b>והי' ביום ההוא יצא. . מירושלים</b>: זכרי' יד, ח[ednref_330_א]."],["5566","8","<b>והי' ביום ההוא יוסיף ה' שנית ידו</b>: ישעי' יא, יא."],["5567","9","<b>והי' ביום ההוא יטפו ההרים עסיס</b>: יואל ד, יח."],["5568","10","<b>והי' ביום ההוא יתקע בשופר גדול</b>: ישעי' כז, יג."],["5569","11","<b>אחות לנו קטנה</b>: שה\"ש ח, ח. ראה שהש\"ר שם. (לעיל בחלק המאמרים) בהמאמר כאן הערה 10.\n\n[edn_330_א] ושם ובמדרש וכן לקמן בפיסקא וזהו אתה ובסיום המאמר: יצאו, וכנראה שגם כאן צ\"ל כן."]]],[2000480525,"שהוא קטן כך כל מה שישראל מתלכלכין כל ימות השנה בעוונותיהן בא יוהכ\"פ ומכפר עליהם שנא' כי ביום הזה יכפר עליכם<sup data-n=\"5570\">12</sup> א\"כ אנו רואים שיש מעלה בקטן, וכן מצינו דוד הקטן<sup data-n=\"5571\">13</sup> שמואל הקטן<sup data-n=\"5572\">14</sup> ואפי' ביעקב כתי' מי יקום יעקב כי קטן הוא<sup data-n=\"5573\">15</sup>, וכן אפי' למעלה אנו מצינו שארז\"ל צמצם שכינתו בשני בדי הארון<sup data-n=\"5574\">16</sup> שכל הגילוים שהי' בבהמ\"ק ונועדתי אליך שמה<sup data-n=\"5575\">17</sup> על הכפורת שהי' גילוי אלקות וזה הי' ע\"י הצמצום, א\"כ יש מעלה בקטן ולמה נאמר על לע\"ל שיהי' בשופר גדול. והנה ארז\"ל הרואה שופר בחלום<sup data-n=\"5576\">18</sup> מצפה<sup data-n=\"5577\">19</sup> לישועה שנא' והי' ביום ההוא יתקע בשופר גדול, לכאורה צ\"ל הלא הרואה שופר בחלום היינו סתם שופר א\"כ איך יצפה לישועה הלא בישועה נאמר שופר גדול כו'.\n<b>להבין</b> זאת צ\"ל תחלה הנה איתא בילקוט<sup data-n=\"5578\">20</sup> בשם פדר\"א<sup data-n=\"5579\">21</sup> שמאיל של יצחק<sup data-n=\"5580\">22</sup> לא יצא ממנו דבר לבטלה האפר של איל אילו<sup data-n=\"5581\">24</sup> האפר של יסוד מזבח הפנימי<sup data-n=\"5582\">23</sup>, גידין של איל אלו עשרה נבלים של כנור שהי' דוד מנגן<sup data-n=\"5583\">25</sup> בהן, עורו של איל הי' אזור מתניו של אליהו כי אליהו הי' חגור באזור ואזור שלו הי' מעור<sup data-n=\"5584\">26</sup> של איל של יצחק, קרניו של איל שמאלו שתקע בו בהר סיני ויהי קול השופר<sup data-n=\"5585\">28</sup> משה ידבר והאלקים יעננו בקול<sup data-n=\"5586\">29</sup>, קרנו של ימין<sup data-n=\"5587\">27</sup> שהוא גדול משמאלו שהוא עתיד לתקוע בו לע\"ל שנאמר והי' ביום ההוא יתקע בשופר גדול, לכאורה הלא ענין השופר הוא צעקה פנימי' לא\"ס<sup data-n=\"5588\">30</sup> עצמותו ושם אינו שייך ימין ושמאל כי לית",[["5570","12","<b>כי ביום הזה יכפר עליכם</b>: אחרי טז, ל."],["5571","13","<b>דוד הקטן</b>: חולין ס, ב. שמואל-א יז, יד (ושם: ודוד הוא הקטן). ראה מאמרי אדה\"ז על פרשיות התורה ח\"א בהוספות ע' 21. מאמרי אדה\"א בראשית ע' רצז. סה\"מ תר\"ל ס\"ע שו."],["5572","14","<b>שמואל הקטן</b>: חולין שם. ראה סה\"מ תר\"ל שם. סדה\"ד חלק תנו\"א בערכו."],["5573","15","<b>מי יקום יעקב כי קטן הוא</b>: באוה\"ת חנוכה ח\"ב ע' 596 מציין: עמוס ז, ה. מכות כד, סע\"א. ראה חולין וסה\"מ תר\"ל שם. (לעיל בחלק המאמרים) מאמר ד\"ה רני ושמחי על יד הערה 122 ואילך."],["5574","16","<b>צמצם שכינתו. . הארון</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). לקו\"ת אמור לד, ב. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12."],["5575","17","<b>ונועדתי אליך שמה</b>: ע\"פ תרומה כה, כב."],["5576","18","<b>הרואה שופר בחלום מצפה לישועה</b>: ילקוט שמעוני ישעי' כז, יג (רמז תלו). ראה (לעיל בחלק המאמרים) בהמאמר כאן הערות 21-22."],["5577","19","<b>מצפה</b>: אוצ\"ל: יצפה. וכ\"ה בסמוך בפנים."],["5578","20","<b>איתא בילקוט</b>: שמעוני מלכים-ב א, ח (רמז רכד) — בשינויים. וראה גם ילקו\"ש וירא כב, יג (רמז קא). ישעי' כז, יג (רמז תלו)."],["5579","21","<b>פדר\"א</b>: ספל\"א."],["5580","22","<b>שמאיל של יצחק</b>: הלשון — ראה פדר\"א רפי\"ט. תויו\"ט אבות פ\"ה, מ\"ו."],["5581","24","<b>אילו</b>: אולי תיבה זו מיותרת."],["5582","23","<b>האפר של איל. . יסוד מזבח הפנימי</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 14."],["5583","25","<b>עשרה נבלים של כנור שהי' דוד מנגן</b>: ראה גם לקמן על יד הערה 155: עשרה כנורות של דוד. הגהת הרד\"ל בפרקי דר\"א פי\"ט אות כג. ספל\"א כאן אות עג."],["5584","26","<b>אליהו. . באזור. . מעור</b>: מלכים-ב א, ח."],["5585","28","<b>ויהי קול השופר</b>: יתרו יט, יט [בדילוג]."],["5586","29","<b>משה ידבר. . בקול</b>: בפדר\"א ובילקוט כאן ליתא. ראה גם לקמן בהנחה שני' כאן הערה 33."],["5587","27","<b>קרניו של איל שמאלו. . ימין</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 16."],["5588","30","<b>לא\"ס</b>: בהנחה זו כותב לאו\"ס או לאי\"ס ותוקן כאן וכן להלן — ע\"י המו\"ל — לא\"ס."]]],[2000480526,"שמאלא בהאי עתיקא<sup data-n=\"5589\">31</sup> וכמ\"ש ימינך ה' נאדרי בכח ימינך ה' תרעץ אויב<sup data-n=\"5590\">32</sup> א\"כ איך שייך שם ימין ושמאל. עוד הובא בילקוט<sup data-n=\"5591\">33</sup> בשם הפדר\"א<sup data-n=\"5592\">34</sup> שאותו איל נברא בין השמשות וכן משמע מהמשנה וי\"א אף אילו של יצחק<sup data-n=\"5593\">35</sup>, בשעה שנעקד יצחק על גבי המזבח אותו איל הי' רץ ובא להתקרב תחת יצחק הי' סט\"א<sup data-n=\"5594\">36</sup> סובכו ומערבבו באילנות כמ\"ש והנה איל אחר נאחז בסבך בקרניו<sup data-n=\"5595\">37</sup> שהי' נעקר מאילן זה ואוחז אותו באילן אחר מה עשה אותו איל פשט את ידו ואת רגלו בטליתו של א\"א והביט אחריו וראה את האיל והתירו והקריבו, וזה אינו מובן כלל מהו\"ע שפשט ידו בטליתו של א\"א. גם צ\"ל הנה כתי' מי אל כמוך נושא עון ועובר על פשע לשארית נחלתו<sup data-n=\"5596\">38</sup> וארז\"ל למי נושא עון כו' למי שמשים א\"ע כשיריים<sup data-n=\"5597\">39</sup> לכאורה צ\"ל כיון שנושא עון א\"כ אין שייך שם דקדוקים א\"כ מפני מה דוקא לשארית למי שמשים א\"ע כשיריים הלא שם אינו שייך דקדוקים כו'.\n<b>להבין</b> כל הנ\"ל, הנה ענין קטן<sup data-n=\"5598\">40</sup> הוא מדתו של יעקב בריח התיכון המבריח מן הקצה אל הקצה<sup data-n=\"5599\">41</sup>, כיון שנק' קצה וקצה זהו בבחי' סדר השתל', אך הנה יש מעלה בבחי' קטן כי כאשר האדם מחשב לדבר<sup data-n=\"5600\">42</sup> חשוב אז מדקדקים עליו אבל אם אינו מחשב לדבר שהוא אין שום משמע, אז אין מדקדקים עליו, א\"כ זהו מעלה מה שהוא קטן בעיניו, אך זהו בסדר השתל' אבל לגבי א\"ס שלמעלה מסדר השתל' כיון שיש קצה וקצה זהו בחי' הגבלה ע\"כ נק' קטן ששם אינו תופס מקום ע\"כ כתי' אני ה' לא שניתי<sup data-n=\"5601\">43</sup> אתה הוא קודם שנבה\"ע<sup data-n=\"5602\">44</sup> ואתה הוא לאחר שנבה\"ע שאין בו שום שינוי. לכאורה הלא תחלה לא הי' התהוות העולמות ואח\"כ נתהווה א\"כ איך אין בו שום שינוי מזה שנתהווה. אך מפני שכלליות התהוות הוא רק מהארה בעלמא שאינו נוגע לעצמות, ואפי' עולמות עליונים כיון שנושא ע\"ע שם עולם שעולם הוא לשון העלם<sup data-n=\"5603\">45</sup> הוא רק מהארה בעלמא שאינו נוגע לעצמות, ע\"כ נק' קטן.",[["5589","31","<b>לית שמאלא בהאי עתיקא</b>: ראה זהר אד\"ר נשא קכט, א. ע\"ח שער עתיק שי\"ב, פ\"ב. שער הארת המוחין של\"ב, פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתעא."],["5590","32","<b>ימינך ה'. . תרעץ אויב</b>: בשלח טו, ו."],["5591","33","<b>הובא בילקוט</b>: שמעוני הנ\"ל, וירא כב, יג (רמז קא) לפנ\"ז — בשינויים. לקמן בהנחה שני' ו(לעיל בחלק המאמרים) בהמאמר כאן לא צויין לילקוט."],["5592","34","<b>הפדר\"א</b>: שם לפנ\"ז ספל\"א — בשינויים."],["5593","35","<b>וי\"א אף אילו של יצחק</b>: ראה אבות פ\"ה, מ\"ו ובתויו\"ט שם."],["5594","36","<b>סט\"א</b>: לקמן בהנחה שני' ובילקוט: סמאל."],["5595","37","<b>והנה איל אחר נאחז בסבך בקרניו</b>: וירא כב, יג."],["5596","38","<b>מי אל כמוך. . לשארית נחלתו</b>: מיכה ז, יח. לקמן בהנחה שני' בא זה בסיום פיסקא ראשונה."],["5597","39","<b>למי נושא עון. . א\"ע כשיריים</b>: ר\"ה יז, סע\"א ואילך."],["5598","40","<b>קטן. . אל הקצה</b>: ראה גם תו\"א וישב כט, ד."],["5599","41","<b>יעקב בריח. . אל הקצה</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["5600","42","<b>מחשב לדבר</b>: אצ\"ל: מחשב עצמו לדבר."],["5601","43","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 29."],["5602","44","<b>אתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["5603","45","<b>שעולם הוא לשון העלם</b>: ראה ספר הבהיר ס\"י. תו\"ח שמות ח\"א יח, ד הערה 783."]]],[2000480527,"<b>אבל</b> ענין השופר היינו מן המיצר<sup data-n=\"5604\">46</sup> קראתי י\"ה ענני במרחב י\"ה שבמיצר יומשך המרחב וזהו\"ע במרחב י\"ה פי' יו\"ד הוא בעצם בחי' צמצום<sup data-n=\"5605\">47</sup> וצריך להמשיך בצמצום דיו\"ד שיומשך המרחב כי שופר הו\"ע תשובה<sup data-n=\"5606\">48</sup> אך לא על תשובה כפשוטו לבד שאם אנו אומרים שהוא על תשובה לבד א\"כ יש פתח ומבוא בתורה על חטא ועון אלא ששופר אינו על תשובה לבד כמו שנת\"ל שתשובה הוא לאו דוקא על חטא ועון שאם לאו יהי' פתח ומקום על חטא ועון<sup data-n=\"5607\">49</sup> אלא שאם פגם במעשה ובדיבור או במחשבה צריך תשובה על החטא שפגם ואם לא פגם צריך ג\"כ תשובה, דהיינו ענין החזרה<sup data-n=\"5608\">50</sup> פי' החזרת הנפש למקורו ושרשו כמ\"ש והרוח תשוב לאלקי' אשר נתנו<sup data-n=\"5609\">51</sup>, עי\"ז נמשך מלמעלה בחי' ונתתי רוחי בכם וחייתם<sup data-n=\"5610\">52</sup>, א\"כ יש עוד פי' בתשובה לשון החזרה, כך ענין שופר הוא לאו דוקא על תשובה לבד ועיקר הזכרון הוא ע\"י תקיעה כמ\"ש בהרמב\"ן שעיקר הזכרון הוא ע\"י תקיעה<sup data-n=\"5611\">53</sup> וש\"ת הוא מצד הספק<sup data-n=\"5612\">54</sup>.\n<b>וכמו</b> שבכל יום קודם השינה צריך האדם לעשות חשבון בנפשו<sup data-n=\"5613\">55</sup> שצריך לחזור הנפש למקורו ושרשו וצריך שיהי' נקי שזהו פקדון בידך אפקיד רוחי<sup data-n=\"5614\">56</sup> וכמו כאשר מחזירים פקדון צריך להחזיר שיהי' נקי מכל דבר כך הנשמה הוא בחי' פקדון וצריך להחזיר הפקדון שיהי' נקי מכל לכלוך וסיג וזהו שבידך אפקיד רוחי ר\"ת באר<sup data-n=\"5615\">57</sup> כמו שהבאר הוא נביעה מתתא לעילא כך הנשמה תמיד יש לה דביקות בא\"ס לדבקה בו, כך בכלליות השנה ר\"ה הוא החזרת החיות משנה העברה<sup data-n=\"5616\">58</sup> שהחיות הוא שליח וצריך השליח להביא מה שעשה בכל השנה בקיום התומ\"צ שזהו עיקר הכוונה, כמ\"ש אנכי עשיתי ארץ<sup data-n=\"5617\">59</sup> ואדם עלי' בראתי, פי' בראתי גימט' תרי\"ג<sup data-n=\"5618\">60</sup>, א\"כ כמו שבכל יום צריך שיהי' החזרה נקי מכל לכלוך מכ\"ש בר\"ה בודאי צ\"ל שיהי' החזרה נקי מכל לכלוך וזהו\"ע שופר שהו\"ע תשובה כי יש פי' תשובה לשון החזרה",[["5604","46","<b>מן המיצר</b>: תהלים קיח, ה."],["5605","47","<b>יו\"ד. . צמצום</b>: ראה גם אגה\"ת פ\"ד. תו\"ח בשלח ח\"א קס, ב."],["5606","48","<b>שופר הו\"ע תשובה</b>: ראה רמב\"ם הל' תשובה פ\"ג, ה\"ד."],["5607","49","<b>שנת\"ל שתשובה. . פתח. . חטא ועון</b>: ראה לעיל הנחה ד\"ה יפה שעה אחת הב' על יד הערה 21 ואילך."],["5608","50","<b>תשובה. . החזרה</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 454."],["5609","51","<b>והרוח תשוב לאלקי' אשר נתנו</b>: קהלת יב ז[ednref_331_ב]."],["5610","52","<b>ונתתי רוחי בכם וחייתם</b>: יחזקאל לז, יד."],["5611","53","<b>כמ\"ש בהרמב\"ן שעיקר הזכרון הוא ע\"י תקיעה</b>: ראה גם בהנחה שני' כאן."],["5612","54","<b>וש\"ת הוא מצד הספק</b>: ראה הלשון בהנחה שני' כאן."],["5613","55","<b>קדם השינה. . חשבון בנפשו</b>: ראה זהר קרח קעח, א. (לעיל בחלק המאמרים) המשך יונתי פכ\"ב ובהערה 549."],["5614","56","<b>בידך אפקיד רוחי</b>: תהלים לא, ו."],["5615","57","<b>שבידך אפקיד רוחי ר\"ת באר</b>: ראה פע\"ח שער ק\"ש שעהמ\"ט שט\"ז, פ\"ב. פ\"י. (לעיל בחלק המאמרים) המשך יונתי ובהערה 489."],["5616","58","<b>ר\"ה. . החיות משנה העברה</b>: ראה גם לקמן הנחה ד\"ה כנשר יעיר קנו ובהערה 101."],["5617","59","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב."],["5618","60","<b>בראתי גימט' תרי\"ג</b>: ראה רמ\"ז לזהר ויגש רה, ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1688.\n\n[edn_331_ב] ושם: אל האלקים. . נתנה — ראה גם לקמן סוף פיסקא ועפי\"ז. (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה אחת הב' ובהערה 25."]]],[2000480528,"והרוח תשוב, אך אם פגם שחטא צריך תשובה על החטא כי ענין החטא היינו חסרון<sup data-n=\"5619\">61</sup>, כאשר עשה חסרון קצת היינו חטא כמו פגימה בסכין כאשר יש בסכין כמו אחיזת הצפורן שבאותו מקום אינו חלק זהו פגימה כי הסכין צ\"ל חד וחלק<sup data-n=\"5620\">62</sup> כך חסרון קצת זהו חטא כמ\"ש קולע אל השערה ולא יחטא<sup data-n=\"5621\">63</sup>, פי' ולא יחטא שאינו חסר שחטא הוא לשון חסרון<sup data-n=\"5622\">64</sup> וכמו הייתי אני ובני שלמה חטאים<sup data-n=\"5623\">65</sup>, פרש\"י כלומר חסרים<sup data-n=\"5624\">66</sup>, שחטא הוא לשון חסרון ע\"כ כאשר יש חסרון דק צריך ג\"כ תשובה ע\"ז כי האדם הוא עולם קטן כמבואר באדר\"נ<sup data-n=\"5625\">67</sup> כל מה שיש בעולם יש באדם ברא יערות בעולם ברא שערות באדם, ע\"כ כמו שהאדם צריך לעשות תשובה בכל יום כן בכלליות יום<sup data-n=\"5626\">68</sup> העולם צריך ג\"כ לעשות תשובה, וכמו\"כ בר\"ה שאז הדין<sup data-n=\"5627\">69</sup> בכללית העולם צריך שיהי' נקי מכל לכלוך ע\"כ צריך לעשות תשובה, אך אם לא פגם צריך ג\"כ תשובה היינו החזרה שצריך להחזיר החיות משנה העברה שאפי' צדיק גמור צריך תשובה<sup data-n=\"5628\">70</sup> אם אפי' אין לו שום חטא כמו אפי' הרהור עבירה ג\"כ לא נמצא אצלו כי הרהורי עבירה קשה מעבירה<sup data-n=\"5629\">71</sup> כי הרהור מלפפתו<sup data-n=\"5630\">72</sup> כי ע\"י הרהור יטמא הרצון ורצון שולט ומושל על כל כחות הנפש א\"כ כאשר מטמא הרצון מגיע לכל הכחות הנפש ע\"כ הרהורי עבירה קשה מעבירה, וצ\"ג שאין לו אפי' הרהור ג\"כ מ\"מ צריך לתשובה היינו החזרת הנפש למקורו ושרשו, ע\"כ אפי' צ\"ג צריך לומר על חטא<sup data-n=\"5631\">73</sup> הגם שלכאורה אנו אומרים בעל חטא דברים שלא נמצא אצל צדיק, אך כד דייקת בי' שפיר ימצא כל הדברים אלו בדקות אפי' אצל צ\"ג ע\"כ הוא אומר על חטא כו'.\n<b>א\"כ</b> יש בתשובה שני פי' אך שתלוי באיזה ענין היינו אם פגם צריך תשובה על החטא ולא תשובה תתאה אלא תשובה עילאה, והיינו תורה שתורה היא",[["5619","61","<b>החטא היינו חסרון</b>: נסמן בסמוך הערה 64."],["5620","62","<b>הסכין צ\"ל חד וחלק</b>: ראה שו\"ת אדה\"ז ס\"ז (קה\"ת תשמ\"ח) ובהנסמן שם. שם ע' 269. ע' 329 ואילך. ע' 331 ואילך. ע' 428 ואילך. אהל יצחק הלכה למעשה סי\"א, ס\"ו. דרכי תשובה סי\"ח, ס\"מ."],["5621","63","<b>קולע אל השערה ולא יחטא</b>: ס' שופטים כ, טז [בדילוג]."],["5622","64","<b>שחטא הוא לשון חסרון</b>: ראה לקו\"ת מטות פב, א. נצבים נא, א. מאמרי אדה\"א דברים ח\"ג ע' תתקיד. נ\"ך ע' נא. סה\"מ תרל\"ב ח\"א ע' קמד. המשך תער\"ב ח\"ג ע' א'תנט. סה\"מ מלוקט א' ע' רצב. שם ב' ע' קכח ובהנסמן בהנ\"ל."],["5623","65","<b>הייתי אני ובני שלמה חטאים</b>: מלכים-א א, כא [ושם: והייתי]."],["5624","66","<b>פרש\"י כלומר חסרים</b>: וכ\"ה בהנחה שני' כאן־ לעיל הנחה ד\"ה יפה שעה אחת הב' על יד הערה 29. סה\"מ תרל\"ב ח\"ב ע' תקפד — תיבת כלומר לא הובא ברש\"י שם."],["5625","67","<b>האדם הוא עולם קטן כמבואר באדר\"נ</b>: ראה שם פל\"א, ג. ראה גם ראה בחיי בראשית א, לא (ריש ע' נ) בשם חכמי המחקר. תנחומא פקודי ג. מאמרי אדה\"א הנחות תקע\"ז ע' צח. וש\"נ."],["5626","68","<b>יום</b>: תיבה זו אינו ברורה כ\"כ בהכת\"י."],["5627","69","<b>בר\"ה שאז הדין</b>: ראה ר\"ה ח, סע\"א. טז, א-ב."],["5628","70","<b>צדיק גמור צריך תשובה</b>: ראה גם לקמן הנחה ד\"ה כנשר יעיר קנו ובהערה 106."],["5629","71","<b>הרהורי עבירה קשה מעבירה</b>: ראה יומא כט, א. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 381."],["5630","72","<b>הרהור מלפפתו</b>: ראה סוטה ג, ב. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה תעשה לי פיסקא והנה כמו."],["5631","73","<b>צ\"ג. . על חטא</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 590."]]],[2000480529,"תשו\"ע וכמו שמבואר בכהאריז\"ל כאשר מנדנד שינה לילה א'<sup data-n=\"5632\">74</sup> בשבוע<sup data-n=\"5633\">75</sup> ע\"י לימוד התורה אז לוקחים ענין כרת, ובתנא דב\"א נא' הי' רגיל ללמוד<sup data-n=\"5634\">76</sup> דף א' ילמוד שני דפים פרק א' ילמוד שני פרקים ועי\"ז לוקחים ענין כרת שהו\"ע תשו\"ע, אך על פגם קטן די בתפלה לבד, אך אם לא פגם ע\"י חטא ועון צריך ג\"כ תשובה הו\"ע החזרת הנפש והרוח תשוב כו'. א\"כ יש תשובה על חטא ועון, ואם לא פגם צריך ג\"כ תשובה היינו החזרה למקורה ושרשה. והיינו כמו עד\"מ אנו רואים באדם שיש צעקה באדם שצועק מפני שיש לו ריבוי מכאובים וחולאים ע\"כ הוא צועק מפני הכאב שיש לו, ויש אדם שצועק שרוצה בדבר טוב, כך יובן ברוחני' יש צעקה של צדיק גמור דהיינו כמו אהבת הבן אל האב שמשתוקק לאב כך הנה כתיב חי ה' אשר עמדתי לפניו<sup data-n=\"5635\">77</sup> שהנשמה עמדה למעלה באהוי\"ר וירדה בגוף ונה\"ב לבד שהגוף הוא מונע ומעכב באם אפי' בא לאהוי\"ר אינו בערך אהוי\"ר שלמטה לגבי אהוי\"ר שלמעלה וע\"ז כתי' יש מפזר ונוסף עוד<sup data-n=\"5636\">78</sup> כמו שהסוחר הוא מפזר ממון<sup data-n=\"5637\">79</sup> בשביל להרויח כסף וזהב היינו אהוי\"ר<sup data-n=\"5638\">80</sup> והנשמה מפזר האוי\"ר שהי' לה למעלה בשביל שע\"י ירידה אפשר לבוא לאשתאבא בגופא דמלכא<sup data-n=\"5639\">81</sup> וזהו\"ע תשובת הצדיקים, אבל כאשר פגם וחטא שנעשה אצלו ריבוי פגמים מכף רגל ועד ראש<sup data-n=\"5640\">82</sup> אין בו מתום פצע וחבורה נעשה אצלו צעקה מזה שפגם כמו עד\"מ חולה כאשר מרגיש כאב הוא צועק בקול רם, לכאורה מה הועיל לו הצעקה אלא שהצעקה הוא מצד עצמו בלא הבחנה, כך כאשר יש לו פגמי' נעשה אצלו צעקה, וזהו\"ע צעקת שופר שיש צעקה מצד הפגמי' ויש צעקה מצד שרוצה לחזור הנפש למקורה ושרשה.\n<b>והנה</b> שופר הוא מקרן של איל<sup data-n=\"5641\">83</sup> שהו\"ע אדם ובהמה תושיע ה'<sup data-n=\"5642\">84</sup> שהתקיעה הוא ע\"י אדם ושופר של בהמה ע\"כ הו\"ע אדם ובהמה תושיע ה' וארז\"ל ערומים בדעת כאדם<sup data-n=\"5643\">85</sup> ונמשכים אחריך כבהמה ופרש\"י ערומים בדעת כאדה\"ר, לכאורה צ\"ל הלא אדם הוא בחי' חכמה כמ\"ש ויהי האדם לנפש חי' ות\"א לרוח ממללא<sup data-n=\"5644\">87</sup> שהוא",[["5632","74","<b>שמבואר בכהאריז\"ל. . שינה לילה א'. . כרת</b>: ראה גם בהנחה שני' כאן ובהערה 77."],["5633","75","<b>לילה א' בשבוע</b>: כ\"ה גם בהנחה שני' כאן על יד הערה 78."],["5634","76","<b>ובתנא דב\"א. . רגיל ללמוד</b>: בקיצורים והערות לתניא ס\"ע לט מציין: ע' ויקרא רבה פכ\"ה ע\"ש. ראה לקו\"ש אגה\"ת כרך טל ע' 111 ואילך ובהערה 1 והערה 15 שם. לקמן הנחה ד\"ה כנשר יעיר קנו ובהערה 133."],["5635","77","<b>חי ה' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי ובהערה 60."],["5636","78","<b>יש מפזר ונוסף עוד</b>: משלי יא, כד. ראה גם מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' נט ואילך."],["5637","79","<b>כמו שהסוחר הוא מפזר ממון</b>: ראה גם תו\"א וישב כו, ג."],["5638","80","<b>כסף וזהב היינו אהוי\"ר</b>: תו\"א וישב כו, ד. תו\"ח וישב קצט, א."],["5639","81","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 51."],["5640","82","<b>מכף רגל ועד ראש</b>: ישעי' א, ו."],["5641","83","<b>שופר הוא מקרן של איל</b>: ראה ר\"ה טז, א. מאמרי אדה\"א דברים ח\"ג ע' תתצז. וש\"נ."],["5642","84","<b>אדם ובהמה תושיע הוי'</b>: תהלים לו, ז."],["5643","85","<b>ערומים בדעת כאדם</b>: ראה חולין ה, ב (וברש\"י שם־ ובתהלים שם). לקו\"ת בחוקותי נ, רע\"ג."],["5644","87","<b>ויהי. . ות\"א לרוח ממללא</b>: כ\"ז ליתא בהנחה שני' כאן, ובמקומו מביא ויפח באפיו נשמת חיים ע\"ש."]]],[2000480530,"בחי' חכמה<sup data-n=\"5645\">86</sup> ויש ראש וראשון וראשית ואדה\"ר כולל כל הבחי' אלו והיינו בחי' ח\"ס דא\"א<sup data-n=\"5646\">88</sup> א\"כ הוא רחוק מבהמה ואיך משימים א\"ע כבהמה הלא בהמה אינו אדם כו', אלא צ\"ל שיש מעלה בבהמה כו' וצ\"ל מהו המעלה של משימים א\"ע כבהמה. הנה כתיב<sup data-n=\"5647\">89</sup> לעולם יהי אדם ערום ביראה<sup data-n=\"5648\">90</sup> משמע שיראה לבד אינו מספיק אלא שצריך ערמומית ליראה כמ\"ש אני חכמה שכנתי ערמה<sup data-n=\"5649\">91</sup> כמו השכן אינו בערך לגבי הבית ובעה\"ב, כך חכמה לגבי ערמה שהוא רק שכן לגבי ערמה כי ענין החכמה ארז\"ל איזה חכם הרואה את הנולד<sup data-n=\"5650\">92</sup> פי' שרואה מה שיהי' בכמה שנים או במאות שנים וחבירו אינו יודע מה שיהי' והוא מגיד לו א\"כ ענין הדיבור לא שהוא חכמה אלא שע\"י הדיבור נעשה גילוי העלם החכמה שמגלה לו גילוי חכמתו ע\"י הדיבור. אך א\"ל<sup data-n=\"5651\">93</sup> שהדיבור הוא חכמה כמארז\"ל לא קאים אינש אדעתי' דרבי'<sup data-n=\"5652\">94</sup> עד ארבעין שנין משמע שאחר ארבעין שנין קאים וזהו ע\"י הדיבור מוכרח לומר שדיבור הוא חכמה כו', וענין ערום היינו שמסתיר הענין שלא יודעו וסילק הענין שלא יבין חבירו עד שמסבב ומוליך לרצונו ולוכד את חבירו, ובאמת זהו אסור ע\"פ התורה ששורש נמשך<sup data-n=\"5653\">95</sup> מהנחש הי' ערום<sup data-n=\"5654\">96</sup>, שהנחש הי' ערום הי' חכם בודאי והי' יודע מה שאסור ומה שמותר אלא שהלך בערמומית ע\"כ אמר אף כי אמר אלקים<sup data-n=\"5655\">97</sup> לא תאכלו מכל עץ הגן שהגם שידע שלא כל הדברים אסרו מ\"מ שאל כן מפני שהלך בערמומית ששאל תחלה אפי' על דברים המותרים עד שנסע<sup data-n=\"5656\">98</sup> לדברים האסורים וזהו ערמומית דלעו\"ז, וכן יש ערמומית דקדושה בא אחיך במרמה<sup data-n=\"5657\">99</sup> ויקח ברכתיך, ויעקביני זה פעמים<sup data-n=\"5658\">100</sup>, שלא הי' ביכולתו ליקח את הברכות אם לא ע\"י ערמומית<sup data-n=\"5659\">101</sup>, וזהו ערמומית דקדושה, ע\"כ צריך אדם להיות ערום ביראה שצריך ערמומית ליראה והיינו ערמומי' דקדושה.",[["5645","86","<b>ויהי האדם לנפש חי'. . חכמה</b>: בראשית ב, ז. ראה תו\"א מקץ מב, ריש ע\"ב. סידור שער החנוכה ערב, סע\"א ואילך. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרה. שעה\"י קמד, א ובהערה 8."],["5646","88","<b>ראש וראשון וראשית ואדה\"ר. . ח\"ס דא\"א</b>: ראה גם לקמן פיסקא אך כדי. בהנחה שני' כאן."],["5647","89","<b>הנה כתיב</b>: בהנחה שני' כאן: הנה ארז\"ל."],["5648","90","<b>לעולם יהי אדם ערום ביראה</b>: ברכות יז, א [ושם: יהא — וכ\"ה בהנחה שני' כאן]."],["5649","91","<b>אני חכמה שכנתי ערמה</b>: משלי ח, יב. ראה גם בהנחה שני' כאן (על יד הערה 100) בשם הזהר. סה\"מ תרל\"ב ח\"א ע' קצג. ח\"ב ע' תקסד."],["5650","92","<b>איזה חכם הרואה את הנולד</b>: ראה תמיד לב, א."],["5651","93","<b>א\"ל</b>: אפשר לומר."],["5652","94","<b>לא קאים אינש אדעתי' דרבי'</b>: ראה ע\"ז ה, ב. (לעיל בחלק המאמרים) מאמר ד\"ה וכל שיח השדה ספ\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. תו\"ח בשלח ח\"א ריז, ג הערה 418. המשך וככה תרל\"ז ספל\"ה."],["5653","95","<b>ששרש נמשך</b>: אוצ\"ל: ששרש הערמה נמשך."],["5654","96","<b>מהנחש הי' ערום</b>: בראשית ג, א."],["5655","97","<b>אף כי אמר אלקים</b>: בראשית שם."],["5656","98","<b>שנסע</b>: כ\"ה בהכת\"י."],["5657","99","<b>בא אחיך במרמה</b>: תולדות כז, לה. ראה גם סה\"מ ליקוט ח\"ג ע' קפה."],["5658","100","<b>ויעקביני זה פעמים</b>: תולדות שם, לו."],["5659","101","<b>הברכות. . ע\"י ערמומית</b>: ראה גם מאמרי אדה\"ז תקס\"ד ע' קפב ואילך. אוה\"ת בלק כרך ה[ednref_332_ג] ע' א'תרע ואילך. מטות ע' א'שמג. לקו\"ש תולדות ח\"א ס\"ע 55 ואילך. וש\"נ.\n\n[edn_332_ג] במהדורת תשנ\"ח ע' א'יד ואילך."]]],[2000480531,"<b>כי</b> הנה יש ביראה כמה בחי' יש יראה תתאה ויראה עילאה<sup data-n=\"5660\">102</sup> שהוא יראה בושת יראת הרוממות שמתבושש מהקב\"ה כמו עד\"מ א' שמתבושש מאדם גדול ולא שעושה כן (בל\"א גימאכטע זאך) אלא שבאמת כן שהוא מתבושש באמת, כך יש למעלה יראה בושת שמתבושש מגדולתו ית', וכמו שיש במ\"ה בחי' ביטול כמה מדרגות שיש ביטול היש, לכאורה צ\"ל כיון שהוא בביטול הוא יודע שאין שום מציאות חוץ מאתו ית' ואיך הוא מציאות ודבר נפרד שהוא מציאות היש לכאורה זהו שני הפכים, אך באמת הוא בטל לגבי ית' רק שהוא מציאות היש מפני שזהו כח ההסתר מא\"ס אכן אתה אל מסתתר<sup data-n=\"5661\">103</sup> ע\"כ הוא מציאות היש מ\"מ הוא בטל, ויש ביטול אמיתי, ויש עוד בחי' ופלגשו שמה ראומה פי' ראו מה<sup data-n=\"5662\">104</sup>, אם הוא אינו בטל אינו שייך לקרות מ\"ה אלא צ\"ל שהוא בבחי' ביטול רק שברצונו שיראו הביטול שלו איך שהוא בטל וזהו פי' ראו מ\"ה הגם שהוא מה מ\"מ זהו בבחי' ראו שרוצה שיראו איך שהוא בטל, מזה נמשך כח בסט\"א כי אתה מחי' את כולם<sup data-n=\"5663\">105</sup> שגם הם מקבלים חיות ובאם לאו לא יתקיימו אלא שגם הם צריכים להיות בביטול רק שהביטול שלהם הוא בבחי' ראו מ\"ה שרוצים שיראו הביטול שלהם, כן יש ביראה ג\"כ כמה מדרגות יש יראה תתאה ויש בחי' יראה עילאה ויש בחי' ותהי יראתם אותי כמצות אנשים מלומדה<sup data-n=\"5664\">106</sup> והיינו כמו בחי' ראו מ\"ה, וזהו דכתי' ועתה מה ה' דורש מאתך כ\"א הצנע לכת עם ה' אלקיך<sup data-n=\"5665\">107</sup>, פי' שצריך להיות בבחי' הצנע לכת הגם שהולך בדרך תומ\"צ ומע\"ט הליכות עולם לו<sup data-n=\"5666\">108</sup> והוא ירא מאלקים מ\"מ בחיצוני' שלא נראה שיהי' שוה עם כל בני אדם, כי יש אהבה ויראה בולטת שאז א\"ל<sup data-n=\"5667\">109</sup> שיפול, אבל כאשר הצנע לכת שאינו נראה כלל שבחיצוני' הוא שוה עם כל בני אדם ובפנימי' הוא בטל בתכלית מתוך פנימי' נקודת לבבו אז נתקיים האהוי\"ר כו'.\n<b>אך</b> כדי לבוא לבחי' זו הוא ע\"י ענווה כי ענווה גדולה מכולם<sup data-n=\"5668\">110</sup> כדאיתא בירושלמי מה שעשה החכמה<sup data-n=\"5669\">111</sup> עטרה לראשה עשה ענווה עקב לשוליתי' פי' יראה תתאה הוא בחי' מל' ויראה עילאה הוא בחי' ת\"ת וזהו עטרה, עוד א\"ל עטרה על ראשה פי' שיש",[["5660","102","<b>יראה תתאה ויראה עילאה</b>: ראה גם תניא פמ\"ג. סידור הערה לתיקון חצות קנא, ג ואילך."],["5661","103","<b>אכן אתה אל מסתתר</b>: ישעי' מה, טו. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אי' בירושלמי ובמדרש נביאים וכתובים ובהערה 33."],["5662","104","<b>ופלגשו שמה ראומה. . ראו מה</b>: וירא כב, כד [ושם: ושמה]. ראה הנסמן בלקו\"ת בהר מג, א. מאמרי אדה\"א דברים ח\"ד ע' א'תצג. וש\"נ (ובהערה שם בשם הבעש\"ט והמגיד). שעה\"י קמא, א ובהערה 16. סה\"מ תרל\"ג ח\"ב ע' תיד. וש\"נ. פלח הרמון בהר ע' תא בשם המגיד. וש\"נ. ולהעיר מתוספות השלם וירא שם."],["5663","105","<b>אתה מחי' את כולם</b>: נחמי' ט, ו."],["5664","106","<b>ותהי יראתם אותי כמצות אנשים מלומדה</b>: ישעי' כט, יג [ושם מצות]. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אי' בירושלמי ובמדרש נביאים וכתובים הערה 12."],["5665","107","<b>ועתה מה ה'. . הצנע. . ה' אלקיך</b>: מיכה ו, ח [ושם: ומה ה'. . כ\"א. . והצנע. . עם אלקיך[ednref_333_ד]]."],["5666","108","<b>הליכות עולם לו</b>: חבקוק ג, ו."],["5667","109","<b>א\"ל</b>: אפשר להיות."],["5668","110","<b>ענווה גדולה מכולם</b>: ע\"ז כ, ב."],["5669","111","<b>כדאיתא בירושלמי מה שעשה החכמה</b>: ראה שם שבת פ\"א, סה\"ג.\n\n[edn_333_ד] להעיר ממכות כד, א. ”היום יום\" ג'־ ח' תשרי [ושם: ה' אלקיך. הוי' אלקיך]."]]],[2000480532,"ראש וראשון וראשית ועטרה על ראשה היינו בחי' ח\"ס דא\"א ומה שעשה החכמה עטרה עשה ענווה עקב לשוליתי' פי' שוליתי' הוא מנעל<sup data-n=\"5670\">112</sup> ונעל וענווה הוא עקב למנעל, כי ענין ענווה היינו שהוא בטל בתכלי' וע\"כ אינו תופס מקום אצלו אם זה אומר כן וזה אומר כן מפני שהוא עניו שהוא בטל בתכלית כמו שמצינו אפי' בצדיקים הגדולים שדוד המלך אמר אנכי תולעת ולא איש<sup data-n=\"5671\">113</sup> כמו שהתולעת הוא מרכיב<sup data-n=\"5672\">115</sup> בפה<sup data-n=\"5673\">114</sup> כך אמר<sup data-n=\"5674\">116</sup> אין כחו אלא בפה שכל השירות והתשבחות שלו הוא בפה ע\"כ אמר אנכי תולעת ולא איש, אך דוד הי' מרכבה רק לבחי' מל'<sup data-n=\"5675\">117</sup>, וכן אפי' במשה רבינו אנו מצינו שהי' עניו כמ\"ש והאיש משה עניו מאד<sup data-n=\"5676\">118</sup>, וזהו ערומים בדעת כאדה\"ר מ\"מ נמשכים אחריך כבהמה כמבואר בתני' שהכל כפתי' נגדו<sup data-n=\"5677\">119</sup> כמו שארז\"ל פתי יאמין לכל דברים<sup data-n=\"5678\">120</sup> זה משה<sup data-n=\"5679\">121</sup> לכאורה הלא משה הי' רבן של כל הנביאים<sup data-n=\"5680\">122</sup>, כל הנביאים נתנבאו בכה<sup data-n=\"5681\">123</sup> ומשה נתנבא בזה אספקלרי' המאירה<sup data-n=\"5682\">124</sup>, ואיך נק' פתי, אלא מפני שלגבי א\"ס עצמותו הכל כפתים נגדו, וזהו ערומים בדעת כאדה\"ר ונמשכים אחריך כבהמה שהוא בטל בתכלית, כי האמת אפי' ענין לאשתאבא בגופא דמלכא זהו ג\"כ בחי' רצון שרוצה בדבר מה וצ\"ל שגם זה לא ירצה שאינו רוצה בשום דבר וזהו\"ע נמשכים אחריך כבהמה שזהו\"ע עניו, ועי\"ז א\"ל<sup data-n=\"5683\">125</sup> לבחי' ערום ביראה שהוא בחי' יראה עילאה.\n<b>ועפ\"ז</b> יובן מה שארז\"ל נטל הקב\"ה שיחתן של אבות<sup data-n=\"5684\">126</sup>, פי' שיחתן היינו תפלה כמ\"ש ויצא יצחק לשוח בשדה<sup data-n=\"5685\">127</sup> וכן מפרש השוחה לשחות<sup data-n=\"5686\">*128</sup>, ועשאן",[["5670","112","<b>שוליתי' הוא מנעל</b>: ראה קרבן העדה שם."],["5671","113","<b>אנכי תולעת ולא איש</b>: תהלים כב, ז[ednref_334_ה]."],["5672","115","<b>מרכיב</b>: אוצ\"ל: מרקיב. ראה גם לקו\"ת שם נז, ב."],["5673","114","<b>שהתולעת הוא מרכיב בפה</b>: ראה מדרש תהלים שם. תנחומא בשלח ט. זהר וישלח קעח, א. תרומה קלט, א. לקו\"ת חוקת נז, א. נח, סע\"ד."],["5674","116","<b>כך אמר</b>: וכ\"ה בהנחה שני' כאן. בהנ\"ל הערה 114 על כנס\"י. וראה בלקו\"ת שם נז, א: וכן. . גבי דוד. . כתולעת. וראה שם נז, ב לימוד התורה. . ואנכי תולעת."],["5675","117","<b>דוד הי' מרכבה. . מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["5676","118","<b>והאיש משה עניו מאד</b>: בהעלותך יב, ג."],["5677","119","<b>כמבואר בתני' שהכל כפתי' נגדו</b>: פי\"ח. ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 50."],["5678","120","<b>פתי יאמין לכל דברים</b>: משלי יד, טו [ושם: דבר]."],["5679","121","<b>פתי יאמין. . זה משה</b>: שמו\"ר רפ\"ג. ראה קיצורים והערות לתניא ע' קא ואילך. סה\"מ תרל\"ג ח\"א ס\"ע קנא ואילך. המשך וככה תרל\"ז פמ\"ב (ע' נט)."],["5680","122","<b>משה הי' רבן של כל הנביאים</b>: שמו\"ר פכ\"א, ד."],["5681","123","<b>כל הנביאים נתנבאו בכה</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. תו\"ח בשלח ח\"א קמד, ב הערה 29."],["5682","124","<b>משה. . אספקלרי' המאירה</b>: יבמות מט, ב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם ספ\"א. תו\"ח ח\"ש קלא, ד."],["5683","125","<b>א\"ל</b>: אפשר להגיע."],["5684","126","<b>נטל הקב\"ה שיחתן של אבות</b>: ב\"ר פ\"ע, ו (התחלת המדרש שהובא לעיל בריש המאמר)."],["5685","127","<b>שיחתן. . ויצא יצחק לשוח בשדה</b>: ח\"ש כד, סג. ראה ברכות כו, ב. (לעיל בחלק המאמרים) מאמר ד\"ה וכל שיח השדה בתחילתו. וש\"נ."],["5686","*128","<b>מפרש השוחה לשחות</b>: ישעי' כה, יא [ושם: יפרש]. ראה גם תו\"א ח\"ש יז, ב. לקו\"ת חוקת סו, א.\n\n[edn_334_ה] ושם: ואנכי — ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אשריכם זורעי על כל מים ובהערה 114."]]]]});
